import{n as e,r as t}from"./rolldown-runtime-CNOWq4Kh.js";var n=t({default:()=>r}),r;function i(){return(i=e((()=>{r={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`Елементи керування середовищем виконання ACP для ввімкнення диспетчеризації, вибору бекендів, обмеження дозволених цільових агентів і вибору способу відображення потокових ходів.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Дозволені агенти ACP`},help:{"v1-f2mw0d-3a":`Список ідентифікаторів цільових агентів ACP, дозволених для сеансів середовища виконання ACP. Порожній список означає відсутність додаткових обмежень.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`Бекенд ACP`},help:{"v1-1s1l6bz-2v":`Ідентифікатор стандартного бекенду середовища виконання ACP (наприклад: acpx). Має відповідати зареєстрованому бекенду плагіна середовища виконання ACP.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`Стандартний агент ACP`},help:{"v1-7donnu-2c":`Резервний ідентифікатор цільового агента ACP, який використовується, коли під час запуску ACP ціль не вказано явно.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`Диспетчеризацію ACP увімкнено`},help:{"v1-1ug9t9m-3w":`Незалежний перемикач диспетчеризації ходів сеансів ACP (стандартне значення: true). Установіть false, щоб команди ACP залишалися доступними, а виконання ходів ACP було заблоковано.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP увімкнено`},help:{"v1-1uonl1v-2a":`Глобальний перемикач функцій ACP. Залишайте вимкненим, доки не налаштовано середовище виконання та політику ACP.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`Резервні бекенди ACP`},help:{"v1-1wvdifq-5m":`Упорядкований список ідентифікаторів резервних бекендів ACP, які перевіряються, коли основний бекенд завершується помилкою UNAVAILABLE (наприклад, через обмеження частоти запитів / вичерпання квоти). Кожен запис має відповідати зареєстрованому бекенду плагіна середовища виконання ACP.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Команда встановлення середовища виконання ACP`},help:{"v1-1jjuv9m-39":"Необов’язкова команда встановлення/налаштування для оператора, яку показують `/acp install` і `/acp doctor`, якщо підключення бекенду ACP не налаштовано."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`Потік ACP`},help:{"v1-1bka5p-2v":`Параметри потокового відображення ACP: розмір фрагментів, видимість метаданих і поведінка доставки без дублікатів.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Режим доставки потоку ACP`},help:{"v1-19gdmx1-3s":`Спосіб доставки ACP: live передає відображувані дані поступово, а final_only буферизує всі відображувані дані ACP до подій завершення ходу.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Пригнічення повторів у потоці ACP`},help:{"v1-manh32-3d":`Якщо встановлено true (за замовчуванням), повторювані рядки відображення стану/інструментів ACP у межах ходу приховуються, а необроблені події ACP залишаються незмінними.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Видимість тегів потоку ACP`},help:{"v1-1ybhx22-34":`Перевизначення видимості для кожного sessionUpdate у відображенні ACP (наприклад, usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Агенти`},help:{"v1-2rc4v8-55":`Кореневий розділ конфігурації середовища виконання агентів. Сусідні розділи кореневого рівня визначають інфраструктуру та спільні для агентів значення за замовчуванням; agents.defaults визначає поведінку циклу агента; записи окремих агентів можуть перевизначати обидва набори параметрів, де це підтримується.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Типові налаштування агента`},help:{"v1-1af7k5b-5a":`Спільні налаштування за замовчуванням, які успадковують агенти, якщо їх не перевизначено для окремого запису в agents.entries. Використовуйте налаштування за замовчуванням, щоб забезпечити узгоджену базову поведінку та зменшити дублювання конфігурації для кожного агента.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Ціль успадкування автентифікації`},help:{"v1-2d16wl-2x":`Власник успадкованого сховища облікових даних для забезпечення сумісності під час оновлення, доки облікові дані не буде перенесено окремо для кожного агента.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Власник успадкування автентифікації`},help:{"v1-1a1s7nm-4s":`Агент, чиє застаріле сховище облікових даних залишається джерелом успадкування після вилучення маркера за замовчуванням. Записується автоматично під час оновлення, якщо попереднім власником був не main.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Максимум символів початкового завантаження`},help:{"v1-drlo3i-37":`Максимальна кількість символів із кожного файлу початкового завантаження робочого простору, що додаються до системного промпту перед обрізанням (за замовчуванням: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Загальний максимум символів початкового завантаження`},help:{"v1-1evwsjb-2c":`Максимальна загальна кількість символів з усіх доданих файлів початкового завантаження робочого простору (за замовчуванням: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Ущільнення`},help:{"v1-1qxdwz8-5p":`Поведінка ущільнення, коли контекст наближається до ліміту токенів, зокрема стратегія та збереження пам’яті перед ущільненням. Використовуйте це, коли тривалим сеансам потрібна стабільна безперервність за умов обмеженого вікна контексту.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Вбудоване автоматичне ущільнення`},help:{"v1-1et7vwu-5l":`Увімкнути вбудоване проактивне автоматичне ущільнення (типово: true). Установіть false, щоб зупинити вбудоване ущільнення за пороговим значенням, зберігши відновлення після переповнення OpenClaw, попереднє ущільнення та ручну команду /compact.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Політика збереження ідентифікаторів під час ущільнення`},help:{"v1-hby01l-4l":`Політика збереження ідентифікаторів у підсумках ущільнення: "strict" додає на початку вбудовані вказівки щодо збереження непрозорих ідентифікаторів (типово), а "off" вимикає цей префікс.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Збереження останніх токенів під час ущільнення`},help:{"v1-tgysub-5h":`Мінімальна кількість токенів, що зберігається з найновішого вікна розмови під час ущільнення. Використовуйте вищі значення, щоб зберегти безперервність поточного контексту, і нижчі — щоб зберегти більше давнішої історії.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-476m1y-11":`Пороговий розмір активного чату для ущільнення`},help:{"v1-7p9ney-ah":`Поріг у байтах для попереднього локального ущільнення у вбудованому середовищі виконання (байти або рядки на кшталт "20mb"). Для Codex app-server натомість обмежує початкову історію нової гілки: лише одна спроба створення зведення на боці хоста, і лише коли історію без зведення було б пропущено; ніколи під час звичайних ходів або після нативної команди /compact. Установіть 0 або залиште незаданим, щоб вимкнути. Нативні запобіжні обмеження розміру розгортання та кількості токенів залишаються незмінними.`}},"agents%2Edefaults%2Ecompaction%2EmaxSummaryChars":{label:{"v1-18p81ru-x":`Максимальна кількість символів у підсумку стиснення`},help:{"v1-em0nj5-8b":`Максимальна кількість символів у збереженому підсумку стиснення на боці клієнта (за замовчуванням: 16000; діапазон: 1000–200000). Більші підсумки зберігають більше згенерованого контексту, але збільшують вартість його повторного використання в наступних запитах. Ліміт токенів активної моделі може вимагати меншого підсумку. Не керує вбудованим стисненням на боці провайдера.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Збереження пам’яті перед ущільненням`},help:{"v1-1xbzc1i-6t":`Налаштування збереження пам’яті перед ущільненням, які запускають запис у пам’ять агентом за допомогою активної моделі сеансу та її звичайного ланцюжка резервних моделей перед значним ущільненням. Залишайте ввімкненими для тривалих сеансів, щоб важливий контекст зберігався перед інтенсивним скороченням.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Збереження пам’яті перед ущільненням увімкнено`},help:{"v1-9xllgp-5o":`Вмикає збереження пам’яті перед ущільненням, перш ніж середовище виконання суттєвіше скоротить історію при наближенні до ліміту токенів. Залишайте ввімкненим, якщо не маєте наміру вимкнути побічні операції з пам’яттю в середовищах з обмеженими ресурсами.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-1mr3mj1-17":`Пороговий розмір чату для збереження пам’яті перед ущільненням`},help:{"v1-pihai2-8y":`Примусово зберігає пам’ять перед ущільненням, коли видима моделі історія чату досягає цього порога (у байтах або у вигляді рядка, наприклад "2mb"). Після ущільнення враховуються збережена кінцева частина історії та подальші обміни повідомленнями, а не відкинута історія. Використовуйте цей параметр, щоб запобігти зависанням під час тривалих сеансів, навіть коли лічильники токенів застарілі; установіть 0, щоб вимкнути.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`М’який поріг збереження пам’яті перед ущільненням`},help:{"v1-1dqo2l1-5c":`Порогова відстань до ущільнення (у токенах), за якої запускається збереження пам’яті перед ущільненням. Використовуйте пороги з ранішим спрацюванням для надійнішого збереження або пороги, ближчі до ущільнення, для меншої частоти збереження.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Попередня перевірка ущільнення під час ходу`},help:{"v1-12ud1gw-6c":`Необов’язковий поріг оцінюваного навантаження між циклами викликів інструментів із використанням резерву для ущільнення. Підтримання порога за вимірюваннями провайдера та перевірка допустимості за жорстким обмеженням контекстного вікна виконуються незалежно, повторно використовуючи безпечне обрізання або відновлення шляхом ущільнення.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Попередню перевірку ущільнення під час ходу ввімкнено`},help:{"v1-1or5cwa-57":`Увімкнути необов’язковий поріг оцінюваного навантаження між циклами викликів інструментів. Типове значення: false. Підтримання порога за вимірюваннями та перевірка жорсткого обмеження контекстного вікна залишаються активними, навіть коли цей параметр вимкнено.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Режим ущільнення`},help:{"v1-1unahwc-76":`Режим стратегії ущільнення: "safeguard" (фактичний типовий режим, якщо значення не задано) застосовує захисні механізми для збереження недавнього контексту, а "default" використовує базове підсумовування без них. Установлюйте "default", лише якщо підсумовування в режимі safeguard спричиняє проблеми з вашим провайдером.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Перевизначення моделі ущільнення`},help:{"v1-cfeys9-6q":`Необов’язкове значення provider/model або налаштований псевдонім без префікса, що використовується лише для підсумовування під час ущільнення. Псевдоніми без префікса розпізнаються перед надсиланням запиту; якщо налаштований буквальний ідентифікатор моделі збігається з псевдонімом, пріоритет має ідентифікатор. Залиште незаданим, щоб і надалі використовувати основну модель агента.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Сповіщення користувача про ущільнення`},help:{"v1-lvymm8-bv":`Якщо ввімкнено, надсилає користувачеві короткі сповіщення про обслуговування контексту: коли ущільнення починається та завершується (наприклад, «🧹 Ущільнення контексту...» та «🧹 Ущільнення завершено»), а також коли спроби збереження пам’яті перед ущільненням вичерпано й формування відповіді продовжується в погіршеному стані (наприклад, «⚠️ Тимчасовий збій обслуговування пам’яті; продовжуємо відповідь.»). Типово вимкнено, щоб обслуговування контексту відбувалося непомітно й не відволікало.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Розділи контексту після ущільнення`},help:{"v1-1n0ln2u-5f":`Назви розділів H2/H3 у AGENTS.md, які за бажанням можна повторно додавати після ущільнення. Залиште незаданим або задайте [], щоб вимкнути повторне додавання. Явно задайте ["Session Startup", "Red Lines"], щоб увімкнути попередню типову пару.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Синхронізація індексу після ущільнення`},help:{"v1-ekpjeq-6l":`Керує режимом повторного індексування пам’яті сеансу після ущільнення: "off", "async" або "await" (типово: "async"). Використовуйте "await" для максимальної актуальності, "async" для меншої затримки ущільнення, а "off" — лише коли синхронізація пам’яті сеансу виконується іншим способом.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Провайдер ущільнення`},help:{"v1-2zoy3b-7v":`Ідентифікатор зареєстрованого плагіна постачальника ущільнення, що використовується для підсумовування. Якщо його задано й постачальника зареєстровано, замість вбудованого запиту на підсумовування викликається його метод summarize(). У разі збою постачальника використовується вбудований механізм. Залиште незаданим, щоб використовувати стандартне вбудоване підсумовування.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Контроль якості ущільнення`},help:{"v1-u9ognp-4k":`Налаштування повторних спроб перевірки якості підсумків ущільнення в режимі safeguard. У режимі safeguard цю функцію ввімкнено за замовчуванням; установіть enabled: false, щоб пропустити перевірки підсумків і повторне генерування.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Контроль якості ущільнення ввімкнено`},help:{"v1-1xk2vt3-36":`Вмикає перевірки якості підсумків і повторні спроби генерування для ущільнення в режимі safeguard. За замовчуванням: true в режимі safeguard.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Максимальна кількість повторних спроб контролю якості ущільнення`},help:{"v1-n7l46y-3y":`Максимальна кількість повторних спроб генерування після невдалої перевірки якості підсумку в режимі safeguard. Використовуйте невеликі значення, щоб обмежити додаткову затримку та витрати токенів.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Збереження останніх обмінів репліками під час ущільнення`},help:{"v1-y34ihi-5k":`Кількість останніх обмінів репліками між користувачем і асистентом, які зберігаються дослівно й не включаються до підсумку в режимі safeguard (за замовчуванням: 3). Збільште це значення, щоб зберегти точний контекст нещодавнього діалогу, або зменште його для максимальної економії завдяки ущільненню.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Рівень міркування під час ущільнення`},help:{"v1-1vafgaw-g1":`Рівень міркування, що використовується лише для вбудованих зведень ущільнення OpenClaw: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" або "inherit". За замовчуванням використовується налаштування ущільнення від провайдера, а за його відсутності — "low"; нативний локальний Ollama віддає перевагу "off". Установіть "inherit", щоб повторно використати рівень сеансу. Явні налаштування перевизначають стандартні значення провайдера, а вибраний рівень обмежується можливостями фактичної моделі та середовища виконання ущільнення. Нативне ущільнення Codex app-server ігнорує це налаштування, оскільки його запит compact не підтримує перевизначення рівня міркування для окремої операції, і OpenClaw записує попередження в журнал.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Час очікування ущільнення (секунди)`},help:{"v1-p0ymcy-c4":`Кількість секунд, протягом яких запит до вбудованої моделі ущільнення може залишатися без поступу (типово: 180). Початок кожного запиту й кожен вихідний токен у потоці поновлюють цей інтервал, тому повільний запит, який продовжує передавати дані, не переривається; усе ущільнення припиняється після 10 інтервалів. Ущільнення під керуванням плагіна отримує один інтервал, якщо рушій явно не оголошує onProgress в info.acceptedHostParams і не повідомляє про поступ; діє те саме обмеження у 10 інтервалів.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Додавання контексту`},help:{"v1-u18x0-7u":`Керує додаванням файлів початкового налаштування робочого простору до контексту у вбудованому середовищі виконання: "always" використовує звичайне додавання (типово), "continuation-skip" пропускає відповідні наступні кроки після зафіксованого кроку з повним початковим налаштуванням, а "never" вимикає додавання. Не керує підготовкою запитів через CLI.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Стандартні обмеження контексту`},help:{"v1-1coeez8-5d":`Цільові стандартні ліміти контексту для кожного агента, що застосовуються до вибраних великих уривків і доданих блоків промпту. Використовуйте їх, щоб налаштувати обмежені обсяги читання та додавання, не відкриваючи знову жодних шляхів виклику без обмежень.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Стандартна максимальна кількість символів memory_get`},help:{"v1-1qb40qv-4v":`Максимальна кількість символів за замовчуванням, яку повертає memory_get до додавання метаданих про обрізання та повідомлення про продовження. Збільште значення, щоб наблизитися до більших уривків, як раніше, але залишайте його обмеженим.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Максимум символів після ущільнення за замовчуванням`},help:{"v1-64qo8g-5r":`Максимальна кількість символів за замовчуванням, що зберігаються з AGENTS.md під час додавання оновленого контексту після ущільнення. Зменште це значення, щоб знизити витрати на відновлення після ущільнення, або збільште його для агентів, яким потрібні докладніші початкові настанови.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Робочий каталог`},help:{"v1-1y8wlxn-6a":`Робочий каталог для запусків формування відповідей агента, окремий від файлів початкового налаштування робочого простору та пам’яті. Значення cwd для конкретного агента та cwd, задане під час створення сеансу, мають пріоритет. Підтримує ~ і відносні шляхи; окремий cwd потребує запуску поза пісочницею.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Модель прийняття рішень`},help:{"v1-7nd7ze-64":`Необов’язковий постачальник/модель для типізованих варіантів вибору, оцінок і ймовірностей булевих значень. Якщо значення не задано або воно порожнє, виклики для прийняття рішень вимкнено. Плагіни з підтримкою цієї функції надсилають цьому постачальнику обмежений обсяг даних завдання; моделі чату й допоміжні моделі залишаються без змін.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`Вбудований OpenClaw`},help:{"v1-1keek32-3k":`Засоби посилення безпеки вбудованого виконавця OpenClaw, що визначають довіру до локальних налаштувань агента в робочому просторі та їх застосування в сеансах OpenClaw.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Резервне перемикання через політику кібербезпеки`},help:{"v1-pl298d-4c":`Автоматична ескалація до Daybreak у межах тієї самої моделі для відмов за кіберполітикою OpenAI, які можна безпечно повторити у вбудованому середовищі виконання, з дотриманням наявних перевірок доступу та політик.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Період очікування резервного перемикання через політику кібербезпеки`},help:{"v1-1hhmb1o-2l":`Як довго в поточному сеансі пропускатимуться спроби доступу до Daybreak для активної моделі, якщо цей доступ недоступний.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Режим резервного перемикання через політику кібербезпеки`},help:{"v1-rzsd2b-2h":`Увімкнути автоматичну ескалацію ("auto", за замовчуванням) або залишити відмови постачальника остаточними ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Контракт виконання вбудованого OpenClaw`},help:{"v1-1fch2ig-66":`Контракт виконання вбудованого OpenClaw: "default" зберігає стандартну поведінку виконавця, тоді як "strict-agentic" вмикає структуроване відстеження плану та невидиме для користувача відновлення кроків для підтримуваних запусків OpenAI/OpenAI Codex сімейства GPT-5.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Політика налаштувань проєкту вбудованого OpenClaw`},help:{"v1-fdyy04-65":'Як вбудований OpenClaw обробляє локальний файл робочого простору `.openclaw/settings.json`: "sanitize" (за замовчуванням) видаляє shellPath/shellCommandPrefix, "ignore" повністю вимикає налаштування проєкту, а "trusted" застосовує їх без змін.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Експериментальні прапорці агента`},help:{"v1-cvv5cl-2w":`Експериментальні прапорці типових налаштувань агента. Залишайте їх вимкненими, якщо не тестуєте попередню версію функціональності навмисно.`}},"agents%2Edefaults%2Eexperimental%2EdecisionAssistance":{label:{"v1-1tepbyi-y":`Допомога в ухваленні рішень (експериментальна)`},help:{"v1-1fmo3r9-ew":`Глобальна згода на експериментальну допомогу від моделі Decision, налаштованої для агента-власника (за замовчуванням: false; потрібно явно встановити true). Застосовувана decisionModel може успадковуватися з глобальних налаштувань за замовчуванням або вибиратися окремо для кожного агента; порожнє значення для окремого агента вимикає допомогу. У підтримуваних сценаріях використання вибрані дані можуть надсилатися цьому постачальнику, і за це може стягуватися плата. Підтримувані сценарії використання, налаштування й обробку даних описано в документації щодо допомоги Decision. Цей параметр не обмежує явні виклики decision_evaluate, не вибирає постачальників і не надає дозволів на дії.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Увімкнути полегшений режим локальної моделі (експериментальний)`},help:{"v1-gj06u6-7b":`Розширене налаштування для усунення несправностей, яке обмежує необов’язкові інструменти, як-от browser, automations і message. Типово вимкнено; підтримувані локальні середовища виконання використовують автоматичний пошук інструментів без цього обмеження. Явні дозволи на використання інструментів і обов’язкові інструменти доставки зберігаються.`}},"agents%2Edefaults%2Eexperimental%2EusageRankedToolIndex":{label:{"v1-ndslef-12":`Індекс інструментів із ранжуванням за використанням (експериментальна функція)`},help:{"v1-1jpzjov-bq":`Увімкнути індекси каталогів інструментів Code Mode, Tool Search і MCP у промптах із ранжуванням за використанням у вбудованому середовищі виконання OpenClaw (типово: false). Зберігає лише ідентифікатори інструментів, оцінки зі згасанням у часі та часові позначки у сховищі агента, що належить оператору, протягом 90 днів; сеанси інкогніто не враховуються. Рейтинги залишаються незмінними до межі префікса промпту. Не змінює дозволи інструментів або Codex. Переглядайте дані, імпортуйте історію використання або скидайте їх за допомогою openclaw tools usage.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Швидкий режим агента за замовчуванням`},help:{"v1-6q8gx8-3c":`Типова політика швидкого режиму для циклу агента ("auto", "ultrafast", true або false). Налаштування окремих агентів перевизначають її.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Максимальна затримка для імітації людини (мс)`},help:{"v1-vnmvli-1m":`Максимальна затримка в мс для користувацького налаштування humanDelay (типово: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Мінімальна затримка для імітації людини (мс)`},help:{"v1-5nrtr5-1l":`Мінімальна затримка в мс для користувацького налаштування humanDelay (типово: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Режим затримки для імітації людини`},help:{"v1-k7hyg3-1n":`Тип затримки для відповідей блоками ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Максимальний розмір зображення (пкс)`},help:{"v1-1j31o2j-2s":`Максимальна довжина сторони зображення в пікселях під час очищення даних зображень у чаті та результатах інструментів (типово: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Резервні моделі для зображень`},help:{"v1-1kgx5i9-1b":`Упорядкований список резервних моделей для зображень (provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Модель для зображень`},help:{"v1-dstqyh-2c":`Необов’язкова модель для зображень (provider/model), що використовується, коли основна модель не підтримує зображення на вході.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Якість зображення`},help:{"v1-1uyxc5s-6u":`Налаштування стиснення медіаданих для інструмента роботи із зображеннями: "auto" враховує обмеження постачальника/моделі та кількість зображень, "efficient" заощаджує токени й байти, "balanced" зберігає поточний баланс, а "high" зберігає більше деталей на знімках екрана та зображеннях документів.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Резервні моделі генерації зображень`},help:{"v1-oljfk4-1m":`Упорядкований список резервних моделей генерації зображень (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Модель генерації зображень`},help:{"v1-g4yw0h-2o":`Необов’язкова модель генерації зображень (provider/model), яку використовує спільна функція генерації зображень.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Час очікування генерації зображень (мс)`},help:{"v1-9yesfj-31":`Час очікування відповіді постачальника за замовчуванням у мілісекундах для викликів image_generate. Значення timeoutMs для окремого виклику перевизначає це налаштування.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Резервні моделі генерації музики`},help:{"v1-wyg9xe-1m":`Упорядкований список резервних моделей генерації музики (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Модель генерації музики`},help:{"v1-xs1e2h-2o":`Необов’язкова модель генерації музики (provider/model), яку використовує спільна функція генерації музики.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Резервні моделі генерації відео`},help:{"v1-wpbf1e-1m":`Упорядкований список резервних моделей генерації відео (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Модель генерації відео`},help:{"v1-hfmlbl-2o":`Необов’язкова модель генерації відео (provider/model), яку використовує спільна функція генерації відео.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Час очікування генерації відео (мс)`},help:{"v1-1bqj80s-4i":`Стандартний час очікування запиту до провайдера в мілісекундах для викликів video_generate. Параметр timeoutMs окремого виклику має пріоритет над цим значенням, а це значення — над стандартними значеннями провайдера.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Резервні моделі`},help:{"v1-t4djq2-24":`Упорядкований список резервних моделей (provider/model). Використовуються, коли основна модель не працює.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Основна модель`},help:{"v1-1i8a1v4-v":`Основна модель (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Політика моделей`},help:{"v1-z0txb7-2e":`Явна політика перевизначення моделі. Не вказуйте її або залиште allow порожнім, щоб дозволити будь-яку модель.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Дозволені моделі`},help:{"v1-1vy0b57-5c":`Дозволені посилання для перевизначення моделі. Підтримуються псевдоніми, повні посилання "provider/model" і шаблони префіксів із символом підстановки в кінці, як-от "openai/*", "clawrouter/anthropic/*" або "openai/gpt-*". Порожнє значення дозволяє будь-яку модель.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Моделі`},help:{"v1-13cvq23-4i":`Налаштований каталог моделей і параметри для кожної моделі. Записи містять псевдоніми, параметри, метадані середовища виконання та перевизначення Code Mode; вони не обмежують перевизначення моделі.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Середовище виконання моделі типового агента`},help:{"v1-6km9kx-41":`Необов’язкова політика середовища виконання для окремої моделі типового агента. Використовуйте її для винятків, що стосуються конкретних моделей, замість налаштування середовища виконання для всього агента.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`Ідентифікатор середовища виконання моделі типового агента`},help:{"v1-1co96w7-4a":`Ідентифікатор середовища виконання моделі типового агента: "openclaw", "auto", зареєстрований ідентифікатор виконавчої оболонки плагіна, як-от "codex", або підтримуваний псевдонім бекенду CLI, як-от "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Режим коду`},help:{"v1-rsdl5o-6x":`Режим коду OpenClaw для цієї конкретної пари постачальник/модель: «Увімкнено» примусово вмикає його, «Вимкнено» вимикає, а «За замовчуванням» успадковує tools.codeMode.enabled. Налаштування активації для конкретного агента мають пріоритет. Це не змінює вибране середовище виконання або вбудований режим коду Codex.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Область застосування вибору моделі`},help:{"v1-sj8owq-bl":`Область застосування для команд чату й оновлень моделі сеансу Gateway без явно вказаної області: "session" (за замовчуванням) змінює лише поточний сеанс, "agent" також оновлює основну модель цього агента, а "global" також оновлює спільну резервну модель agents.defaults.model. Явно вказані прапорці області застосування мають пріоритет; зміна налаштованих типових значень потребує прав власника або адміністратора. Засоби вибору через зворотні виклики Telegram і вбудований локальний TUI діють лише в межах сеансу.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Максимальний розмір PDF (МБ)`},help:{"v1-1uig1dr-1u":`Максимальний розмір PDF-файлу в мегабайтах для інструмента PDF (за замовчуванням: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Максимальна кількість сторінок PDF`},help:{"v1-11na7hp-1y":`Максимальна кількість сторінок PDF для обробки інструментом PDF (за замовчуванням: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Резервні моделі PDF`},help:{"v1-89ebd8-19":`Упорядкований список резервних моделей PDF (provider/model).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`Модель PDF`},help:{"v1-2ktkxt-2y":`Необов’язкова модель PDF (provider/model) для інструмента аналізу PDF. За замовчуванням використовується imageModel, а потім — модель сеансу.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Кореневий каталог репозиторію`},help:{"v1-j3sh74-2h":`Необов’язковий кореневий каталог репозиторію, що відображається в рядку середовища виконання системного промпту (перевизначає автоматичне визначення).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Діапазон вихідних портів CDP браузера в пісочниці`},help:{"v1-1jkowdc-2b":`Необов’язковий список дозволених CIDR для вхідного трафіку CDP на межі контейнера (наприклад, 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Мережа браузера в пісочниці`},help:{"v1-8m74ud-5w":`Мережа Docker для контейнерів браузера в пісочниці (за замовчуванням: openclaw-sandbox-browser). Використовуйте виділену мережу за замовчуванням або власну мостову мережу; "none" не підтримується, оскільки керування браузером потребує опублікованих портів CDP.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Дозволити приєднання до простору імен контейнера Docker у пісочниці`},help:{"v1-qm39de-4c":`НЕБЕЗПЕЧНЕ аварійне перевизначення, що дозволяє мережевий режим Docker container:<id> у пісочниці. Це приєднує до простору імен іншого контейнера та послаблює ізоляцію пісочниці.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`GPU Docker у пісочниці`},help:{"v1-jj0yhw-4k":`Необов’язкове значення для надання Docker доступу до GPU, що передається в --gpus, наприклад "all" або "device=GPU-uuid". Потрібне сумісне середовище виконання на хості, як-от NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Ціль застарілого сховища сеансів`},help:{"v1-1xkej6i-2g":`Власник вилучених з ужитку рядків main-agent і фіксованих застарілих сховищ сеансів для забезпечення сумісності під час оновлення.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Власник застарілого сховища сеансів`},help:{"v1-ommm7e-5w":`Агент, якому належать вилучені з ужитку рядки main-agent або рядки без визначеної області у фіксованому застарілому сховищі сеансів після вилучення маркера за замовчуванням. Записується автоматично під час оновлення, якщо попередній власник не був main або єдиним агентом.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Необов’язковий список дозволених навичок за замовчуванням, який успадковують агенти без заданого agents.entries.*.skills. Не задавайте його, щоб не обмежувати навички; установіть [], щоб агенти, які його успадковують, не мали навичок. Пам’ятайте, що явно задане agents.entries.*.skills замінює цей список за замовчуванням, а не об’єднується з ним.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Пропускати створення файлів початкового налаштування робочого простору`},help:{"v1-kbstgw-5v":`Пропускає автоматичне створення файлів початкового налаштування робочого простору, але не додавання наявних файлів до контексту. Для вбудованого середовища виконання встановіть agents.defaults.contextInjection у "never", щоб вимкнути додавання, якщо це налаштування не перевизначено для окремого агента.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Пропущені необов’язкові файли початкового налаштування`},help:{"v1-1j2z4yj-4c":`Необов’язкові файли початкового налаштування, які не слід створювати в робочих просторах агентів. Допустимі значення: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md приймається, але не має ефекту).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Контекст запуску`},help:{"v1-1ugsihy-5o":`Вступ до першого запиту, який середовище виконання додає для команд "/new" і "/reset" без аргументів. Це налаштування визначає, чи завантажувати останні щоденні файли пам’яті в перший запит заздалегідь, замість того щоб доручати моделі вирішувати, що читати.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Команди для застосування початкового контексту`},help:{"v1-wav4a5-36":`Визначає, які команди скидання без аргументів отримують початковий контекст: додайте "new", "reset" або обидві (за замовчуванням: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Кількість днів щоденної пам’яті в початковому контексті`},help:{"v1-4i5xcm-3p":`Кількість датованих файлів пам’яті для завантаження, відраховуючи назад від сьогодні в налаштованому часовому поясі користувача (за замовчуванням: 2 — за сьогодні та вчора).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Увімкнути початковий контекст`},help:{"v1-1d5vz2u-4i":`Увімкнути вступ із початковим контекстом для скидання сеансу без аргументів (за замовчуванням: true). Вимкніть, щоб використовувати лише запит без щоденної пам’яті, завантаженої середовищем виконання.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Максимальний розмір файлу початкового контексту в байтах`},help:{"v1-11cbian-41":`Максимально дозволена кількість байтів на щоденний файл пам’яті під час формування початкового контексту (за замовчуванням: 16384). Файли, що перевищують цей ліміт безпечного читання, пропускаються.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Максимальна кількість символів файлу початкового контексту`},help:{"v1-10z53s-2u":`Максимальна кількість символів із кожного завантаженого щоденного файлу пам’яті, що зберігаються в початковому вступі (за замовчуванням: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Максимальна загальна кількість символів початкового контексту`},help:{"v1-sf676u-54":`Максимальна загальна кількість символів, що зберігаються з усіх завантажених щоденних файлів пам’яті у вступній частині під час запуску (за замовчуванням: 2800). Після досягнення цього ліміту вміст додаткових файлів у вступній частині обрізається.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Режим делегування субагентам`},help:{"v1-pqewbk-5o":`Рівень наполегливості вказівок щодо делегування субагентам, заданий лише через промпт. За замовчуванням — "prefer" в основному сеансі кожного агента та "suggest" в інших сеансах; "prefer" наполегливо вказує агенту делегувати нетривіальні завдання через sessions_spawn.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Ціль системного агента`},help:{"v1-1wwimo9-34":`Налаштування цілі для фонового виконання запитів до моделей системним агентом OpenClaw і Custodian, а також для окремих операцій читання оператором без заданої області дії.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Власник системного агента`},help:{"v1-15rvt92-8c":`Агент, модель і облікові дані якого використовуються для фонових звернень системного агента та Custodian. Також використовується, коли в models.list, models.authStatus, skills.status, doctor.memory.status або команді CLI infer, яка визначає належну агенту модель чи стан автентифікації, не вказано agentId або --agent; явно заданий у запиті agentId завжди має пріоритет.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Інтервал індикації введення (секунди)`},help:{"v1-1y701ox-42":`Визначає інтервал у секундах між оновленнями, що підтримують активність індикатора введення, для кожного агента. Збільште його, щоб зменшити частоту оновлень у всіх каналах, які підтримують індикацію введення.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Режим індикації введення`},help:{"v1-m2hvpw-3m":`Визначає, коли агенти починають показувати індикатор введення: "never", "instant", "thinking" або "message". Параметр typingMode окремого агента перевизначає це типове значення.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Допоміжна модель`},help:{"v1-1cfea4z-cl":`Необов’язкова дешевша модель (provider/model, псевдонім або { primary, fallbacks }) для коротких внутрішніх завдань, як-от створення заголовків і опис перебігу виконання. Резервні допоміжні моделі використовують ту саму політику повторних спроб, визначення псевдонімів і вибору моделей, що й налаштовані резервні моделі, незалежно від model.fallbacks. Якщо значення не задано, використовується мала модель, оголошена основним постачальником, за її наявності (інакше — основна модель); задайте порожній рядок, щоб вимкнути маршрутизацію до допоміжної моделі.`}},"agents%2Edefaults%2EutilityModel%2Efallbacks":{label:{"v1-rlvlnh-n":`Резервні допоміжні моделі`},help:{"v1-12k3amd-2v":`Упорядкований список резервних допоміжних моделей (provider/model або псевдонім), незалежний від списку резервних моделей для основної моделі.`}},"agents%2Edefaults%2EutilityModel%2Eprimary":{label:{"v1-1rpgua8-l":`Основна допоміжна модель`},help:{"v1-11k8uor-1c":`Основна допоміжна модель (постачальник/модель або псевдонім).`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Резервні голосові моделі`},help:{"v1-faazv4-1b":`Упорядкований список резервних голосових моделей (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Голосова модель`},help:{"v1-1yeh3h4-2t":`Необов’язкова голосова модель (provider/model), що використовується для мовлення, транскрибування та голосових функцій у реальному часі.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Час очікування голосових операцій (мс)`},help:{"v1-1sbergs-32":`Типовий час очікування відповіді на запит до провайдера в мілісекундах для операцій із голосовою моделлю, якщо компонент, що викликає операцію, підтримує обмеження часу очікування.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Робочий простір`},help:{"v1-1u5ipll-5t":`Робочий простір агента за замовчуванням для файлів початкового налаштування та пам’яті. Також використовується як робочий каталог, якщо agents.defaults.cwd не задано. Задайте його явно під час запуску через обгортки, щоб забезпечити узгоджене визначення шляхів.`}},"agents%2Edefaults%2EworkspaceFileMode":{label:{"v1-13trwkt-k":`Права доступу до нових файлів пам’яті`},help:{"v1-11pw0mp-9b":`Права доступу до нових файлів DREAMS.md, MEMORY.md і звітів memory/dreaming, створених memory-core: "0600", "0620", "0640" або "0660". Якщо не задано, зберігається точне значення 0600; налаштовані режими враховують umask хоста, що виконує запис. Наявні файли, щоденна пам’ять, корпус сеансів і приватний стан залишаються без змін. Права проходження каталогів і типові ACL потрібно налаштувати окремо.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Список агентів`},help:{"v1-1e0blk1-5i":`Явний список налаштованих агентів з ідентифікаторами та необов’язковими перевизначеннями моделі, інструментів, ідентичності й робочого простору. Не змінюйте ідентифікатори з часом, щоб прив’язки, схвалення та маршрутизація сеансів залишалися узгодженими.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Застаріле середовище виконання агента`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`Ідентифікатор застарілого середовища виконання агента`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Максимальна кількість символів ініціалізації агента`},help:{"v1-rsf1es-4j":`Перевизначення для окремого агента максимальної кількості символів у кожному файлі ініціалізації робочого простору, що додається до системного промпту цього агента. Не вказуйте, щоб успадкувати agents.defaults.bootstrapMaxChars.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Максимальна загальна кількість символів ініціалізації агента`},help:{"v1-1bal68p-4y":`Перевизначення для окремого агента максимальної загальної кількості символів у всіх файлах ініціалізації робочого простору, що додаються до системного промпту цього агента. Не вказуйте, щоб успадкувати agents.defaults.bootstrapTotalMaxChars.`}},"agents%2Eentries%2E*%2Ecompaction":{label:{"v1-1kqcx8z-g":`Стиснення для агента`},help:{"v1-ioyi1g-2o":`Перевизначення параметрів стиснення на боці клієнта для окремого агента. Невказані параметри успадковуються з agents.defaults.compaction.`}},"agents%2Eentries%2E*%2Ecompaction%2EmaxSummaryChars":{label:{"v1-1vend8r-13":`Максимальна кількість символів у підсумку стиснення для агента`},help:{"v1-1fwu60v-58":`Гранична кількість символів у збереженому підсумку на боці клієнта для окремого агента (1000–200000), що перевизначає agents.defaults.compaction.maxSummaryChars. Ліміт токенів активної моделі може вимагати меншого підсумку.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Додавання контексту агента`},help:{"v1-1j68ys8-50":`Перевизначення для окремого агента, що керує додаванням файлів початкового налаштування робочого простору у вбудованому середовищі виконання. Не вказуйте, щоб успадкувати agents.defaults.contextInjection. Не впливає на підготовку промптів через CLI.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Обмеження контексту агента`},help:{"v1-f1qxq8-3c":`Необов’язкові перевизначення для окремого агента параметрів бюджету цільового контексту. Невказані поля успадковують значення з agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Максимальна кількість символів memory_get агента`},help:{"v1-12hlmsv-1v":`Перевизначення для окремого агента стандартного максимального бюджету символів memory_get.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Максимальна кількість символів агента після ущільнення`},help:{"v1-15s0npd-1w":`Перевизначення ліміту уривка AGENTS.md після ущільнення для окремого агента.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Робочий каталог агента`},help:{"v1-mv43ak-6a":`Робочий каталог для запусків формування відповідей цього агента. Перевизначає agents.defaults.cwd, але не cwd, заданий під час створення сеансу; файли початкового налаштування та пам’яті залишаються в робочому просторі. Підтримує ~ і відносні шляхи; окремий cwd потребує запуску поза пісочницею.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Модель прийняття рішень агента`},help:{"v1-1mih8bf-3j":`Модель прийняття рішень для окремого агента. Якщо значення не задано, успадковується agents.defaults.decisionModel; порожній рядок вимикає виклики для прийняття рішень для цього агента.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`Вбудований OpenClaw агента`},help:{"v1-uoomza-4b":`Необов’язкові перевизначення вбудованого OpenClaw для окремого агента. Використовуйте їх, щоб увімкнути суворішу поведінку виконання GPT-5 для певних агентів, не змінюючи глобальних налаштувань за замовчуванням.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Контракт виконання вбудованого OpenClaw агента`},help:{"v1-1d1jaoi-7k":`Необов’язкове перевизначення контракту виконання вбудованого OpenClaw для окремого агента. Установіть "strict-agentic", щоб увімкнути структуроване відстеження плану та невидиме для користувача відновлення ходів для цього агента в підтримуваних запусках моделей сімейства GPT-5 від OpenAI/OpenAI Codex, або "default", щоб успадкувати стандартну поведінку виконавця.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Експериментальні прапорці агента`},help:{"v1-1r06jov-2a":`Експериментальні прапорці для окремого агента. Пропущені поля успадковують agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Полегшений режим локальної моделі агента`},help:{"v1-5o3tgx-58":`Налаштування для усунення несправностей в ощадному режимі локальної моделі для окремого агента. Вмикайте його лише тоді, коли обмеження необов’язкових інструментів усуває підтверджений збій моделі, не скорочуючи набір інструментів для всіх агентів.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Швидкий режим агента за замовчуванням`},help:{"v1-ev6028-41":`Необов’язкове типове налаштування швидкого режиму для окремого агента ("auto", "ultrafast", true або false). Застосовується, якщо швидкий режим не перевизначено для окремого повідомлення чи сеансу.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Аватар профілю`},help:{"v1-pzp9gr-1t":`Аватар агента (шлях відносно робочого простору, URL http(s) або URI даних).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Політика моделей агента`},help:{"v1-17d5je8-2r":`Політика перевизначення моделі для окремого агента. Явно заданий список дозволених моделей замінює політику за замовчуванням для цього агента.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Дозволені моделі агента`},help:{"v1-1enipb-5w":`Дозволені посилання для перевизначення моделі для цього агента. Підтримуються псевдоніми, повні посилання "provider/model" і шаблони префіксів із символом підстановки в кінці, як-от "provider/*", "provider/namespace/*" або "provider/family-*"; порожнє значення дозволяє будь-яку модель.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Перевизначення моделей агента`},help:{"v1-nld1vq-1v":`Перевизначення каталогу моделей для окремого агента з повними ідентифікаторами provider/model як ключами.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Середовище виконання моделі агента`},help:{"v1-7b59y-3s":`Необов’язкова політика середовища виконання для окремої моделі цього агента. Використовуйте її для винятків моделей, специфічних для агента, замість налаштування середовища виконання для всього агента.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`Ідентифікатор середовища виконання моделі агента`},help:{"v1-1ckfc39-46":`Ідентифікатор середовища виконання моделі для окремого агента: "openclaw", "auto", ідентифікатор зареєстрованої плагінної обв’язки, як-от "codex", або підтримуваний псевдонім бекенда CLI, як-от "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Режим коду`},help:{"v1-91zu7f-7m":`Режим коду OpenClaw для цього агента й конкретної пари provider/model: «Увімкнено» примусово вмикає його, «Вимкнено» вимикає, а «За замовчуванням» успадковує налаштування активації агента, потім спільне перевизначення моделі, потім tools.codeMode.enabled. Це не змінює вибране середовище виконання або вбудований режим коду Codex.`}},"agents%2Eentries%2E*%2EnativeRuntimeConsent":{label:{"v1-r2vkr2-11":`Збережені дозволи нативного середовища виконання`},help:{"v1-1uktqfm-79":`Ідентифікатори оболонок виконання, яким дозволено використовувати власні нативні дозволи для цього агента. Нові чати використовують повний доступ із вимкненою пісочницею. Видаліть ідентифікатор, щоб негайно відкликати збережену згоду; явна згода для окремого чату залишається без змін. Обов’язкові обмеження пісочниці та робочого простору діють і надалі.`}},"agents%2Eentries%2E*%2EnewSessionPermissionMode":{help:{"v1-15v8f6l-5p":`Режим дозволів, що зберігається для нових профільованих сеансів за участю оператора, якщо режим не вказано явно. Не змінює наявні, відгалужені, делеговані чи автономні сеанси. Повний режим, як і раніше, потребує operator.admin.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Відображення міркувань агента за замовчуванням`},help:{"v1-13ly0xf-3m":`Необов’язкове налаштування відображення міркувань за замовчуванням для окремого агента (on|off|stream). Застосовується, якщо для повідомлення або сеансу не задано перевизначення відображення міркувань.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Середовище виконання агента`},help:{"v1-avjgkf-3l":`Необов’язковий дескриптор середовища виконання для цього агента. Використовуйте embedded для стандартного виконання OpenClaw або acp для типових налаштувань зовнішньої обв’язки ACP.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Середовище виконання ACP агента`},help:{"v1-91zvdk-3i":`Типові налаштування середовища виконання ACP для цього агента, коли runtime.type=acp. Перевизначення ACP на рівні прив’язки й надалі мають пріоритет для кожної розмови.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Агент інфраструктури ACP для цього агента`},help:{"v1-1pm98vp-37":`Необов’язковий ідентифікатор агента інфраструктури ACP для цього агента OpenClaw (наприклад, codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Бекенд ACP агента`},help:{"v1-1u3cdsg-2n":`Необов’язкове перевизначення бекенду ACP для сеансів ACP цього агента (за відсутності використовується глобальне значення acp.backend).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Робочий каталог ACP агента`},help:{"v1-d9p9rf-1t":`Необов’язковий типовий робочий каталог для сеансів ACP цього агента.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Режим ACP агента`},help:{"v1-yatuk4-21":`Необов’язковий типовий режим сеансів ACP для цього агента (persistent або oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Тип середовища виконання агента`},help:{"v1-139fbk6-2r":`Тип середовища виконання для цього агента: "embedded" (типове середовище виконання OpenClaw) або "acp" (типові налаштування інфраструктури ACP).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`Діапазон адрес джерел CDP браузера в пісочниці агента`},help:{"v1-1q1qyso-1d":`Перевизначення списку дозволених CIDR-діапазонів джерел CDP для окремого агента.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Мережа браузера в пісочниці агента`},help:{"v1-13bdfww-4c":`Перевизначення мережі Docker для браузера в пісочниці окремого агента. Використовуйте мостову мережу; "none" не підтримується, оскільки керування браузером потребує опублікованих портів CDP.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Дозволити приєднання до простору імен контейнера Docker у пісочниці агента`},help:{"v1-1xtnseb-2i":`НЕБЕЗПЕЧНЕ перевизначення для окремого агента, що дозволяє приєднання до просторів імен контейнерів у мережевому режимі Docker пісочниці.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`Графічні процесори Docker у пісочниці агента`},help:{"v1-1kek1n2-1t":`Перевизначення прокидання графічних процесорів Docker до контейнерів пісочниці для окремого агента.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Фільтр навичок агента`},help:{"v1-igchue-6v":`Необов’язковий список дозволених навичок для цього агента. Якщо його не вказано, агент успадковує agents.defaults.skills, коли це значення задано; інакше навички залишаються без обмежень. Задайте [], щоб вимкнути всі навички. Явно заданий список повністю замінює успадковані типові значення, а не об’єднується з ними.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Ліміти Skills агента`},help:{"v1-1sv10v9-4y":`Необов’язкові перевизначення лімітів підсистеми навичок для окремого агента. Використовуйте, коли агенту потрібен інший ліміт обсягу промпту навичок без додавання другого загального шляху налаштування лімітів контексту.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Максимальна кількість символів у промпті Skills агента`},help:{"v1-dys63y-52":`Індивідуальне перевизначення ліміту символів промпту навичок для агента. Розширює наявний шлях skills.limits.maxSkillsPromptChars замість налаштування того самого ліміту через contextLimits.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegateToolsTo":{label:{"v1-bycm06-m":`Цільові агенти для делегування інструментів`},help:{"v1-y7q6z7-d6":`Конкретні налаштовані нативні цільові агенти, які під час запуску можуть не застосовувати tools.deny агента-ініціатора. Окремо потрібен дозвіл allowAgents. Передавання лише з обмеженнями deny зберігає всі нелокальні обмеження; якщо початкові профілі чи списки дозволеного накладають обмеження або транспорт не підтримується, передавання відхиляється, а не розширює дозволи. Нативні допоміжні агенти з тією самою ціллю зберігають власні додаткові обмеження. Запити з обмеженнями щодо відправника та запити ACP ніколи не використовують цей дозвіл. Відкликання відновлює початковий знімок стану агента-ініціатора.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Режим делегування субагентам`},help:{"v1-1rkgh6p-4s":`Індивідуальне перевизначення рівня делегування субагентам для агента. Не задавайте значення, щоб використовувати "prefer" в основному сеансі цього агента та "suggest" в інших випадках; явно задане "prefer" або "suggest" завжди має пріоритет.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Типовий рівень міркування агента`},help:{"v1-173q7vy-43":`Необов’язковий типовий рівень міркування для окремого агента. Перевизначає agents.defaults.thinkingDefault для цього агента, якщо не задано перевизначення на рівні повідомлення або сеансу.`}},"agents%2Eentries%2E*%2Etools%2EagentToAgent":{label:{"v1-q7r7ya-o":`Вихідні повідомлення агента`},help:{"v1-xo2o9d-5d":`Політика обміну повідомленнями агента лише для вихідних повідомлень. Явно вказані адресати не надають доступу до читання сеансів або їхнього стану й залишаються обмеженими глобальними правилами міжагентної взаємодії та обмеженнями ізольованого середовища.`}},"agents%2Eentries%2E*%2Etools%2EagentToAgent%2Esend":{label:{"v1-1lxwft1-w":`Список дозволених адресатів агента`},help:{"v1-tfolqu-ar":`Ідентифікатори агентів або шаблони з *, з якими цей агент може зв’язуватися через sessions_send, навіть за обмеженої видимості tools.sessions.visibility. Якщо не вказано, успадковується видимість; [] забороняє звичайне надсилання між агентами. Глобальні обмеження tools.agentToAgent та ізольованого середовища діють і надалі. Не надає доступу до списку, історії, пошуку, стану чи спостереження; відповіді належать лише до надісланого ходу. Доступ до дочірніх сеансів, що належать ініціатору запиту, залишається незмінним.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Доповнення до списку дозволених інструментів агента`},help:{"v1-1550ui9-46":`Додатковий список дозволених інструментів для окремого агента, що доповнює глобальну політику та політику профілю. Обмежуйте цей список, щоб уникнути випадкового розширення привілеїв спеціалізованих агентів.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Політика інструментів агента за постачальниками`},help:{"v1-mthxv9-4t":`Індивідуальні перевизначення політики інструментів за постачальниками для агента, що дають змогу керувати можливостями в межах каналу. Використовуйте, коли окремому агенту потрібні суворіші обмеження для одного постачальника, ніж для інших.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Режим коду агента`},help:{"v1-118t8u5-65":`Параметри режиму коду для окремого агента. Явно заданий enabled перевизначає спільні налаштування моделі та глобальні налаштування активації за замовчуванням; перевизначення codeMode моделі для конкретного агента має пріоритет. Інші параметри об’єднуються з tools.codeMode, перевизначаючи відповідні значення без зміни активації.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Час очікування виконання агента (секунди)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Перевизначення ідентифікаційних даних GitHub CLI для агента`},help:{"v1-mjwdh4-38":`Повне перевизначення керованих ідентифікаційних даних GitHub CLI та автора Git для цього агента. Не вказуйте, щоб успадкувати системні ідентифікаційні дані.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EallowInSandbox":{label:{"v1-1rxew98-12":`Дозволити ідентифікаційні дані GitHub агента в ізольованому середовищі`},help:{"v1-17rsbdj-6g":`Дозволяє використання керованих облікових даних GitHub і даних автора Git цього агента в його власному ізольованому середовищі Docker або Podman (типово: false). Спільна область не допускає впровадження ідентифікаційних даних; інші серверні механізми відхиляють їх надання. Коли параметр увімкнено, аудит безпеки видає попередження.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`Електронна адреса автора Git для агента`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Ім’я автора Git для агента`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Тип облікових даних GitHub для агента`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Версія профілю GitHub для агента`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Список дозволених дій із повідомленнями для агента`},help:{"v1-1g5gov3-67":`Список дозволених дій із повідомленнями для окремого агента в інструменті message. Для публічних агентів у пісочниці задайте мінімальний список, наприклад ["send"], щоб читання, редагування, видалення, реакції та інші специфічні для постачальника дії з повідомленнями залишалися прихованими й заблокованими.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Обмін повідомленнями між контекстами для агента (між постачальниками)`},help:{"v1-pehesn-49":`Перевизначення дозволу на надсилання між провайдерами для окремого агента. Успадковує глобальне налаштування (типово: true). Установіть false, щоб заблокувати обмін повідомленнями між провайдерами для цього агента.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Обмін повідомленнями агента між контекстами (той самий провайдер)`},help:{"v1-s9u09h-4t":`Обмеження надсилання повідомлень до інших розмов у межах одного провайдера для окремого агента. Установіть false для цього параметра та allowAcrossProviders, щоб публічні агенти могли надсилати повідомлення лише в поточній розмові.`}},"agents%2Eentries%2E*%2Etools%2Eopenclaw":{label:{"v1-1fc612h-p":`Делегування OpenClaw для агента`},help:{"v1-wjtvl7-25":`Політика схвалення змін, делегованих системному агенту OpenClaw, для окремого агента.`}},"agents%2Eentries%2E*%2Etools%2Eopenclaw%2EautoApproveChanges":{label:{"v1-lxqapd-10":`Автоматичне схвалення делегованих змін для агента`},help:{"v1-1ok03hg-a1":`Перевизначає tools.openclaw.autoApproveChanges для цього агента. Значення true надає постійний дозвіл на делеговане адміністрування, який може дозволяти виконання коду на хості Gateway; значення false вимагає окремого схвалення, зокрема в режимі Full Access. Якщо значення не задано, успадковується глобальне налаштування, а далі — фактичні повноваження запуску, що надсилає запит. Обмеження файлової системи, пісочниці та операцій залишаються чинними.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Профіль інструментів агента`},help:{"v1-1du76ix-57":`Перевизначення вибору профілю інструментів для окремого агента, якому потрібен інший базовий набір можливостей. Використовуйте ощадливо, щоб відмінності в політиках агентів залишалися свідомими та доступними для перевірки.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Рій агента`},help:{"v1-420ljs-2c":`Перевизначення налаштувань рою для окремого агента. Значення об’єднуються з конфігурацією верхнього рівня tools.swarm і мають пріоритет над нею.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Режим індикації введення агента`},help:{"v1-oxir52-2e":`Перевизначає стандартну політику початку індикації введення для одного агента, не впливаючи на інших агентів.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Допоміжна модель агента`},help:{"v1-ccb32g-5u":`Допоміжна модель для окремого агента у вигляді рядка або { primary, fallbacks }. Якщо не задано, успадковується agents.defaults.utilityModel. Явне значення primary без fallbacks очищає успадковані резервні моделі; порожній рядок вимикає маршрутизацію до допоміжних моделей.`}},"agents%2Eentries%2E*%2EutilityModel%2Efallbacks":{label:{"v1-17pzdxs-t":`Резервні допоміжні моделі агента`},help:{"v1-v419a0-2k":`Упорядкований список резервних допоміжних моделей для окремого агента. Порожній список очищає успадковані резервні допоміжні моделі.`}},"agents%2Eentries%2E*%2EutilityModel%2Eprimary":{label:{"v1-lbcmz5-r":`Основна допоміжна модель агента`},help:{"v1-1d8oent-1z":`Основна допоміжна модель для окремого агента. Не вказуйте, щоб успадкувати основну допоміжну модель за замовчуванням.`}},"agents%2Eentries%2E*%2EworkspaceFileMode":{label:{"v1-13trwkt-k":`Права доступу до нових файлів пам’яті`},help:{"v1-8mxas6-56":`Перевизначає agents.defaults.workspaceFileMode для новостворених файлів пам’яті цього агента у форматі, зручному для читання людиною. Права доступу до наявних файлів зберігаються; хост, що виконує запис, застосовує власну umask.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Покоління призначення агентів-власників`},help:{"v1-1g8mxd3-8u":`Стійкий маркер покоління моделі володіння в багатоагентній системі. "explicit" означає, що фонові канали, консультації із системним агентом, Talk, cron і прямі операції CLI мають визначити власника для конкретного інтерфейсу або зупинитися, якщо власника неможливо визначити. OpenClaw встановлює цей маркер автоматично під час створення або міграції групи агентів; для єдиного агента його слід опустити.`}},approvals:{label:{"v1-1m405m7-9":`Погодження`},help:{"v1-4y3in-5w":`Налаштування маршрутизації погоджень для пересилання запитів на погодження exec і плагінів до чатів поза початковим сеансом. Залишайте їх вимкненими, якщо операторам не потрібна явна видимість погоджень поза основним каналом.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Пересилання погоджень exec`},help:{"v1-1r2mozk-5v":`Об’єднує налаштування пересилання погоджень exec, зокрема ввімкнення, режим маршрутизації, фільтри та явно задані цілі. Налаштуйте тут, якщо запити на погодження мають надходити до робочих каналів, а не лише до початкової гілки.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Фільтр агентів для погоджень`},help:{"v1-xip9a-4k":'Необов’язковий список дозволених ідентифікаторів агентів, для яких можна пересилати запити на схвалення, наприклад `["primary", "ops-agent"]`. Використовуйте його, щоб не надсилати в канали сповіщення щодо сторонніх агентів.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Пересилати погодження exec`},help:{"v1-1t0whe8-5s":`Увімкнути пересилання запитів на погодження exec до налаштованих місць призначення (типово: false). Залишайте вимкненим у конфігураціях із низьким ризиком і вмикайте лише тоді, коли відповідальним за погодження людям потрібно бачити запити в каналах.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Режим пересилання погоджень`},help:{"v1-1dedfo4-69":`Визначає, куди надсилаються запити на погодження: "session" використовує початковий чат, "targets" — налаштовані цілі, а "both" надсилає обома маршрутами. Використовуйте "session" як базовий варіант і розширюйте лише тоді, коли робочий процес потребує дублювання.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Фільтр сеансів для погоджень`},help:{"v1-smeg8e-5u":'Необов’язкові фільтри ключів сеансів, які зіставляються як підрядки або шаблони регулярних виразів, наприклад `["discord:", "^agent:ops:"]`. Використовуйте вузькі шаблони, щоб до спільних місць призначення пересилалися лише потрібні контексти схвалення.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Цілі пересилання запитів на схвалення`},help:{"v1-17ah848-5u":`Явно задані цілі доставки, які використовуються, коли режим пересилання включає цілі; кожна містить відомості про канал і місце призначення. Формуйте списки цілей за принципом найменших привілеїв і перевіряйте кожне місце призначення, перш ніж вмикати широке пересилання.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`ID облікового запису цілі схвалення`},help:{"v1-16zopng-5e":`Необов’язковий параметр вибору облікового запису для каналів із кількома обліковими записами, коли запити на схвалення потрібно спрямовувати через контекст певного облікового запису. Використовуйте його лише тоді, коли в цільовому каналі налаштовано кілька облікових записів.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Цільовий канал схвалення`},help:{"v1-ji1igl-59":`ID каналу або постачальника для доставки пересланих запитів на схвалення, наприклад discord, slack або ID каналу плагіна. Використовуйте лише дійсні ID каналів, щоб уникнути непомітних збоїв доставки запитів через невідомі маршрути.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`ID цільової гілки схвалення`},help:{"v1-1axynw7-59":`Необов’язкова цільова гілка або тема для каналів, які підтримують доставку пересланих запитів на схвалення в гілках. Використовуйте цей параметр, щоб обговорення схвалень залишалося в робочих гілках, а не в основних каналах.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Місце призначення запитів на схвалення`},help:{"v1-1ijng7e-5n":`Ідентифікатор одержувача в цільовому каналі (ID каналу, ID користувача або кореневого повідомлення гілки залежно від провайдера). Уточнюйте значення для кожного провайдера, оскільки формат адресата відрізняється між інтеграціями каналів.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Пересилання запитів на схвалення плагінів`},help:{"v1-1m6pzxv-6b":`Об’єднує налаштування пересилання запитів на схвалення плагінів: увімкнення, режим маршрутизації, фільтри та явно задані адресати. Не залежить від пересилання запитів на схвалення виконання команд. Налаштуйте тут, якщо запити на схвалення плагінів мають надходити до операційних каналів.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Фільтр агентів для схвалення плагінів`},help:{"v1-b3test-4y":'Необов’язковий список дозволених ідентифікаторів агентів, для яких можна пересилати запити на схвалення плагінів, наприклад `["primary", "ops-agent"]`. Використовуйте його, щоб вибрати, запити на схвалення яких агентів пересилатимуться.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Пересилати запити на схвалення плагінів`},help:{"v1-1ntctaf-3v":`Увімкнення пересилання запитів на схвалення плагінів налаштованим адресатам доставки (типово: false). Не залежить від approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Режим пересилання запитів на схвалення плагінів`},help:{"v1-1h62vy4-3z":`Визначає, куди надсилаються запити на схвалення плагінів: "session" використовує початковий чат, "targets" — налаштованих адресатів, а "both" надсилає обома шляхами.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Фільтр сеансів для схвалення плагінів`},help:{"v1-1eppxmt-57":'Необов’язкові фільтри ключів сеансів, що зіставляються як підрядки або шаблони регулярних виразів, наприклад `["discord:", "^agent:ops:"]`. Використовуйте вузькі шаблони, щоб пересилалися лише запити з потрібних контекстів схвалення.'}},"approvals%2Eplugin%2Eslack":{label:{"v1-o7dlxi-m":`Рецензенти плагінів у Slack`},help:{"v1-1svd0ag-4x":`Політика рецензентів у Slack для схвалення плагінів. Не вказуйте типовий список рецензентів, щоб зберегти авторизацію облікового запису через allowFrom/defaultTo; задайте [], щоб за замовчуванням заборонити ухвалення рішень через Slack.`}},"approvals%2Eplugin%2Eslack%2Eapprovers":{label:{"v1-r39jnl-u":`Типові рецензенти плагінів у Slack`},help:{"v1-auy576-5v":`Типові рецензенти плагінів у Slack, задані як необроблені ідентифікатори користувачів U/W у вибраному обліковому записі Slack або як значення team:<team-id>:user:<user-id> із зазначенням робочого простору. Списки плагінів та інструментів мають пріоритет над цим списком для власних запитів.`}},"approvals%2Eplugin%2Eslack%2Eplugins":{label:{"v1-13wg4dk-v":`Перевизначення рецензентів плагінів у Slack`},help:{"v1-16kb0vj-2r":`Перевизначення рецензентів, де ключем є ідентифікатор вибраного плагіна нативного інструмента. Ключі інструментів кодують необроблену назву інструмента.`}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Цілі пересилання запитів на схвалення плагінів`},help:{"v1-o92qze-3k":`Явно задані цілі доставки, що використовуються, коли режим пересилання запитів на схвалення плагінів включає цілі; кожна містить відомості про канал і місце призначення.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`ID облікового запису цілі схвалення плагіна`},help:{"v1-1wf3lqn-3j":`Необов’язковий селектор облікового запису для каналів із кількома обліковими записами, коли запити на схвалення плагінів потрібно спрямовувати через певний обліковий запис.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Цільовий канал схвалення плагіна`},help:{"v1-1mzhzi9-34":`ID каналу або провайдера для доставки пересланих запитів на схвалення плагінів, наприклад discord, slack або ID каналу плагіна.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`ID цільової гілки схвалення плагіна`},help:{"v1-1scaw9c-2v":`Необов’язкова цільова гілка або тема для каналів, що підтримують доставку пересланих запитів на схвалення плагінів у гілках.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Місце призначення запитів на схвалення плагіна`},help:{"v1-sh5te1-31":`Ідентифікатор місця призначення в цільовому каналі (ID каналу, ID користувача або кореневе повідомлення гілки залежно від провайдера).`}},attachments:{label:{"v1-8925gh-b":`Вкладення`},help:{"v1-1xvgkss-40":`Поведінка зберігання верхнього рівня, спільна для провайдерів та інструментів, які зберігають медіафайли. Використовуйте ttlHours, щоб обмежити термін зберігання тимчасово підготовлених медіафайлів перед очищенням.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`TTL зберігання вкладень (години)`},help:{"v1-r7enyq-98":`Необов’язковий термін зберігання в годинах для збережених медіафайлів, які обробляє загальне очищення за mtime. Залиште параметр незаданим, щоб вимкнути це очищення, або задайте значення на кшталт 24 (1 день) чи 168 (7 днів), щоб періодично видаляти старіші підготовлені медіафайли. Керовані вихідні медіафайли (вкладення, створені в чаті) виключено: для них діють окремі правила зберігання з урахуванням SQLite та чату.`}},audio:{label:{"v1-11wczsp-5":`Аудіо`}},auth:{label:{"v1-5xz433-4":`Автентифікація`},help:{"v1-1eu3aud-5c":`Кореневий розділ профілів автентифікації для облікових даних постачальників у кількох профілях і визначення порядку резервного перемикання з урахуванням періодів очікування. Зберігайте профілі мінімальними та явно визначеними, щоб поведінку автоматичного резервного перемикання можна було перевірити.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Порядок профілів автентифікації`},help:{"v1-1x6kknp-1w":`Упорядковані ідентифікатори профілів автентифікації для кожного постачальника (використовуються для автоматичного резервного перемикання).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Профілі автентифікації`},help:{"v1-kzoqcn-1j":`Іменовані профілі автентифікації (постачальник + режим + необов’язкова електронна адреса).`}},bindings:{label:{"v1-1hcih9f-8":`Прив’язки`},help:{"v1-y7hrzb-4i":`Правила прив’язування верхнього рівня для маршрутизації та постійного закріплення розмов ACP. Використовуйте type=route для звичайної маршрутизації та type=acp для постійних прив’язок до середовища виконання ACP.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Перевизначення прив’язки ACP`},help:{"v1-1t4lisi-44":`Необов’язкові перевизначення ACP для окремих прив’язок із bindings[].type=acp. Цей рівень перевизначає стандартні значення agents.entries.*.runtime.acp для відповідної розмови.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`Бекенд прив’язки ACP`},help:{"v1-rsrbkp-2x":`Перевизначення бекенду ACP для цієї прив’язки (якщо не задано, використовується бекенд ACP середовища виконання агента, а потім — глобальне значення acp.backend).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Робочий каталог прив’язки ACP`},help:{"v1-ngpkj0-1y":`Перевизначення робочого каталогу для сеансів ACP, створених із цієї прив’язки.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Мітка прив’язки ACP`},help:{"v1-azce82-23":`Зрозуміла мітка для стану й діагностики ACP у цій прив’язаній розмові.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Режим прив’язки ACP`},help:{"v1-cgq8xv-1v":`Перевизначення режиму сеансу ACP для цієї прив’язки (persistent або oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`ID агента прив’язки`},help:{"v1-17ra0cl-4m":`ID цільового агента, який отримує трафік, коли виконується відповідне правило зіставлення прив’язки. Використовуйте лише дійсні ID налаштованих агентів, щоб уникнути збоїв маршрутизації під час виконання.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Правило зіставлення прив’язки`},help:{"v1-sc1w2e-51":`Об’єкт правила зіставлення, що визначає, коли застосовується прив’язка, зокрема канал і необов’язкові обмеження за обліковим записом або співрозмовником. Задавайте вузькі правила, щоб уникнути випадкового перехоплення обробки агентом в інших контекстах.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`ID облікового запису прив’язки`},help:{"v1-1d209g7-56":`Необов’язковий селектор облікового запису для каналів із кількома обліковими записами, щоб прив’язка застосовувалася лише до одного з них. Використовуйте його, коли маршрут потрібно обмежити певним обліковим записом; інакше залиште незаданим.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Канал прив’язки`},help:{"v1-d22m5-54":"Ідентифікатор каналу або постачальника, до якого застосовується ця прив’язка, наприклад `telegram`, `discord` або ID каналу плагіна. Використовуйте точний ключ налаштованого каналу, щоб перевірка прив’язки працювала надійно."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`ID гільдії прив’язки`},help:{"v1-jzzfj1-4x":`Необов’язкове обмеження за ID гільдії/сервера у стилі Discord для перевірки прив’язок у розгортаннях із кількома серверами. Використовуйте, коли однакові ідентифікатори співрозмовників можуть траплятися в різних гільдіях.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Зіставлення співрозмовника для прив’язки`},help:{"v1-gcjxff-4i":`Необов’язкова умова зіставлення співрозмовника для конкретних розмов, що включає його тип та ID. Використовуйте, коли за агентом потрібно закріпити лише один особистий чат, групу або канал.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`ID співрозмовника для прив’язки`},help:{"v1-86fbh7-4b":`Ідентифікатор розмови для зіставлення співрозмовника, наприклад ID чату, каналу або групи від постачальника. Указуйте його точно, щоб уникнути непомітних невідповідностей.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Тип співрозмовника для прив’язки`},help:{"v1-uufscp-4x":`Тип розмови зі співрозмовником: "direct", "group", "channel" або застаріле "dm" (застарілий псевдонім для direct). У нових конфігураціях надавайте перевагу "direct" і узгоджуйте тип із семантикою каналу.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Ролі для прив’язки`},help:{"v1-6s891m-4k":`Необов’язковий список фільтрів за ролями для постачальників, які додають ролі до контексту чату. Використовуйте його, щоб спрямовувати трафік від привілейованих або операційних ролей до спеціалізованих агентів.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`ID команди для прив’язки`},help:{"v1-hh9ps2-48":`Необов’язкове обмеження за ID команди/робочого простору для постачальників, які організовують чати в межах команд. Додайте його, якщо потрібно обмежити прив’язки контекстом одного робочого простору.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Сеанс прив’язки`},help:{"v1-x325l2-4v":`Необов’язкові перевизначення параметрів сеансу маршруту для розмов, що відповідають цій прив’язці. Використовуйте їх, коли окремий маршрут має зберігати того самого агента, але інакше ізолювати контекст сеансів.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`Область сеансу особистих повідомлень прив’язки`},help:{"v1-10sg3xw-4s":`Необов’язкове перевизначення області сеансу особистих повідомлень для цієї прив’язки маршруту. Наприклад, можна залишити глобальне значення session.dmScope="main", а для вибраних співрозмовників використовувати "per-account-channel-peer".`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Область групового сеансу прив’язки`},help:{"v1-1ys2u7k-6n":`Необов’язкове перевизначення області сеансу групи/каналу для цієї прив’язки маршруту. "per-group" зберігає відповідні кімнати окремо, а основний сеанс агента стежить за ними у фоновому режимі незалежно від dmScope; "main" об’єднує їхній контекст в основному сеансі й не потребує спостереження.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Тип прив’язки`},help:{"v1-172mhtk-3o":`Тип прив’язки. Використовуйте "route" (або не вказуйте тип для застарілих записів маршрутів) для звичайної маршрутизації та "acp" для постійних прив’язок розмов ACP.`}},broadcast:{label:{"v1-awqjh0-j":`Гілки груп агентів`},help:{"v1-1tz72sr-6b":`Використовуйте гілки груп агентів, щоб залучити кількох налаштованих агентів до однієї вхідної розмови, кожного у власному сеансі. Записи із зазначенням каналу підтримують обмежену кількість подальших раундів; застарілі масиви співрозмовників WhatsApp зберігають однопрохідну поведінку.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Учасники та параметри групи агентів`},help:{"v1-1b63zmt-7d":`Використовуйте ідентифікатор співрозмовника із зазначенням каналу (наприклад, "telegram:-100123"), щоб налаштувати масив ідентифікаторів агентів або об’єкт зі строго визначеною структурою з полями agents, mentionGating, maxRounds і maxTurns. Записи із зазначенням каналу мають пріоритет над застарілими ключами співрозмовників WhatsApp і допускають щонайбільше 16 агентів.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Учасники групи агентів`},help:{"v1-g5o0ky-43":`Ідентифікатори агентів-учасників з agents.entries (щонайбільше: 16). Кожен учасник використовує власний сеанс для цього каналу, облікового запису, розмови та гілки.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Максимальна кількість раундів групи агентів`},help:{"v1-i6v4jc-5a":`Максимальна кількість раундів на вхідне повідомлення, включно з початковим раундом (ціле число: 1–4, типово: 1). У наступних раундах учасники отримують обмежений обсяг відповідей інших учасників із зазначенням авторства. Раунди припиняються, коли всі учасники пропускають хід.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Максимальна кількість ходів групи агентів`},help:{"v1-1kiv8dy-72":`Максимальна кількість ходів учасників на вхідне повідомлення в усіх раундах (ціле число: 1–32, типово: agents.length). Місця резервуються до паралельного запуску; це обмежує кількість ходів агентів, а не окремих фрагментів повідомлень чи надсилань через інструменти. Після перезапуску ліміти не відновлюються.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Вибір учасників групи агентів за згадками`},help:{"v1-uay9zu-5u":`Вибирати лише учасників, явно згаданих через @, якщо є збіги; інакше запускати всіх учасників (типово: true). Самі лише імена або емодзі не вибирають учасників. Списки дозволених каналів і правила допуску діють і надалі.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Стратегія групи агентів`},help:{"v1-p4k9hu-4q":`Порядок виконання учасників: "parallel" (типово) запускає агентів одночасно, а "sequential" — у налаштованому порядку. Кожен раунд завершується до початку наступного.`}},browser:{label:{"v1-13dzmen-7":`Браузер`},help:{"v1-5b74wi-5l":`Налаштування роботи браузера для локального або віддаленого підключення через CDP, маршрутизації профілів і поведінки знімків екрана та стану. Залиште типові значення, якщо ваш процес автоматизації не потребує спеціальних налаштувань транспорту браузера.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Дозволити імпорт системного профілю`},help:{"v1-1lsvlxw-5w":`Дозволяє хостам macOS імпортувати файли cookie з локального системного профілю браузера сімейства Chrome до керованого профілю браузера OpenClaw. Вимкніть цей параметр, щоб заборонити імпорт файлів cookie профілю браузера та запит згоди на доступ до В’язки ключів macOS.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Режим лише підключення до браузера`},help:{"v1-xaw7xm-4s":`Обмежує роботу браузера лише підключенням без запуску локальних процесів браузера. Використовуйте цей режим, коли всі сеанси браузера керуються зовнішнім віддаленим постачальником CDP.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`URL CDP браузера`},help:{"v1-2n72jb-65":`URL кінцевої точки CDP/DevTools для підключення до екземпляра браузера із зовнішнім керуванням. Використовуйте його для централізованих хостів браузера, тунелів або підключення до наявного сеансу та обмежуйте доступ до URL лише довіреними мережевими шляхами.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Типовий профіль браузера`},help:{"v1-a6xo96-52":`Назва типового профілю браузера, який вибирається, коли під час виклику профіль не вказано явно. Використовуйте стабільний профіль з мінімальними привілеями як типовий, щоб зменшити ризик випадкового використання стану з іншого контексту.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Браузер увімкнено`},help:{"v1-1m3zcs-5g":`Увімкнення підтримки браузера в Gateway, щоб могли працювати браузерні інструменти та робочі процеси з керуванням через CDP. Вимкніть, якщо автоматизація браузера не потрібна, щоб обмежити доступні можливості та зменшити обсяг роботи під час запуску.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Виконання скриптів у браузері ввімкнено`},help:{"v1-1oa79mq-59":`Вмикає допоміжні засоби виконання скриптів на боці браузера під час роботи, якщо це підтримується. Залишайте вимкненим, якщо вашим робочим процесам не потрібне виконання скриптів на додачу до знімків і навігації.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Шлях до виконуваного файлу браузера`},help:{"v1-1dshhkn-6g":`Явно заданий шлях до виконуваного файлу браузера, якщо автоматичного виявлення недостатньо у вашому середовищі. Використовуйте стабільний абсолютний шлях або шлях, що починається з ~ і вказує на домашній каталог у вашій ОС, щоб поведінка запуску залишалася передбачуваною після перезапусків.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Ретранслятор розширення браузера`},help:{"v1-6ywlwr-4e":`Налаштування сумісності автентифікації ретранслятора розширення Chrome. Зберігайте перехідний період підтримки застарілої автентифікації лише доти, доки вона потрібна старішим сполученим розширенням або зовнішнім клієнтам CDP.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Дозволити застарілу автентифікацію ретранслятора браузера`},help:{"v1-pj2e90-63":`Тимчасово дозволяє застарілу автентифікацію ретранслятора через Bearer, Basic і token-subprotocol. Типове значення: true протягом одного перехідного періоду. Установіть false, коли всі розширення та зовнішні клієнти CDP використовуватимуть Browser Relay Authentication v2.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Режим браузера без графічного інтерфейсу`},help:{"v1-hlkywz-56":`Локальні керовані браузери за замовчуванням працюють без графічного інтерфейсу. Установіть false, щоб відображати вікно браузера. Браузери з наявним сеансом, із розширенням, віддалені браузери та браузери в режимі лише підключення зберігають режим, вибраний зовнішніми засобами.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Режим браузера без ізоляції`},help:{"v1-slntux-4w":`Вимикає прапорці ізоляції Chromium для середовищ, де ізоляція не працює під час виконання. За можливості залишайте цей параметр вимкненим, оскільки він послаблює захист ізоляції процесів.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Профілі браузера`},help:{"v1-1x8lf05-51":`Мапа підключень іменованих профілів браузера для явної маршрутизації до портів або URL-адрес CDP із необов’язковими метаданими. Використовуйте узгоджені назви профілів і уникайте визначень кінцевих точок, що перекриваються.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Режим лише підключення для профілю браузера`},help:{"v1-2b5zs0-5a":`Перевизначення режиму лише підключення для окремого профілю: пропускає запуск локального браузера й лише підключається до наявної кінцевої точки CDP. Корисно, коли один профіль керується ззовні, а інші запускаються локально.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`Порт CDP профілю браузера`},help:{"v1-gx1yiq-49":`Локальний порт CDP для окремого профілю, що використовується для підключення до екземплярів браузера за портом замість URL-адреси. Використовуйте унікальні порти для кожного профілю, щоб уникнути конфліктів підключення.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`URL-адреса CDP профілю браузера`},help:{"v1-x491r0-64":`URL-адреса кінцевої точки CDP/DevTools для окремого профілю, що використовується для явної маршрутизації до браузера за назвою профілю. Використовуйте для віддалених хостів CDP, тунелів або профілів наявних сеансів, які мають підключатися через запущену кінцеву точку Chrome DevTools.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Драйвер профілю браузера`},help:{"v1-17byyx6-5r":`Режим драйвера браузера для окремого профілю. Використовуйте "openclaw" (або застарілий "clawd") для профілів на основі CDP, "existing-session" для підключення через Chrome DevTools MCP або "extension" для ретранслятора розширення Chrome з автентифікацією.`}},"browser%2Eprofiles%2E*%2Eengine":{label:{"v1-w0e8eg-m":`Рушій профілю браузера`},help:{"v1-1n0drki-ab":`Попередньо визначений набір можливостей рушія браузера: "chromium" (за замовчуванням) або експериментальні "lightpanda" / "kitesurf" для роботи із зовнішнім браузером через CDP. Зовнішні рушії потребують явно заданого ws/wss cdpUrl, виділеного для одного профілю, і attachOnly: true, ніколи не запускають локальний браузер і надають лише підтримувані ними операції. Lightpanda не підтримує знімки екрана; Kitesurf має експериментальну підтримку створення знімків екрана.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Шлях до виконуваного файлу браузера для профілю`},help:{"v1-29azyv-4w":`Шлях до виконуваного файлу браузера для окремого керованого профілю, що запускається локально. Перевизначає browser.executablePath і підтримує шляхи, що починаються з ~ для позначення домашнього каталогу ОС.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Режим без графічного інтерфейсу для профілю браузера`},help:{"v1-p4jtgv-4u":`Перевизначення режиму без графічного інтерфейсу для окремого профілю браузера, що запускається локально. Використовуйте, коли один профіль має працювати без графічного інтерфейсу, не застосовуючи browser.headless примусово до всіх інших профілів.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Аргументи Chrome MCP для профілю браузера`},help:{"v1-rc45ke-5g":`Додаткові аргументи Chrome DevTools MCP для окремого профілю для підключення в режимі existing-session, наприклад --no-usage-statistics. Задані тут аргументи кінцевої точки перевизначають вбудований вибір автоматичного підключення або URL браузера.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Команда Chrome MCP для профілю браузера`},help:{"v1-1xpty8o-2h":`Команда Chrome DevTools MCP для окремого профілю для підключення в режимі existing-session. За замовчуванням — npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Каталог даних користувача для профілю браузера`},help:{"v1-5xvgex-9h":`Каталог даних користувача Chromium для окремого профілю, що використовується для підключення до наявного сеансу через Chrome DevTools MCP. Використовуйте його для Brave, Edge, Chromium або нестандартних профілів Chrome, якщо вбудований механізм автоматичного підключення вибирає неправильний каталог даних браузера на вибраному хості чи вузлі браузера. Шляхи, що починаються з ~, розгортаються відносно домашнього каталогу користувача в ОС.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Типові параметри знімків браузера`},help:{"v1-v19wdy-4y":`Типова конфігурація створення знімків, яка використовується, якщо під час виклику параметри знімка не задано явно. Налаштуйте її для узгодженого створення знімків у різних каналах і сценаріях автоматизації.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Режим знімків браузера`},help:{"v1-joeyxp-5c":`Типовий режим отримання знімків, який визначає, як вміст сторінки перетворюється для використання агентом. Виберіть режим, що забезпечує баланс між читабельністю, точністю відтворення та витратами токенів для ваших робочих процесів.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`Політика SSRF браузера`},help:{"v1-1qbp9im-5e":`Налаштування захисту від підроблення запитів на стороні сервера для механізмів отримання даних через браузер або мережу, які можуть звертатися до внутрішніх хостів. У робочому середовищі зберігайте обмежувальні типові налаштування та відкривайте доступ лише до явно схвалених цілей.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Дозволені імена хостів браузера`},help:{"v1-1rng39-2k":`Точні імена хостів або явно задані IP-адреси, дозволені перевірками політики SSRF браузера. Зберігайте список мінімальним.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Дозволити унікальний локальний діапазон IPv6 у браузері`},help:{"v1-1glx5cy-2c":`Дозволити унікальні локальні адреси IPv6 (fc00::/7) для довірених проксі-середовищ із fake-IP.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Браузер: дозволити діапазон для тестування продуктивності RFC 2544`},help:{"v1-10ateu3-2i":`Дозволяє IP-адреси з діапазону для тестування продуктивності RFC 2544 (198.18.0.0/15) у довірених проксі-середовищах із підставними IP-адресами.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Браузер: заблоковані імена хостів`},help:{"v1-nug0we-6k":`Шаблони імен хостів, які блокуються до DNS-запитів і перевірки правил дозволу, навіть якщо доступ до приватної мережі ввімкнено. Підтримуються точні імена хостів і "*.example.com" лише для піддоменів; щоб заблокувати кореневий домен, додайте "example.com" окремо. Порожнє або невстановлене значення не додає жодних заборон.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Браузер: дозволити доступ до приватної мережі (небезпечно)`},help:{"v1-17103pi-4m":`Дозволяє інструментам браузера доступ до діапазонів адрес приватної мережі. Якщо значення не задано, типово вимкнено; вмикайте лише для явно довірених ресурсів приватної мережі.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Браузер: очищення вкладок`},help:{"v1-1ctwaad-4y":`Політика очищення вкладок браузера, відкритих сеансами основного агента, за можливості. Залишайте ввімкненою, щоб запобігти накопиченню застарілих вкладок ізольованого середовища або керованого браузера під час тривалої роботи шлюзів.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Браузер: очищення вкладок увімкнено`},help:{"v1-4sv97p-3u":`Вмикає очищення неактивних відстежуваних вкладок браузера для сеансів основного агента. Вимикайте лише тоді, коли зовнішні інструменти повністю керують життєвим циклом вкладок.`}},channels:{label:{"v1-1ju93md-8":`Канали`},help:{"v1-18k1gv4-50":`Налаштування постачальників каналів і спільні значення за замовчуванням, які керують політиками доступу та поведінкою окремих інтерфейсів. Зберігайте значення за замовчуванням централізовано й перевизначайте їх для окремих постачальників лише за потреби.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Типові налаштування каналів`},help:{"v1-uz6veb-4p":`Типова поведінка каналів для всіх провайдерів, якщо налаштування окремого провайдера не задано. Використовуйте це, щоб забезпечити узгоджену базову політику перед налаштуванням окремих провайдерів.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Типовий захист від зациклення ботів`},help:{"v1-1lpznyk-4w":`Типові налаштування захисту від зациклення пар для провайдерів каналів, які підтримують захист від циклічного обміну між ботами. Перевизначайте їх для окремого провайдера, лише якщо певному каналу потрібен інший ліміт.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Типова тривалість паузи при зацикленні ботів у секундах`},help:{"v1-1yl5ird-2z":`Тривалість паузи в секундах для пари після перевищення ліміту циклічного обміну. Типове значення для каналів із підтримкою цієї функції — 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Захист від зациклення ботів увімкнено типово`},help:{"v1-3ruik-4r":`Типово вмикає захист від зациклення пар для каналів із підтримкою цієї функції, коли повідомлення ботів можуть потрапляти на обробку. Провайдери все одно можуть вимкнути захист, якщо повідомлення ботів ігноруються.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Типова кількість подій циклічного обміну ботів за часове вікно`},help:{"v1-1u0mdjc-41":`Максимальна кількість подій, якими пара відправник/одержувач може обмінятися протягом заданого часового вікна до початку блокування. Типове значення для каналів із підтримкою цієї функції — 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Типова тривалість часового вікна циклічного обміну ботів у секундах`},help:{"v1-12xpmen-2m":`Тривалість ковзного вікна в секундах для лімітів циклічної взаємодії між парами. Типове значення для каналів із підтримкою цієї функції — 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Типова видимість контексту`},help:{"v1-1hze3g1-5o":`Типова видимість додаткового контексту для отриманого вмісту цитат, гілок обговорення та історії: "all" (зберігати весь контекст), "allowlist" (лише відправники зі списку дозволених) або "allowlist_quote" (список дозволених зі збереженням явних цитат).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Типова політика для груп`},help:{"v1-ntl9m4-4n":`Типова політика для груп у всіх каналах: "open", "disabled" або "allowlist". Залиште "allowlist" для безпечнішої роботи у виробничому середовищі, якщо широка участь у групах не є навмисною.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Неявні згадки за замовчуванням`},help:{"v1-4gtdyv-48":`Політика за замовчуванням, яка визначає, чи активують відповіді боту, цитування бота та участь бота в гілці канали обміну повідомленнями, що підтримують цю функцію, без явної згадки.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Неявні згадки через цитування бота за замовчуванням`},help:{"v1-va1u5v-2v":`За замовчуванням вважати цитовані повідомлення бота неявними згадками. Для зворотної сумісності значення за замовчуванням — true.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Неявні згадки через відповіді боту за замовчуванням`},help:{"v1-lm44c3-39":`За замовчуванням вважати відповіді на власні повідомлення бота неявними згадками. Для зворотної сумісності значення за замовчуванням — true.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Неявні згадки через участь у гілці за замовчуванням`},help:{"v1-160205h-3o":`За замовчуванням вважати подальші повідомлення в гілках, де брав участь бот, неявними згадками. Для зворотної сумісності значення за замовчуванням — true.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Перевизначення моделей для каналів`},help:{"v1-1b01spx-2p":`Зіставлення: провайдер -> ідентифікатор каналу / співрозмовника в особистих повідомленнях -> перевизначення моделі (значення — provider/model або псевдоніми).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Хмарні виконавці`},help:{"v1-10carc4-5v":`Профілі хмарних виконавців для тимчасових віддалених середовищ, які вмикаються за бажанням. Якщо цей розділ відсутній або не містить профілів, створення хмарних виконавців залишається недоступним, а поточна поведінка статусу Gateway/вузла не змінюється.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Робочий стіл хмарного виконавця (експериментально)`},help:{"v1-sly85c-3k":`Вмикає експериментальний інтерфейс worker.desktop.observe і панель робочого столу у вебзастосунку для середовищ хмарних воркерів із підтримкою робочого столу.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Пул підготовлених хмарних воркерів`},help:{"v1-rw51o5-6b":`Обмеження для підготовлених хмарних воркерів, що зберігаються в готовності для майбутніх сеансів. За резервні воркери стягується плата як за запущені машини, доки постачальник не завершить очищення; їхній фіксований термін дії визначається фактичними потребами проєкту та чинною політикою постачальника щодо простою.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Ліміт резерву готових хмарних воркерів`},help:{"v1-1mpd1dt-7u":`Загальний для Gateway ліміт непризначених підготовлених хмарних воркерів у всіх проєктах і профілях (типово: 4). Воркери, що готуються, і резервні воркери, очищення яких ще не підтверджено, враховуються в цьому ліміті. Установіть 0, щоб вивільнити непризначені резервні воркери й вимкнути поповнення резерву, зберігши повторне використання знімків і активні сеанси.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Профілі хмарних виконавців`},help:{"v1-eii67l-3j":`Іменовані профілі хмарних виконавців. Кожен профіль визначає провайдера виконавця, зареєстрованого плагіном, і містить налаштування цього провайдера.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Профіль хмарного виконавця`},help:{"v1-1v2w7jl-4u":`Один профіль хмарного виконавця, який вибирається за назвою під час створення середовища. Використовуйте підтримувані посилання на облікові дані провайдера замість вбудовування секретних даних у цей блок.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Спосіб установлення хмарного виконавця`},help:{"v1-blrtbf-74":`Спосіб установлення виконавця: "bundle" (типово) передає встановлену збірку Gateway із хешем вмісту й підтримує випущені, розробницькі та невипущені версії; "npm" установлює точну версію Gateway і доступний лише тоді, коли цю версію вже випущено.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Провайдер хмарного виконавця`},help:{"v1-1p4s4c1-44":`Ідентифікатор постачальника воркерів, зареєстрований плагіном. Налаштований плагін має надати цей ідентифікатор, перш ніж Gateway зможе створювати середовища на основі профілю.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Цільовий розмір резерву готових хмарних воркерів`},help:{"v1-1nwve9s-7w":`Цільова кількість непризначених підготовлених воркерів для кожного проєкту, який відповідає умовам і використовує цей профіль (типово: 1), з урахуванням загального для Gateway ліміту пулу підготовлених воркерів. Установіть 0, щоб вимкнути резерви цього профілю, зберігши повторне використання знімків. Воркери, що готуються, і резервні воркери, очищення яких ще не підтверджено, враховуються в цільовій кількості.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Налаштування постачальника хмарних воркерів`},help:{"v1-mq7u32-4j":`Налаштування постачальника, які перевіряє вибраний плагін. Для значень із секретними даними використовуйте об’єкти SecretRef; у непрозорих налаштуваннях посилання на секрети не розкриваються автоматично.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Час простою до призупинення хмарного воркера`},help:{"v1-1keuwgh-4w":`Автоматично вивільняє ресурси хмарного воркера після вказаного часу простою, наприклад 45m або 2h; наступне повідомлення запускає створення заміни. Мінімум: 1m. Залиште невказаним, щоб воркери продовжували працювати.`}},"cloudWorkers%2Eprofiles%2E*%2EworkspaceDurability":{label:{"v1-1yi22sz-v":`Збереження робочого простору репозиторію`},help:{"v1-1r6ow8r-6o":`За замовчуванням використовується дзеркальне копіювання. Репозиторії зі збереженням диска потребують постачальника керованих вузлів із точним виділенням ресурсів і явно заданого скінченного періоду обчислень у секундах. Між ходами вихідний диск залишається основним джерелом даних; дія «Перемістити до Gateway» експортує його та виводить з експлуатації.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Профілі хмарних воркерів для проєктів`},help:{"v1-1kkfrif-46":`Назви типових профілів хмарних воркерів із ключами у вигляді нормалізованих ідентифікаторів репозиторіїв у нижньому регістрі (host/owner/repo). Явно вказані ідентифікатори профілів диспетчеризації мають пріоритет.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Профіль хмарного воркера для проєкту`},help:{"v1-1mux5u0-30":`Назва профілю хмарного воркера, який використовується за замовчуванням, коли origin робочого дерева сеансу відповідає цьому ідентифікатору репозиторію.`}},"cloudWorkers%2ErequiredProfile":{label:{"v1-1rqoa9j-n":`Обов’язковий профіль виконавця`},help:{"v1-1q30qf7-57":`Вимагати виконання кожного сеансу з цим профілем виконавця. Сеанси розподіляються автоматично без можливості резервного виконання на Gateway. Недоступність виконавців блокує кроки сеансу, але не запуск Gateway.`}},commands:{label:{"v1-15x4mpf-8":`Команди`},help:{"v1-1gi0dr2-5a":`Керує інтерфейсами команд чату, обмеженнями доступу для власників і поведінкою привілейованого доступу до команд у різних постачальників. Залиште типові значення, якщо вам не потрібні суворіший контроль операторів або ширша доступність команд.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Правила привілейованого доступу до команд`},help:{"v1-7azkw-5g":`Визначає правила дозволу привілейованих команд за каналом і відправником для інтерфейсів команд рівня власника. Використовуйте конкретні ідентифікатори окремих постачальників, щоб привілейовані команди не були доступні широкій аудиторії чатів.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Дозволити команду Bash у чаті`},help:{"v1-83ah7w-36":"Дозволити команді bash у чаті (`!`; псевдонім `/bash`) виконувати команди оболонки хоста (типово: false; потребує tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Час роботи Bash на передньому плані (мс)`},help:{"v1-1o0o4dw-2c":`Скільки часу bash очікує перед переходом у фоновий режим (типово: 2000; 0 — негайний перехід у фоновий режим).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`Дозволити /config`},help:{"v1-151bb7c-21":`Дозволити команді /config у чаті читати й записувати конфігурацію на диску (типово: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`Дозволити /debug`},help:{"v1-y1lc3j-1y":`Дозволити команду /debug у чаті для перевизначень, що діють лише під час виконання (типово: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`Дозволити /mcp`},help:{"v1-1rtwcgd-2o":`Дозволити команді /mcp у чаті керувати конфігурацією серверів MCP OpenClaw у mcp.servers (типово: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Нативні команди`},help:{"v1-dighr2-5n":`Реєструє нативні слеш-команди та команди меню в каналах, які підтримують реєстрацію команд (Discord, Slack, Telegram). Залишайте ввімкненим, щоб команди було легко знайти, якщо тільки ви не використовуєте навмисно суто текстові сценарії роботи з командами.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Нативні команди навичок`},help:{"v1-19gtqci-5h":`Реєструє нативні команди навичок, щоб користувачі могли викликати навички безпосередньо з меню команд постачальника, де це підтримується. Узгоджуйте з вашою політикою навичок, щоб доступні команди відповідали очікуванням операторів.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Власники команд`},help:{"v1-1di38gv-3y":`Явний список дозволених власників для команд, доступних лише власникам. Використовуйте ідентифікатори відповідного каналу (за потреби з префіксом, як-от "whatsapp:+15551234567"). '*' ігнорується.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`Дозволити /plugins`},help:{"v1-akwy9y-33":`Дозволити команду чату /plugins для перегляду виявлених плагінів і їх увімкнення або вимкнення в конфігурації (типово: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Дозволити перезапуск`},help:{"v1-m32fv2-27":`Дозволити /restart, /update та зовнішні запити на перезапуск через SIGUSR2 (типово: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Текстові команди`},help:{"v1-1utu76s-5j":`Увімкнення розпізнавання текстових команд у повідомленнях чату на додачу до вбудованих інтерфейсів команд, де вони доступні. Залиште цей параметр увімкненим для сумісності з каналами, які не підтримують вбудовану реєстрацію команд.`}},cron:{label:{"v1-1qlte4b-b":`Автоматизації`},help:{"v1-4md8ic-5u":`Глобальні налаштування планувальника для збережених автоматизацій, паралельного виконання, резервної доставки та терміну зберігання сеансів виконання. Залиште типові значення, якщо не збільшуєте обсяг автоматизацій і не інтегруєте зовнішні приймачі вебхуків.`}},"cron%2Eagents":{label:{"v1-13sapf2-u":`Типові налаштування автоматизацій для кожного агента`},help:{"v1-15ynqdo-4x":`Типові налаштування автоматизацій для кожного агента з ідентифікатором агента як ключем. Кожна автоматизація використовує запис для свого фактичного агента (визначеного через agentId, а за його відсутності — через агента в ключі сеансу, інакше — типового агента).`}},"cron%2Eagents%2E*%2Edelivery":{label:{"v1-106qeoh-y":`Типове доставлення для автоматизацій агента`},help:{"v1-fgez3q-5r":"Типове місце призначення оголошень для автоматизацій цього агента, у яких не вказано маршрут. Повністю замінює `cron.delivery` для цього агента; поля не об’єднуються. Типові налаштування користувача, який створив завдання, мають вищий пріоритет."}},"cron%2Eagents%2E*%2EfailureAlert":{label:{"v1-15hpccn-11":`Маршрут сповіщень про збої автоматизацій агента`},help:{"v1-ppqxgd-6j":"Типовий маршрут сповіщень про збої (`mode`, `channel`, `to`, `threadId`, `accountId`) для автоматизацій цього агента. Повністю замінює поля маршруту в `cron.failureAlert`; `enabled`, `after`, `cooldownMs` та `includeSkipped` залишаються спільними для всього Gateway."}},"cron%2Ecreators":{label:{"v1-8luomx-w":`Типові налаштування автоматизацій для кожного автора`},help:{"v1-12liwzq-9q":`Типові налаштування автоматизацій для кожного автора з ідентифікатором профілю Gateway користувача, який створив автоматизацію, як ключем. Застосовуються лише тоді, коли в автоматизації записано профіль користувача-автора (безпосередньо або як профіль, що делегував створення агенту); застарілі автоматизації та автоматизації, авторів яких визначено лише за каналом, невідомих авторів, агентів або системи не використовують записи авторів. Ключі мають збігатися точно.`}},"cron%2Ecreators%2E*%2Edelivery":{label:{"v1-85aipy-10":`Типове доставлення для автоматизацій автора`},help:{"v1-ybgvfk-4j":"Типове місце призначення оголошень для автоматизацій цього користувача, у яких не вказано маршрут. Має вищий пріоритет за `cron.agents.<agentId>.delivery` і `cron.delivery`; повністю замінює їх."}},"cron%2Ecreators%2E*%2EfailureAlert":{label:{"v1-1e8apq2-13":`Маршрут сповіщень про збої автоматизацій автора`},help:{"v1-mlj76p-7m":"Стандартний маршрут сповіщень про збої (`mode`, `channel`, `to`, `threadId`, `accountId`) для автоматизацій цієї особи. Має пріоритет над маршрутом агента-власника та повністю замінює поля маршруту `cron.failureAlert`; `enabled`, `after`, `cooldownMs` та `includeSkipped` залишаються спільними для всього Gateway."}},"cron%2EdefaultTools":{label:{"v1-huhclk-o":`Типові інструменти автоматизації`},help:{"v1-1x80rr1-7x":`Інструменти, що додаються, коли інструмент automations створює або явно змінює непорожній список toolsAllow, перед перевірками політики автора та схваленням. Якщо не задано, нічого не додається. Щоб відмовитися від додавання, використайте toolsAllowMode: "exact" у цьому запиті; [] залишається без інструментів. Наявні завдання та не пов’язані з цим зміни залишаються без змін.`}},"cron%2Edelivery":{label:{"v1-11v82ye-s":`Стандартна доставка для автоматизацій`},help:{"v1-1rndf98-aj":"Спільне для всього Gateway стандартне місце призначення оголошень для автоматизацій без власного маршруту (не вказано каналу, відмінного від `last`, полів `to`, `threadId`, `accountId` або адресування власнику). Воно замінює збережений маршрут сеансу під час виконання й ніколи не застосовується до доставки `none` або `webhook`. Стандартні налаштування `cron.creators.<profileId>.delivery` або `cron.agents.<agentId>.delivery` мають пріоритет над цими."}},"cron%2Edelivery%2EaccountId":{label:{"v1-192kjm5-10":`Стандартний обліковий запис доставки для автоматизацій`},help:{"v1-1ishqby-2j":`Необов’язковий обліковий запис каналу для стандартного місця призначення, якщо канал має кілька облікових записів.`}},"cron%2Edelivery%2Echannel":{label:{"v1-b4tjph-10":`Стандартний канал доставки для автоматизацій`},help:{"v1-x3hpfs-39":"Канал для стандартного місця призначення, наприклад `telegram`. Не вказуйте його, щоб визначати канал через `last` для стандартного одержувача."}},"cron%2Edelivery%2EthreadId":{label:{"v1-16jecza-z":`Стандартна гілка доставки для автоматизацій`},help:{"v1-12h3hbw-2g":`Необов’язкова гілка або тема форуму для стандартного місця призначення, наприклад ідентифікатор теми Telegram.`}},"cron%2Edelivery%2Eto":{label:{"v1-1iipxgp-12":`Стандартний одержувач доставки для автоматизацій`},help:{"v1-1odj9jz-3j":"Одержувач для місця призначення за замовчуванням у форматі адресації каналу (наприклад, ідентифікатор чату Telegram, як-от `-100123456789`)."}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Автоматизації ввімкнено`},help:{"v1-y8otx6-5i":`Увімкнення виконання автоматизацій за збереженими розкладами, якими керує шлюз. Залиште ввімкненим для звичайної роботи нагадувань і автоматизацій. Вимикайте лише для призупинення всіх автоматизацій без видалення завдань.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Термін зберігання сеансів автоматизацій`},help:{"v1-4wagu6-7e":"Визначає, як довго зберігаються сеанси завершених запусків автоматизацій до очищення (`24h`, `7d`, `1h30m` або `false`, щоб вимкнути очищення; нульова тривалість, наприклад `0h`, також вимикає його; типове значення: `24h`). Використовуйте коротший термін зберігання, щоб зменшити зростання обсягу даних за частих запусків."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Пропускати пропущені повторювані автоматизації`},help:{"v1-w9wfmo-66":`Під час запуску Gateway пропускає пропущені запуски за повторюваними розкладами cron/every і натомість планує їхнє наступне виконання в майбутньому. Типове значення: false. Увімкніть, щоб уникнути застарілих нагадувань після простою; пропущені одноразові завдання at усе одно виконуються.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`Політика SSRF для вебхуків автоматизацій`},help:{"v1-1xlfqnu-5h":`Політика SSRF, що застосовується до кожного вихідного вебхука автоматизації. Приватні, петльові, локальні для каналу та внутрішні адреси призначення залишаються заблокованими, якщо ця політика явно їх не дозволяє. Залиште незаданою для суворого контролю доставки.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Дозволені імена хостів для вебхуків автоматизацій`},help:{"v1-1i94hyz-3n":`Точні імена хостів або літерали IP-адрес, дозволені для доставки вебхуків автоматизацій, зокрема адреси призначення, які інакше були б заблоковані. Залишайте список мінімальним.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Дозволити діапазон унікальних локальних IPv6-адрес для вебхуків автоматизацій`},help:{"v1-rke0oj-3b":`Дозволяє вебхуки автоматизацій на унікальні локальні IPv6-адреси (fc00::/7). Використовуйте лише в довірених проксі-середовищах із fake-IP.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Дозволити діапазон тестування продуктивності RFC 2544 для вебхуків автоматизацій`},help:{"v1-x1usg4-3h":`Дозволяє вебхукам автоматизацій звертатися до IP-адрес із діапазону для тестування продуктивності RFC 2544 (198.18.0.0/15). Використовуйте лише в довірених проксі-середовищах із підставними IP-адресами.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Заблоковані імена хостів для вебхуків автоматизацій`},help:{"v1-16cv1ic-6a":`Шаблони імен хостів, які блокуються до визначення DNS і застосування правил дозволу під час доставки вебхуків автоматизацій. Підтримуються точні імена хостів і "*.example.com" лише для піддоменів; щоб заблокувати кореневий домен, додайте "example.com" окремо. Порожнє або невстановлене значення не додає заборон.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Небезпечний дозвіл доступу до приватної мережі для вебхуків автоматизацій`},help:{"v1-1n9710c-3t":`Дозволяє вебхукам автоматизацій звертатися до ресурсів приватних і внутрішніх мереж. Залишайте вимкненим, якщо не всі налаштовані адреси призначення вебхуків є довіреними.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Токен Bearer для вебхуків автоматизацій`},help:{"v1-1l90hxg-5l":`Токен Bearer, що додається до POST-запитів доставки вебхуків автоматизацій у режимі вебхука. Надавайте перевагу підставлянню із секретів або змінних середовища та регулярно змінюйте цей токен, якщо спільні кінцеві точки вебхуків доступні з інтернету.`}},database:{label:{"v1-1ur2pjs-8":`База даних`},help:{"v1-zxclpq-90":`Вибір рушія бази даних. SQLite використовується за замовчуванням; PostgreSQL — підтримувана альтернатива для п’яти налаштовуваних сімейств. Doctor повідомляє про налаштовані та фактично виявлені рушії й попереджає про невідповідності, відсутні можливості або недоступні сховища. Відомості про обмеження перевірки сумісності платформ і оновлень див. у посібнику оператора PostgreSQL.`}},"database%2Eengine":{label:{"v1-we5l2i-f":`Рушій бази даних`},help:{"v1-6hsgz2-6j":`Рушій сховища за замовчуванням (типово: sqlite). PostgreSQL підтримує state, agent, workboard, logbook і team-reports, якщо database.families не перевизначає їх; сховища безпеки залишаються в локальній SQLite. Зміна рушія не переносить наявні дані.`}},"database%2Efamilies":{label:{"v1-1xrm7s9-n":`Рушії баз даних сімейств`},help:{"v1-12i1jst-75":`Необов’язкові перевизначення рушія для state, agent, workboard, logbook і team-reports. Кожне перевизначення потребує engine. Групи state і agent можуть використовувати різні рушії; локальні журнали безпеки не налаштовуються. Усі групи PostgreSQL спільно використовують database.postgres.`}},"database%2Efamilies%2Eagent%2Eengine":{label:{"v1-1e7sns0-m":`Рушій бази даних сімейства`},help:{"v1-fv44v3-77":`Перевизначення database.engine для цієї групи. Зміна рушія потребує виконання database port --family та перезапуску; редагування конфігурації не переносить наявні дані. Резервне копіювання та відновлення з різними рушіями зберігає рушій кожного сховища, а оновлення потребують підтримки відповідних груп у версії-кандидаті.`}},"database%2Efamilies%2Elogbook%2Eengine":{label:{"v1-1e7sns0-m":`Рушій бази даних сімейства`},help:{"v1-fv44v3-77":`Перевизначення database.engine для цієї групи. Зміна рушія потребує виконання database port --family та перезапуску; редагування конфігурації не переносить наявні дані. Резервне копіювання та відновлення з різними рушіями зберігає рушій кожного сховища, а оновлення потребують підтримки відповідних груп у версії-кандидаті.`}},"database%2Efamilies%2Estate%2Eengine":{label:{"v1-1e7sns0-m":`Рушій бази даних сімейства`},help:{"v1-fv44v3-77":`Перевизначає database.engine для цієї групи. Для зміни рушія потрібні команда database port --family і перезапуск; редагування конфігурації не переносить наявні дані. Резервне копіювання та відновлення зі змішаними рушіями зберігають рушій кожного сховища, а оновлення потребують підтримки цієї групи у версії-кандидаті.`}},"database%2Efamilies%2Eteam-reports%2Eengine":{label:{"v1-1e7sns0-m":`Рушій бази даних сімейства`},help:{"v1-fv44v3-77":`Перевизначає database.engine для цієї групи. Для зміни рушія потрібні команда database port --family і перезапуск; редагування конфігурації не переносить наявні дані. Резервне копіювання та відновлення зі змішаними рушіями зберігають рушій кожного сховища, а оновлення потребують підтримки цієї групи у версії-кандидаті.`}},"database%2Efamilies%2Eworkboard%2Eengine":{label:{"v1-1e7sns0-m":`Рушій бази даних сімейства`},help:{"v1-fv44v3-77":`Перевизначає database.engine для цієї групи. Для зміни рушія потрібні команда database port --family і перезапуск; редагування конфігурації не переносить наявні дані. Резервне копіювання та відновлення зі змішаними рушіями зберігають рушій кожного сховища, а оновлення потребують підтримки цієї групи у версії-кандидаті.`}},"database%2Epostgres":{label:{"v1-11caiz7-a":`PostgreSQL`},help:{"v1-1hstnlv-7j":`Підключення до PostgreSQL та іменування схем. PostgreSQL 16–18 пройшли перевірку сумісності; інші дозволені основні версії залишаються експериментальними до підтвердження відповідності. Створюйте резервну копію кожної схеми сховища разом із її локальною опорною базою SQLite. Обмеження щодо перевірених конфігурацій розгортання наведено в посібнику оператора PostgreSQL.`}},"database%2Epostgres%2Econnection":{label:{"v1-17ej0zp-l":`Підключення до PostgreSQL`},help:{"v1-1gbko0p-9s":`Спільний DSN PostgreSQL, обов’язковий, якщо фактично використовуваний рушій будь-якого сімейства — postgres. Підтримує SecretRefs типів env, file та exec, а також з’єднання TLS; відомості про налаштування та обмеження сумісності див. у посібнику оператора PostgreSQL. Посилання на секрети зі сховища не можна використовувати для початкового запуску бази даних. Хост одноразово визначає значення DSN для робочих процесів бази даних. У разі помилок з’єднання перехід на SQLite ніколи не відбувається.`}},"database%2Epostgres%2Eownership":{label:{"v1-87ucg-s":`Володіння станом Gateway у PostgreSQL`},help:{"v1-1e7fkqn-cj":`Область володіння станом Gateway (типово: state-directory, локальний файл блокування). Режим installation також утримує рекомендаційне блокування сеансу PostgreSQL із ключем на основі бази даних і префікса схеми, тому другому Gateway або власнику процесу обслуговування тієї самої інсталяції буде відмовлено на будь-якому хості, а втрата цього сеансу зупинить Gateway. Потрібно, щоб усі групи з можливістю налаштування використовували postgres. Прив’язки сховища та інші локальні файли залишаються без змін; див. посібник оператора PostgreSQL.`}},"database%2Epostgres%2ErecoveryCaptures":{label:{"v1-dlnk9p-s":`Знімки PostgreSQL для відновлення`},help:{"v1-1qes8ml-9m":`Де зберігаються рядки PostgreSQL у знімках для відкочування оновлень і змін Doctor (типово: portable). portable записує локальний образ експорту SQLite. server зберігає рядки у схемі restore_ тієї самої бази даних, а локально записує лише опорні дані та маніфест; це заощаджує місце на локальному диску й час експорту, але дані буде втрачено в разі втрати сервера. Резервні копії користувача залишаються переносними.`}},"database%2Epostgres%2EschemaPrefix":{label:{"v1-1s0mt2q-o":`Префікс схем PostgreSQL`},help:{"v1-1a5738a-7o":`Префікс для нових схем сховища PostgreSQL (за замовчуванням: openclaw). Використовуйте від 1 до 27 малих латинських літер, цифр або символів підкреслення, починаючи з літери або символу підкреслення. Префікс pg і префікси, що починаються з pg_, утворюють зарезервовані назви схем PostgreSQL. Наявні якорі зберігають свою схему.`}},desktop:{label:{"v1-rs698z-7":`Робочий стіл`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Локальний робочий стіл`},help:{"v1-99weio-30":`Перегляд робочого столу сполучених вузлів або експериментального джерела хоста Gateway через локальний сервер VNC.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Спільний доступ до робочого столу`},help:{"v1-m9lbcj-83":`Вмикає джерело робочого столу цього комп’ютера. Для спарених вузлів macOS, Windows і Linux воно ввімкнене за замовчуванням; явно задане налаштування спільного доступу в настільному застосунку має пріоритет. Джерело Labs на хості Gateway за замовчуванням вимкнене й застосовує зміни одразу. Перезапустіть спарений вузол після зміни його конфігурації робочого столу.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Керований робочий стіл хоста Linux`},help:{"v1-1r7n22m-49":`Запускає та контролює робочий стіл TigerVNC/XFCE на Linux без фізичного дисплея, доступний лише через loopback. Явно вказаний порт або наявний сервер VNC на стандартному порту й надалі має пріоритет.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Локальний файл пароля VNC`},help:{"v1-1m5lsox-37":`Абсолютний шлях до файлу пароля VNC. У macOS не вказуйте його, щоб вводити облікові дані під час відкриття засобу перегляду робочого столу.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Локальний порт VNC`},help:{"v1-1ku4w9b-2b":`Порт RFB на інтерфейсі зворотного зв’язку сервера VNC, що вже працює на цьому комп’ютері (типово: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Діагностика`},help:{"v1-1d5rnym-5p":`Налаштування діагностики для цільового трасування, експорту телеметрії та перевірки кешу під час налагодження. У виробничому середовищі підтримуйте мінімальний рівень базової діагностики та вмикайте докладніші діагностичні дані лише під час дослідження проблем.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Трасування кешу`},help:{"v1-10523zm-5b":`Налаштування журналювання трасування кешу для спостереження за рішеннями щодо кешування та контекстом корисного навантаження під час вбудованих запусків. Вмикайте тимчасово для налагодження та вимикайте після нього, щоб зменшити обсяг конфіденційних даних у журналах.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Трасування кешу ввімкнено`},help:{"v1-2c1umi-1v":`Записувати до журналу знімки трасування кешу для вбудованих запусків агента (типово: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Діагностику ввімкнено`},help:{"v1-a46pxt-4h":`Головний перемикач виведення діагностичних даних у журнали та канали телеметрії. Типово ввімкнено; задавайте false лише в середовищах із жорсткими обмеженнями.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Прапорці діагностики`},help:{"v1-x4w5ok-33":`Увімкніть цільове діагностичне журналювання за прапорцем (наприклад, ["telegram.http"]). Підтримуються шаблони на кшталт "telegram.*" або "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Налаштування експорту OpenTelemetry для трасувань, метрик і журналів, які створюють компоненти Gateway. Використовуйте їх для інтеграції з централізованими системами спостережуваності та конвеєрами розподіленого трасування.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`Збирання вмісту OpenTelemetry`},help:{"v1-19tid4t-2t":`Збирання вмісту сегментів трасування OTEL, яке вмикається за бажанням. За замовчуванням вимкнено; значення true вмикає збирання вмісту несистемних повідомлень та інструментів.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry увімкнено`},help:{"v1-193bm0-5b":`Вмикає конвеєр експорту OpenTelemetry для трасувань, метрик і журналів відповідно до налаштувань кінцевої точки та протоколу. Залишайте вимкненим, доки кінцеву точку колектора й автентифікацію не буде повністю налаштовано.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`Кінцева точка OpenTelemetry`},help:{"v1-4rrd1x-4y":`URL кінцевої точки колектора для передавання експортованих даних OpenTelemetry, включно зі схемою та портом. Використовуйте доступну й довірену кінцеву точку колектора та відстежуйте помилки приймання даних після розгортання.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`Інтервал вивантаження OpenTelemetry (мс)`},help:{"v1-1moqogc-53":`Інтервал у мілісекундах для періодичного вивантаження телеметрії з буферів до колектора. Збільште його, щоб зменшити частоту передавання даних, або зменште, щоб швидше отримувати дані під час активного реагування на інцидент.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`Заголовки OpenTelemetry`},help:{"v1-s26t2a-52":`Додаткові заголовки HTTP-запитів, що надсилаються із запитами експорту OpenTelemetry та часто використовуються для автентифікації орендаря або маршрутизації. Зберігайте секрети у значеннях, що беруться зі змінних середовища, і уникайте зайвого розростання набору заголовків.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`Журнали OpenTelemetry увімкнено`},help:{"v1-12wo6rv-4k":`Увімкніть експорт сигналів журналів через OpenTelemetry на додачу до локальних приймачів журналів. Використовуйте це, коли потрібна централізована кореляція журналів між службами й агентами.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`Кінцева точка журналів OpenTelemetry`},help:{"v1-1vgzldu-40":`Кінцева точка OTLP/HTTP для сигналу журналів. Якщо задано, перевизначає diagnostics.otel.endpoint і OTEL_EXPORTER_OTLP_ENDPOINT лише для експорту журналів.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`Експортер журналів OpenTelemetry`},help:{"v1-9bzywd-5q":`Приймач експорту журналів для diagnostics.otel.logs. Використовуйте "otlp" для налаштованої кінцевої точки журналів OTLP, "stdout" — для виведення одного запису JSON у кожному рядку stdout у конвеєрах журналів контейнерів, а "both" — коли потрібні обидва приймачі.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`Префікс назв метрик OpenTelemetry`},help:{"v1-1epdpi9-b2":`Замінює стандартний префікс "openclaw." у назвах власних метрик OpenClaw. Використовуйте порожній рядок, щоб видалити префікс, або до 128 символів ASCII: літер, цифр, підкреслень, крапок, дефісів і скісних рисок, починаючи з літери. Додайте потрібний роздільник, наприклад "acme."; стандартні назви метрик gen_ai.* залишаються незмінними. Зміна цього значення потребує оновлення панелей моніторингу та сповіщень, які використовують старі назви в запитах.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`Метрики OpenTelemetry увімкнено`},help:{"v1-13r4cf4-4x":`Увімкніть експорт метрик до налаштованої кінцевої точки колектора OpenTelemetry. Залишайте ввімкненим для панелей моніторингу стану під час роботи й вимикайте лише за потреби мінімізувати обсяг метрик.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`Кінцева точка метрик OpenTelemetry`},help:{"v1-qlfh7x-47":`Окрема кінцева точка OTLP/HTTP для метрик. Якщо задано, перевизначає diagnostics.otel.endpoint і OTEL_EXPORTER_OTLP_ENDPOINT лише для експорту метрик.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`Протокол OpenTelemetry`},help:{"v1-17ine8s-5e":`Транспортний протокол OTel для експорту телеметрії. Допускається лише "http/protobuf"; виконайте "openclaw doctor --fix", щоб виправити збережене застаріле значення "grpc" або отримати вказівки щодо ручного редагування для відповідного джерела.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`Частка вибірки трасувань OpenTelemetry`},help:{"v1-brcwep-50":`Частка вибірки трасувань (0-1), що визначає обсяг даних трасування, які експортуються до серверних систем спостережуваності. Менші значення знижують накладні витрати й вартість, а більші підвищують точність налагодження.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`Назва сервісу OpenTelemetry`},help:{"v1-1hpiqon-5d":`Назва сервісу, що передається в атрибутах ресурсу телеметрії для ідентифікації цього екземпляра Gateway у серверних системах спостережуваності. Використовуйте сталі назви, щоб панелі моніторингу та сповіщення залишалися узгодженими між розгортаннями.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`Трасування OpenTelemetry ввімкнено`},help:{"v1-j7zrrp-4s":`Увімкніть експорт трасувань до налаштованої кінцевої точки колектора OpenTelemetry. Залишайте ввімкненим, коли потрібне трасування затримок або налагодження, і вимикайте, якщо потрібні лише метрики й журнали.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`Кінцева точка трасувань OpenTelemetry`},help:{"v1-8yw5p1-43":`Кінцева точка трасувань OTLP/HTTP для окремого типу сигналу. Якщо задано, перевизначає diagnostics.otel.endpoint і OTEL_EXPORTER_OTLP_ENDPOINT лише для експорту трасувань.`}},discovery:{label:{"v1-l2sr05-9":`Виявлення`},help:{"v1-1sqleij-4w":`Налаштування виявлення служб для локальних оголошень mDNS і необов’язкового сповіщення про присутність у глобальній мережі. Обмежуйте виявлення очікуваними мережами, щоб уникнути витоку метаданих служб.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`Виявлення через mDNS`},help:{"v1-vtbyyq-4w":`Група налаштувань виявлення через mDNS для оголошень у локальній мережі та налаштування поведінки виявлення. Залишайте мінімальний режим для звичайного виявлення в LAN, якщо додаткові метадані не потрібні.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`Режим виявлення через mDNS`},help:{"v1-1p28pd5-2m":`Режим широкомовлення mDNS («minimal» за замовчуванням, «full» включає cliPath/sshPort, «off» вимикає mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Виявлення в глобальній мережі`},help:{"v1-1akkqjm-53":`Група налаштувань виявлення в глобальній мережі для поширення сигналів виявлення за межі локального сегмента. Вмикайте лише в розгортаннях, де навмисно збирають інформацію про присутність Gateway з різних майданчиків.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Домен виявлення в глобальній мережі`},help:{"v1-rxrygo-4m":`Необов’язковий домен одноадресного DNS-SD для виявлення в глобальній мережі, наприклад openclaw.internal. Використовуйте, якщо навмисно публікуєте дані виявлення Gateway за межами локальної області mDNS.`}},env:{label:{"v1-1zc80q-b":`Середовище`},help:{"v1-1ao5po6-55":`Налаштування імпорту та перевизначення середовища для передавання змінних часу виконання процесу Gateway. Використовуйте цей розділ, щоб керувати завантаженням середовища оболонки та явним додаванням змінних.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Імпорт середовища оболонки`},help:{"v1-1gw487t-4y":`Налаштування імпорту середовища оболонки для завантаження змінних з оболонки входу під час запуску. Залиште цю функцію ввімкненою, якщо ви залежите від секретів, визначених у профілі, або налаштувань PATH.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Імпорт середовища оболонки ввімкнено`},help:{"v1-5tiuup-5u":`Вмикає завантаження змінних середовища з профілю оболонки користувача під час ініціалізації запуску. Залиште ввімкненим на комп’ютерах розробників або вимкніть у суворо обмежених сервісних середовищах із явним керуванням змінними середовища.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Час очікування імпорту середовища оболонки (мс)`},help:{"v1-nsk2yf-5c":`Максимальний час у мілісекундах, відведений на визначення середовища оболонки, перш ніж буде застосовано резервну поведінку. Установіть коротший час очікування для швидшого запуску або збільште його, якщо ініціалізація оболонки потребує багато часу.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Перевизначення змінних середовища`},help:{"v1-1uloveo-5t":`Явні перевизначення змінних середовища у форматі ключ/значення, які додаються до середовища процесу OpenClaw під час виконання. Використовуйте це для передбачуваного налаштування середовища, а не покладайтеся лише на побічні ефекти профілю оболонки.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-1hooncl-5s":`Налаштування середовища виконання Gateway для режиму прив’язки, автентифікації, вебзастосунку, віддаленого транспорту та засобів безпеки роботи. Зберігайте обережні типові налаштування, якщо не плануєте навмисно відкривати доступ до шлюзу за межами довірених локальних інтерфейсів.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Дозволити резервне використання x-real-ip у Gateway`},help:{"v1-1wr3qmw-4c":`Вмикає резервне використання x-real-ip за відсутності x-forwarded-for під час роботи через проксі. Залиште вимкненим, якщо ваш стек обробки вхідного трафіку не потребує такої сумісності.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Автентифікація Gateway`},help:{"v1-70b6ni-50":`Політика автентифікації для доступу до Gateway через HTTP/WebSocket, зокрема режим, облікові дані, поведінка довіреного проксі та обмеження частоти запитів. Залишайте автентифікацію ввімкненою для кожного розгортання з доступом поза межами локального інтерфейсу loopback.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Дозволити автентифікацію Gateway за ідентичністю Tailscale`},help:{"v1-vqtmgw-53":`Дозволяє проходити перевірки автентифікації Gateway через довірені механізми ідентифікації Tailscale, якщо їх налаштовано. Використовуйте це лише за надійного захисту ідентичностей у вашій мережі tailnet і якщо від цього залежать робочі процеси операторів.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Надання прав ідентичностям Gateway`},help:{"v1-1h0zxy7-5n":`Зіставляє ідентичності, перевірені довіреним проксі або Tailscale, з правами оператора, що надаються лише на час з’єднання. Ключі електронної пошти зіставляються без урахування регістру; надані права доповнюють права пристрою перед застосуванням обмеження прав для з’єднання.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Режим автентифікації Gateway`},help:{"v1-j8rodq-9t":`Режим автентифікації Gateway: "none", "token", "password" або "trusted-proxy" залежно від архітектури мережевого периметра. Режим token/password вибирає налаштований секрет (gateway.auth.token або gateway.auth.password); клієнти можуть надсилати його в будь-якому з полів автентифікації підключення. Використовуйте token/password для прямого доступу ззовні, а trusted-proxy — лише за проксі-серверами з посиленим захистом і перевіркою ідентичності.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Пароль Gateway`},help:{"v1-1ndt0u2-4g":`Спільний секрет, вибраний параметром gateway.auth.mode=password. Клієнти можуть надсилати його в auth.token або auth.password. Для Tailscale Funnel потрібен режим автентифікації за паролем.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Обмеження частоти спроб автентифікації Gateway`},help:{"v1-1kstr42-54":`Налаштування обмеження частоти спроб входу й автентифікації для зниження ризику підбору облікових даних на межі шлюзу. Залишайте увімкненими в середовищах із зовнішнім доступом і налаштовуйте порогові значення відповідно до звичайного рівня трафіку.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Токен Gateway`},help:{"v1-16i7cxs-5q":`Спільний секрет, що використовується за gateway.auth.mode=token — стандартного режиму для нового локального налаштування. Клієнти можуть надсилати його в auth.token або auth.password. Прив’язування до адрес поза loopback потребує увімкненого режиму автентифікації.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Автентифікація Gateway через довірений проксі`},help:{"v1-12fsi5d-58":`Зіставлення заголовків автентифікації через довірений проксі для постачальників ідентифікації перед шлюзом, які додають твердження про користувача. Використовуйте лише з відомими CIDR-діапазонами проксі та суворими списками дозволених заголовків, щоб запобігти підробленню заголовків ідентифікації.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Ідентичність GitHub через Cloudflare Access OIDC`},help:{"v1-1puth4k-6t":`Необов’язкова підтверджена ідентичність GitHub від вибраного провайдера Cloudflare Access OIDC. Потрібні стандартні заголовки Access для електронної пошти та твердження автентифікації. За відсутності атрибутів профілі залишаються прив’язаними лише до електронної пошти; наявні ролі профілів і налаштування співавторства зберігаються.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Атрибут ідентифікатора облікового запису GitHub`},help:{"v1-qd4qvh-87":`Точна назва переданого атрибута OIDC, значенням якого є перевірений ідентифікатор облікового запису GitHub у вигляді рядка з додатним десятковим числом. Налаштуйте Access для його передавання, а потім перевірте відповідь Access із даними автентифікованої особи. OpenClaw читає oidc_fields або custom, якщо oidc_fields відсутнє. Ніколи не використовуйте неперевірений атрибут, який користувач може редагувати.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Видавець Cloudflare Access`},help:{"v1-gykv03-56":`Точна базова HTTPS-адреса довіреної команди Cloudflare Access, наприклад https://example.cloudflareaccess.com, без кінцевої скісної риски. Твердження від інших видавців не надають ідентифікаційних даних GitHub.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`Ідентифікатор постачальника OIDC Cloudflare Access`},help:{"v1-kbyo5w-44":`Точний ідентифікатор постачальника ідентифікаційних даних Access для довіреної інтеграції OIDC. Сама лише відображувана назва постачальника або відповідна назва твердження не встановлює довіри.`}},"gateway%2Eauth%2EtrustedProxy%2Edelegation":{label:{"v1-gzv594-t":`Делегування для корпоративного браузера`},help:{"v1-1i9071w-4d":`Приймати ідентифікаційні дані браузера OCE та дозволи на області доступу, прив’язані до ревізії, через приватний довірений проксі. Делеговані профілі не використовують псевдоніми електронної пошти чи дозволи для пристроїв.`}},"gateway%2Eauth%2EtrustedProxy%2Edelegation%2EcredentialFile":{label:{"v1-vi5w92-q":`Файл облікових даних делегування`},help:{"v1-1tfpp2u-4t":`Абсолютний шлях до приватного файлу, що містить 32-байтові облікові дані ревізії у вигляді 64 шістнадцяткових символів у нижньому регістрі. Заміна або видалення файлу робить наявні дозволи недійсними.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Автоматичне схвалення пристроїв через довірений проксі`},help:{"v1-uh32ha-6z":`Необов’язкова політика автоматичного схвалення нових пристроїв операторів із браузерним або нативним інтерфейсом, а також розширення прав доступу для того самого ключа після автентифікації через довірений проксі. Надані права обмежуються deviceAutoApprove.scopes і заголовком проксі x-openclaw-scopes, якщо він наявний.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Автоматичне схвалення пристроїв через довірений проксі увімкнено`},help:{"v1-1nntwls-78":`Автоматично схвалює нові пристрої операторів із браузерним або нативним інтерфейсом, а також розширення прав доступу для того самого ключа після того, як зворотний проксі автентифікує дозволеного користувача. Типове значення: false. Увімкніть лише тоді, коли захист ідентифікації на межі проксі достатньо надійний, щоб замінити ручне сполучення пристроїв.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Області доступу для автоматичного схвалення пристроїв через довірений проксі`},help:{"v1-raeila-g3":`Максимальні області доступу, що надаються автоматично схваленим пристроям операторів. За замовчуванням: operator.read, operator.write, operator.approvals і operator.questions. Запитувані області доступу обмежуються цим списком; запити без зазначених областей доступу отримують увесь цей список. Якщо значення не задано, автоматичне схвалення також додає operator.questions для старіших клієнтів інтерфейсу; явно заданий список ніколи не розширюється. Явне додавання operator.admin дозволяє кожному користувачеві, автентифікованому через проксі, автоматично отримувати повні права адміністратора, а запитам без зазначених областей доступу — отримувати їх автоматично; це також спричиняє критичне зауваження під час аудиту безпеки та попередження під час запуску Gateway.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor":{help:{"v1-dai5ie-71":`Необов’язкові стандартні дані співавтора від організації із заголовків проксі-сервера для автентифікованого користувача. Проксі-сервер має перезаписувати ці поля. Вони не підтверджують обліковий запис GitHub і не надають дозволів; перш ніж надані адреси електронної пошти з’являться в історії комітів, потрібно зберегти згоду на їх використання.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor%2EemailHeader":{help:{"v1-1j8gxp7-2h":`Заголовок, що містить надану організацією адресу електронної пошти для зазначення авторства комітів автентифікованого користувача.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor%2EemailVerifiedHeader":{help:{"v1-64bvpw-49":`Необов’язковий заголовок, значення якого має дорівнювати true перед імпортом стандартних даних організації. Не вказуйте його лише тоді, коли підтвердження адреси електронної пошти проксі-сервером достатньо за вашою політикою.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor%2EnameHeader":{help:{"v1-14uvheq-2c":`Заголовок, що містить ім’я співавтора в організації для автентифікованого суб’єкта.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Режим прив’язки Gateway`},help:{"v1-1unqude-4y":`Профіль мережевої прив’язки: "auto", "lan", "loopback", "custom" або "tailnet" для керування доступністю інтерфейсів. Залиште "loopback" для роботи лише локально; "auto" може зробити доступними всі інтерфейси.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`Агенти CLI`},help:{"v1-1unx5p8-57":`Виявлення у вебзастосунку зовнішніх рушіїв сеансів CLI, доступних через каталог сеансів Gateway. Типово ввімкнено; вимкніть, щоб заборонити запуск цих рушіїв у засобі вибору моделі для нового сеансу.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`Агенти CLI увімкнені`},help:{"v1-9ei1mn-8m":`За значення true показує агентів CLI з каталогів у засобі вибору моделі для нового сеансу у вебзастосунку (типово: true). Установіть false, щоб вимкнути агентів CLI та створення нативних сеансів CLI. У списку відображаються лише каталоги, які заявляють про підтримку створення сеансів, а засіб вибору залишається прихованим, якщо Gateway не заявляє про підтримку каталогу сеансів.`}},"gateway%2EcontrolUi":{label:{"v1-zyppo6-7":`Вебзастосунок`},help:{"v1-v2rtyb-5f":`Налаштування розміщення вебзастосунку, зокрема ввімкнення, шляхи та посилення захисту джерел браузера й автентифікації. Мінімізуйте доступність інтерфейсу та забезпечте надійний контроль автентифікації перед розгортанням із доступом з інтернету.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-14ny3x-n":`Дозволені джерела вебзастосунку`},help:{"v1-1br04sw-aq":`Дозволені джерела браузера для підключень до вебзастосунку/WebChat (лише повні адреси джерел, наприклад https://control.example.com). Якщо не вказано, за замовчуванням використовується gateway.publicOrigin, якщо його налаштовано. Явно заданий список, зокрема [], перевизначає це значення за замовчуванням; чинні правила для локальних і приватних джерел залишаються в силі. Значення ["*"] дозволяє будь-яке джерело браузера, і його слід уникати поза межами суворо контрольованого локального тестування.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-ylb79x-x":`Дозволити зовнішні URL для вбудованого вмісту вебзастосунку`},help:{"v1-y8g73z-62":`НЕБЕЗПЕЧНИЙ перемикач, що дозволяє розміщеному вбудованому вмісту завантажувати абсолютні зовнішні URL http(s). Залишайте його вимкненим, якщо ваш вебзастосунок не призначений для вбудовування довірених сторонніх сторінок; розміщеним документам /__openclaw__/canvas він не потрібен.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Автоматично завантажувати значки сайтів для посилань`},help:{"v1-1dimlov-ac":`Завантажувати значки сайтів для посилань і попередні перегляди сторінок за зовнішніми посиланнями через Gateway (увімкнено за замовчуванням). Для попереднього перегляду завантажуються загальнодоступні метадані сторінок і вказані в них зображення без файлів cookie браузера чи облікових даних сайтів. Для всіх запитів застосовуються суворі перевірки SSRF і обмеження на обробку HTML та зображень. Установіть false, щоб вимкнути автоматичне завантаження як значків сайтів, так і попередніх переглядів сторінок; це не впливає на знімки екрана браузера в реальному часі.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-zclsby-h":`Базовий шлях вебзастосунку`},help:{"v1-npn03b-1t":`Необов’язковий префікс URL, за яким доступний вебзастосунок (наприклад /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-13uozha-s":`Запрошення до спільноти у вебзастосунку`},help:{"v1-1m3mu0g-7i":`Показувати на бічній панелі вебзастосунку картку «Спільнота», яку можна приховати (увімкнено за замовчуванням), із посиланнями на Discord, Reddit і X. Установіть false, щоб приховати її в усіх браузерах, які використовують це розгортання інтерфейсу. Зміни застосовуються після оновлення сторінки в браузері або повторного підключення. Попередні приховування, збережені локально в браузері, залишаються чинними.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Небезпечно дозволити резервне визначення джерела за заголовком Host`},help:{"v1-1i3oa94-7s":`НЕБЕЗПЕЧНИЙ перемикач, який дозволяє визначати джерело за заголовком Host як запасний варіант під час перевірок WebSocket у вебзастосунку/WebChat. Цей режим підтримується, якщо ваше розгортання навмисно використовує політику джерел на основі заголовка Host; явне налаштування gateway.controlUi.allowedOrigins залишається рекомендованим захищеним варіантом за замовчуванням.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-kc00jb-q":`Режим пісочниці для вбудованого вмісту вебзастосунку`},help:{"v1-176jrc2-79":'Політика пісочниці iframe для вбудованого вмісту у вебзастосунку. "strict" вимикає скрипти, "scripts" дозволяє інтерактивний вміст зі збереженням ізоляції джерел (за замовчуванням), а "trusted" додає `allow-same-origin` для документів із того самого сайту, яким свідомо надаються розширені привілеї.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-vpzojz-f":`Вебзастосунок увімкнено`},help:{"v1-1u14fve-4l":`За значення true вмикає обслуговування вебзастосунку HTTP-процесом шлюзу. Залишайте ввімкненим для локального адміністрування та вимикайте, коли його замінює зовнішній інтерфейс керування.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-1d85isf-j":`Середовище вебзастосунку`},help:{"v1-vlhh70-4k":`Необов’язкове публічне позначення середовища, яке відображається на смузі вебзастосунку, аватарі агента, мітках, у заголовку браузера та значку сайту. Не вказуйте його, щоб зберегти стандартний вигляд.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-1h2k80-p":`Колір середовища вебзастосунку`},help:{"v1-mp6cta-2i":`Іменована колірна шкала середовища: teal, amber, purple, coral, pink, blue, green, red або gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-vrxwqd-p":`Мітка середовища вебзастосунку`},help:{"v1-1l8ng2x-3w":`Мітка середовища, що відображається у вебзастосунку та на вкладці браузера; пробільні символи на початку й у кінці видаляються, а мітка має містити від 1 до 24 символів.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-1oh9bbh-t":`Експериментальні функції вебзастосунку`},help:{"v1-d3p8ng-3m":`Експериментальні функції вебзастосунку та збережені розширені перевизначення. Експериментальні функції типово вимкнено, якщо в описі відповідного налаштування не зазначено інше.`}},"gateway%2EcontrolUi%2Eexperimental%2EchatBubbles":{label:{"v1-1i4j62s-e":`Бульбашки повідомлень`},help:{"v1-19ex4en-5j":`Увімкнути експериментальні бульбашки повідомлень у вебзастосунку (типово: false). Коли цю функцію ввімкнено, на головній сторінці типово використовуються бульбашки; збережені в браузері налаштування окремих сеансів мають пріоритет. Зміни застосовуються без перезапуску Gateway.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Інтерфейс користувацьких плагінів`},help:{"v1-18073xm-by":`Дозволити ввімкненим плагінам, установленим користувачем, виконувати нативний JavaScript у вебзастосунку (типово: true). Збережено як розширену можливість вимкнення лише через конфігурацію; наявні значення false залишають функцію вимкненою. Це не впливає на подання вбудованих плагінів. Нативний інтерфейс використовує ті самі дозволи Gateway, що й оператор, який увійшов у систему; установлюйте лише довірені плагіни. Зміни застосовуються без перезапуску Gateway. Після вимкнення перезавантажте відкриті сторінки вебзастосунку, щоб очистити раніше завантажений код плагінів.`}},"gateway%2EcontrolUi%2Eexperimental%2Etemplates":{label:{"v1-it5x1k-9":`Шаблони`},help:{"v1-1879y2q-3u":`Увімкнути пошук у ClawHub та одностороннє додавання через вебзастосунок і Gateway (типово: false). Наявні агенти продовжують працювати, навіть коли цю функцію вимкнено.`}},"gateway%2EcontrolUi%2Egithub%2Ehost":{label:{"v1-rjp3f8-r":`Хост служби GitHub для вебзастосунку`},help:{"v1-qaa5xb-3z":`Хост, до якого ці облікові дані служби можуть надавати доступ. Не вказуйте для github.com; задайте значення gateway.github.host для виявлення проєктів Enterprise та отримання метаданих облікового запису.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1ia5u0n-x":`Облікові дані служби GitHub для вебзастосунку`},help:{"v1-uw4wdq-b5":`Облікові дані служби на основі SecretRef для пошуку проєктів у вебзастосунку та попереднього перегляду GitHub при наведенні без керованої ідентичності. Для Enterprise задайте gateway.controlUi.github.host; якщо хост не вказано, використовується github.com. Для попереднього перегляду при наведенні пріоритет має налаштована ідентичність GitHub вибраного агента. Резервне використання GH_TOKEN/GITHUB_TOKEN застосовується лише до github.com. Запити з невідповідними або недоступними обліковими даними відхиляються.`}},"gateway%2EcontrolUi%2EnewSessionModelDefaults":{label:{"v1-bxfhmu-q":`Типові налаштування моделі для нових сеансів`},help:{"v1-1r6o74t-98":`Виберіть "configured", щоб нові чернетки у вебзастосунку використовували налаштовані для вибраного агента модель, середовище виконання та параметри міркування за замовчуванням замість збережених варіантів. За замовчуванням: "last-used". Явно вибрані параметри чернеток і розмов залишаються доступними для редагування; швидкий режим і налаштування розміщення не змінюються. Застосовується після оновлення сторінки браузера або повторного підключення.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-1ke8erh-j":`Кореневий каталог ресурсів вебзастосунку`},help:{"v1-192j3ry-22":`Необов’язковий кореневий каталог файлової системи для ресурсів вебзастосунку (за замовчуванням — dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-zsqsj8-o":`Спостерігач сеансів вебзастосунку`},help:{"v1-1uilm4q-87":`Створює зведення про стан сеансів у реальному часі для підписаних клієнтів вебзастосунку за допомогою допоміжної моделі кожного агента (увімкнено за замовчуванням). Установіть false, щоб вимкнути виклики моделі спостерігача для всього шлюзу; порожній рядок у agents.defaults.utilityModel вимикає спостереження за допомогою допоміжної моделі для агентів, які не перевизначають цей параметр.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Власний хост прив’язки Gateway`},help:{"v1-lwjcyo-4d":`Адреса IPv4 для власної прив’язки. Для конкретних адрес IPv4 також потрібен той самий порт Gateway на 127.0.0.1; уникайте 0.0.0.0, якщо доступ через усі інтерфейси не потрібен.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`HTTP API Gateway`},help:{"v1-9vup6v-4y":`Конфігурація HTTP API Gateway, що об’єднує перемикачі кінцевих точок і засоби керування доступністю API на транспортному рівні. Залишайте ввімкненими лише потрібні кінцеві точки, щоб обмежити доступ для віддалених клієнтів.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Кінцеві точки HTTP Gateway`},help:{"v1-1a0r104-55":`Перемикачі HTTP-кінцевих точок в API Gateway для маршрутів сумісності та необов’язкових інтеграцій. Вмикайте кінцеві точки свідомо та відстежуйте характер доступу після впровадження.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`Кінцева точка OpenAI Chat Completions`},help:{"v1-1271mpb-2b":"Увімкнути сумісну з OpenAI кінцеву точку `POST /v1/chat/completions` (типово: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Обмеження зображень OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Налаштування завантаження та перевірки зображень для сумісних з OpenAI частин `image_url`."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`Список дозволених MIME-типів зображень OpenAI Chat Completions`},help:{"v1-1guijf3-1t":"Дозволені MIME-типи для частин `image_url` (список без урахування регістру)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`Дозволити URL-адреси зображень OpenAI Chat Completions`},help:{"v1-55cb3n-47":"Дозволити завантаження за URL-адресами на боці сервера для частин `image_url` (типово: false; URI даних і надалі підтримуються). Установіть значення `false`, щоб повністю вимкнути завантаження за URL-адресами."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`Максимальний розмір зображень OpenAI Chat Completions у байтах`},help:{"v1-d920yx-1s":"Максимальна кількість байтів для кожного завантаженого або декодованого зображення `image_url` (типово: 10 МБ)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`Максимальна кількість перенаправлень для зображень OpenAI Chat Completions`},help:{"v1-1enujsk-1z":"Максимальна кількість дозволених HTTP-перенаправлень під час завантаження за URL-адресами `image_url` (за замовчуванням: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`Час очікування зображень OpenAI Chat Completions (мс)`},help:{"v1-89w2b9-1x":"Час очікування в мілісекундах для завантаження за URL-адресами `image_url` (за замовчуванням: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`Список дозволених URL-адрес зображень OpenAI Chat Completions`},help:{"v1-n4hlt1-4r":"Необов’язковий список дозволених імен хостів для завантаження за URL-адресами `image_url`; підтримує точні імена хостів і шаблони `*.example.com`. Порожній або відсутній список означає відсутність обмежень за списком дозволених імен хостів."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Заголовки безпеки HTTP для Gateway`},help:{"v1-n8z1hb-44":`Необов’язкові заголовки безпеки HTTP-відповідей, які застосовує сам процес Gateway. Якщо TLS завершується на зворотному проксі, краще налаштувати їх там.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Заголовок суворої безпеки транспорту`},help:{"v1-1buwhc3-3v":`Значення заголовка відповіді Strict-Transport-Security. Установлюйте лише для HTTPS-джерел, які ви повністю контролюєте; використовуйте false, щоб явно вимкнути.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Режим Gateway`},help:{"v1-nfjirv-5m":`Режим роботи Gateway: "local" запускає канали та середовище виконання агента на цьому хості, а "remote" підключається через віддалений транспорт. Залиште "local", якщо ви не плануєте використовувати розділену топологію з віддаленим Gateway.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Skills вузлів Gateway увімкнено`},help:{"v1-1xwu6at-3g":`Приймати навички, опубліковані сполученими вузлами, поки вони підключені (типово: true). Установіть false, щоб ігнорувати навички, опубліковані вузлами.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Режим браузера вузла Gateway`},help:{"v1-oeu1nc-69":`Маршрутизація браузера через вузли ("auto" = віддавати перевагу браузеру хоста, використовувати єдиний підключений вузол браузера, коли локальна можливість недоступна; "manual" = вимагати явного вибору вузла або налаштованого закріплення; "off" = вимкнути маршрутизацію через вузли).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Прив’язка браузера до вузла Gateway`},help:{"v1-1cykty2-1p":`Прив’язати маршрутизацію браузера до конкретного вузла за ідентифікатором або назвою (необов’язково).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Список дозволів вузлів Gateway (додаткові команди)`},help:{"v1-6l4otb-5m":"Додаткові команди node.invoke, які слід дозволити понад стандартні дозволи Gateway (масив рядків команд). Увімкнення тут небезпечних команд є перевизначенням, що впливає на безпеку, і позначається під час `openclaw security audit`."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Список заборон вузлів Gateway`},help:{"v1-u7c8wx-53":"Назви команд вузлів, які слід блокувати, навіть якщо вони є серед заявлених можливостей вузла або в стандартному списку дозволів (лише точний збіг назви команди, наприклад `system.run`; текст оболонки всередині цієї команди не перевіряється)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Сполучення вузлів Gateway`},help:{"v1-gldsi2-4s":`Налаштування політики сполучення вузлів. Автоматичне схвалення з перевіркою через SSH увімкнено за замовчуванням; автоматичне схвалення за CIDR залишається вимкненим, доки явно не налаштовано списки дозволених довірених CIDR/IP.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`CIDR для автоматичного схвалення сполучення вузлів Gateway`},help:{"v1-jeel9f-6u":`Список дозволених CIDR/IP, який вмикається за бажанням, для автоматичного схвалення першого сполучення пристроїв із роллю вузла без запитаних областей доступу. Вимкнено, якщо не задано. Сполучення для оператора, браузера чи вебзастосунку, а також будь-яке сполучення зі зміною ролі, області доступу, метаданих або відкритого ключа й надалі потребує схвалення вручну.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Автоматичне схвалення локального сполучення вузлів Gateway`},help:{"v1-glzm36-41":`Схвалювати довірені локальні сполучення та розширення доступу без запиту (за замовчуванням: true); установіть false, щоб замість зручності вимагати явного схвалення кожного пристрою.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Перевірка сполучення вузлів Gateway через SSH`},help:{"v1-1e4da92-ct":"Автоматичне схвалення з перевіркою через SSH для першого сполучення пристроїв із роллю вузла (за замовчуванням: увімкнено). Gateway встановлює зворотне SSH-з’єднання з хостом сполучення (BatchMode, сувора перевірка ключів хоста) і схвалює запит, лише якщо вивід віддаленої команди `openclaw node identity` збігається з ключем пристрою, що очікує на схвалення. Установіть false, щоб вимкнути перевірку через SSH (незалежно від autoApproveCidrs, який залишається активним); для сполучення лише вручну також скасуйте налаштування autoApproveCidrs. Передайте об’єкт, щоб перевизначити user/identity/timeoutMs/cidrs."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Інструменти плагінів вузлів Gateway`},help:{"v1-1c24iq3-28":`Визначає, чи можуть сполучені вузли публікувати описи інструментів плагінів, видимі агенту.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Інструменти плагінів вузлів Gateway увімкнено`},help:{"v1-14lgfu6-47":`Приймати видимі агенту дескриптори інструментів плагінів, опубліковані сполученими вузлами (типове значення: true). Установіть false, щоб ігнорувати та видалити всі інструменти плагінів, опубліковані вузлами.`}},"gateway%2EopenclawId":{label:{"v1-ezzq9b-p":`Віддалений доступ через OpenClaw ID`},help:{"v1-1ulzsn4-95":`Експериментальний віддалений доступ через OpenClaw ID (Labs). Якщо ввімкнено, шлюз керує дочірнім процесом тунелю, який приймає з’єднання iroh від допущених пристроїв і проксіює їх до цього шлюзу. Типово вимкнено; у вимкненому стані шлюз не запускає дочірніх процесів, не відкриває сокетів тунелю й не звертається до OpenClaw ID, служби Discovery або служби ретрансляції.`}},"gateway%2EopenclawId%2EclientId":{label:{"v1-1g7ikna-t":`Ідентифікатор клієнта вебзастосунку OpenClaw ID`},help:{"v1-4vjfwu-8r":`Публічний клієнт OAuth (код авторизації з PKCE), який вебзастосунок використовує для входу через OpenClaw ID у меню облікового запису. Його URI перенаправлення — <web app origin>/openclaw-id/callback. На цьому комп’ютері вхід використовує це перенаправлення; вебзастосунок, доступ до якого здійснюється через персональний вхід, наприклад Tailscale, використовує авторизацію пристрою від постачальника ідентифікації.`}},"gateway%2EopenclawId%2EdiscoveryUrl":{label:{"v1-hnez1c-p":`URL служби Discovery для OpenClaw ID`},help:{"v1-14rpvwb-5h":`Служба Discovery, яка дзеркалює дескриптор claw і знімок складу учасників та ретранслює повідомлення поштової скриньки. Вона не є довіреною: кожне повернене нею твердження перевіряється за закріпленим коренем довіри власника claw.`}},"gateway%2EopenclawId%2Eenabled":{label:{"v1-c5v95y-x":`Віддалений доступ через OpenClaw ID увімкнено`},help:{"v1-19yjuzt-66":`Вмикає експериментальний віддалений доступ через OpenClaw ID (типове значення: false). Зміни застосовуються без перезапуску шлюзу. Для віддаленого доступу також потрібен relayUrl; для прив’язування claw додатково потрібні issuerUrl, discoveryUrl і loaderDomain.`}},"gateway%2EopenclawId%2EissuerUrl":{label:{"v1-g27qab-m":`URL емітента OpenClaw ID`},help:{"v1-dmrsc-4e":`Емітент OpenClaw ID, який використовується для входу виключно з метою підтвердження особи під час прив’язування claw. Йому ніколи не довіряють визначення членства, схвалення пристроїв або вибір сервера, до якого підключається клієнт.`}},"gateway%2EopenclawId%2EloaderDomain":{label:{"v1-1m8dm2q-p":`Домен завантажувача OpenClaw ID`},help:{"v1-1xj9br0-4o":`DNS-домен завантажувача OpenClaw ID без схеми та шляху; прив’язаний claw доступний за адресою https://<name>-<account tag>.<loaderDomain>, а його прив’язка до сервера підписана для цього імені хоста.`}},"gateway%2EopenclawId%2EmemberDeviceInactivityDays":{label:{"v1-bv2n4v-17":`Неактивність пристрою учасника OpenClaw ID (дні)`},help:{"v1-1n802ug-3g":`Кількість днів, протягом яких браузер учасника може не підключатися до цього claw, перш ніж claw видалить його (типово: 30). Учасник залишається в списку.`}},"gateway%2EopenclawId%2EownerDeviceInactivityDays":{label:{"v1-1elnzyi-16":`Неактивність пристрою власника OpenClaw ID (дні)`},help:{"v1-cy2c02-3x":`Кількість днів, протягом яких пристрій власника може не підключатися до цього claw, перш ніж claw видалить його зі свого списку дозволених пристроїв (типово: 90). Пристрої, схвалені ним, залишаються.`}},"gateway%2EopenclawId%2ErelayUrl":{label:{"v1-1r8to4f-l":`URL ретранслятора OpenClaw ID`},help:{"v1-1f4exuo-3w":`Єдиний ретранслятор iroh у мапі ретрансляторів кінцевої точки тунелю (без публічних ретрансляторів n0, DNS чи pkarr). Браузери підключаються до claw лише через цей ретранслятор.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Порт Gateway`},help:{"v1-af1nrn-51":`TCP-порт, на якому шлюз приймає вхідні з’єднання для API, вебзастосунку та каналів. Використовуйте окремий порт і уникайте конфліктів зі зворотними проксі або локальними сервісами розробки.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Портали Gateway`},help:{"v1-1v2lkw9-1c":`Налаштування публікації порталів і приватного вхідного доступу.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Приватний вхідний доступ до порталів`},help:{"v1-20w4gq-69":`Необов’язковий приватний зворотний HTTPS-проксі з підтримкою підстановних доменів, яким керує оператор. Перенаправляйте вихідний заголовок Host, шляхи та запити на перемикання протоколу на WebSocket до виділеного слухача loopback. Автентифікація порталу за bearer-токеном залишається обов’язковою. Потрібен перезапуск Gateway.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Підстановний домен порталів`},help:{"v1-1ffvdzt-50":`DNS-домен без протоколу та шляху для випадкових піддоменів порталів (наприклад, previews.example.net). Налаштуйте DNS із підстановкою та HTTPS у приватному середовищі; не використовуйте спільний простір імен хостів зі шлюзом або вебзастосунком.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Порт loopback для вхідного доступу до порталів`},help:{"v1-1mb98cv-4g":`Окремий HTTP-порт на інтерфейсі loopback, що приймає трафік від приватного HTTPS-проксі з підтримкою підстановочних доменів. Має відрізнятися від порту Gateway. Це порт бекенду, а не публічний HTTPS-порт.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Публічна базова адреса Gateway`},help:{"v1-1c6onp0-ae":`Доступне ззовні HTTPS-джерело шлюзу. Також використовується як стандартне джерело для браузера, якщо gateway.controlUi.allowedOrigins не задано. HTTP дозволено лише для localhost, 127.0.0.1 або [::1]. MCP OAuth для окремих запитувачів використовує його для формування URL зворотного виклику за шляхом /oauth/mcp/callback; посилання на сеанси каналів і створені плагінами посилання для перегляду використовують його для доступу до вебзастосунку та маршрутів шлюзу.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Доставка push-сповіщень Gateway`},help:{"v1-h23oz7-5s":`Налаштування доставки push-сповіщень, які Gateway використовує, коли потрібно активувати сполучені пристрої або сповістити їх. Налаштуйте тут APNs через ретранслятор для офіційних збірок iOS; пряма автентифікація APNs для локальних і ручних збірок, як і раніше, налаштовується через змінні середовища.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Доставка через APNs у Gateway`},help:{"v1-4bbafr-4e":`Налаштування доставки через APNs для пристроїв iOS, сполучених із цим Gateway. Використовуйте налаштування ретранслятора для офіційних збірок з App Store, які реєструються через зовнішній ретранслятор push-сповіщень.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Ретранслятор APNs для Gateway`},help:{"v1-7glbel-6x":`Налаштування зовнішнього ретранслятора для надсилання через APNs. За замовчуванням Gateway використовує розміщений ретранслятор OpenClaw або цей власний ретранслятор для push.test, сигналів пробудження та пробудження для повторного підключення після того, як сполучена офіційна збірка iOS опублікує реєстрацію з підтримкою ретранслятора.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`Базова URL-адреса ретранслятора APNs для Gateway`},help:{"v1-1o8mgnq-69":`Необов’язкова власна базова HTTPS-адреса зовнішньої служби ретрансляції APNs, яку використовують офіційні збірки iOS з App Store. Вона має відповідати URL-адресі ретранслятора, вбудованій у збірку iOS, щоб трафік реєстрації та надсилання надходив до того самого розгортання.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Час очікування ретранслятора APNs для Gateway (мс)`},help:{"v1-a0jkb1-4z":`Час очікування в мілісекундах для запитів надсилання від Gateway до ретранслятора APNs (за замовчуванням: 10000). Збільште для повільніших ретрансляторів або мереж чи зменште, щоб швидше завершувати невдалі спроби пробудження.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Перезавантаження конфігурації`},help:{"v1-d02mvq-4w":`Політика перезавантаження конфігурації під час роботи, яка визначає, як застосовуються зміни та коли запускаються повні перезапуски. Для найбезпечнішого оновлення під час роботи залиште гібридну поведінку, якщо не налагоджуєте внутрішні механізми перезавантаження.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Режим перезавантаження конфігурації`},help:{"v1-1q1etcf-3m":`Визначає, як застосовуються зміни конфігурації: "off" ігнорує зміни під час роботи, а "hybrid" застосовує зміни, безпечні без перезапуску, і за потреби виконує перезапуск.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Віддалений Gateway`},help:{"v1-6xv7gd-5a":`Налаштування підключення до віддаленого Gateway напряму або через SSH, коли цей екземпляр проксіює запити до іншого хоста середовища виконання. Використовуйте віддалений режим лише тоді, коли роботу на окремих хостах налаштовано навмисно.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`Заголовки автентифікації на периметрі віддаленого Gateway`},help:{"v1-jg9p7d-5o":`HTTP-заголовки зі значеннями із секретів, що передаються проксі-серверу з перевіркою ідентичності перед налаштованим віддаленим Gateway. Заголовки надсилаються лише до точного джерела gateway.remote.url через WSS і ніколи не передаються в разі перенаправлення.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Пароль віддаленого Gateway`},help:{"v1-16jc0yx-7y":`Спільний секрет, що надсилається в полі пароля для автентифікації цього клієнта на віддаленому Gateway. Параметр gateway.auth.mode сервера визначає налаштований секрет; приймається поле токена або пароля клієнта. Керуйте цим секретом зовнішніми засобами й уникайте значень у відкритому вигляді в конфігурації, що потрапляє до комітів.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Політика перевірки ключа хоста SSH віддаленого Gateway`},help:{"v1-7qoxtb-49":`Політика перевірки ключа хоста SSH у macOS. "strict" вимагає вже довіреного ключа хоста; "openssh" явно делегує перевірку чинній конфігурації OpenSSH.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`Ключ ідентифікації SSH віддаленого Gateway`},help:{"v1-hz2hsm-1f":`Необов’язковий шлях до файлу ключа ідентифікації SSH (передається до ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`Адреса підключення SSH до віддаленого Gateway`},help:{"v1-85w39w-2t":`Віддалений Gateway через SSH (створює тунель від порту Gateway до localhost). Формат: user@host або user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`Відбиток TLS віддаленого Gateway`},help:{"v1-1ri16lk-23":`Очікуваний відбиток TLS sha256 для віддаленого Gateway (закріпіть, щоб запобігти атакам MITM).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Токен віддаленого Gateway`},help:{"v1-1pb9q8w-7v":`Спільний секрет, що надсилається в полі token для автентифікації цього клієнта на віддаленому Gateway. Параметр gateway.auth.mode на сервері визначає налаштований секрет; приймається поле клієнта token або password. Зберігайте через підстановку секрету або змінної середовища та оновлюйте разом зі змінами автентифікації віддаленого Gateway.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Транспорт віддаленого Gateway`},help:{"v1-1acfs7m-54":`Транспорт віддаленого з’єднання: "direct" використовує підключення за налаштованою URL-адресою, а "ssh" створює тунель через SSH. Використовуйте SSH, коли потрібен зашифрований тунель без відкриття віддалених портів.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`URL-адреса віддаленого Gateway`},help:{"v1-va7exe-1b":`URL-адреса WebSocket віддаленого Gateway (ws:// або wss://).`}},"gateway%2ErepositoryIntegration":{label:{"v1-9msrgf-m":`Інтеграція з репозиторієм`},help:{"v1-10mbwuf-7d":`Ідентифікатор плагіна, потрібного для надання робочому процесу доступу до вихідного коду репозиторію, зокрема через вбудований механізм, GitHub App і керовані облікові дані OAuth або PAT. Якщо плагін-власник відсутній, вимкнений або не завантажений, доступ заборонено. Не вказуйте, щоб використовувати вбудований механізм роботи з репозиторієм; саме лише ввімкнення плагіна не означає його вибір.`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Ролі операторів Gateway`},help:{"v1-1h5f6fh-84":`Визначення іменованих ролей операторів для командних Gateway. Налаштування gateway.roles.default вмикає застосування прив’язаних до профілю правил доступу до сеансів, ізоляції пісочниці, доступу до агентів і повноважень оператора. Без типової ролі визначення слугують лише каталогом і зберігають поведінку Gateway без gateway.roles.`}},"gateway%2Eroles%2Eassignments":{label:{"v1-hv31t1-p":`Призначення ролей операторів`},help:{"v1-do2i61-55":`Необов’язкові декларативні призначення ролей для автентифікованих профілів. Дійсне явне призначення через users.setRole має пріоритет над цими зіставленнями, після яких застосовується роль за замовчуванням.`}},"gateway%2Eroles%2Eassignments%2EbyGithubLogin":{label:{"v1-wujwr5-u":`Ролі операторів за логіном GitHub`},help:{"v1-ecgzr1-95":`Потребує gateway.roles.default навіть для порожнього зіставлення. Зіставляє кешовані логіни GitHub із налаштованими назвами ролей, ігноруючи регістр після видалення пробілів на початку та в кінці. Некоректні логіни, дублікати нормалізованих логінів і невідомі ролі відхиляються. Профілі без кешованих даних облікового запису GitHub використовують явно призначену або типову роль.`}},"gateway%2Eroles%2Eassignments%2EbyGithubLogin%2E*":{label:{"v1-1wr68uf-q":`Роль оператора для логіна GitHub`},help:{"v1-dad5ey-5e":`Назва налаштованої ролі для цього логіна GitHub. Застосовується, коли профіль має відповідні кешовані ідентифікаційні дані GitHub і не має дійсного явного призначення ролі. Зміни застосовуються без перезапуску, якщо ввімкнено перезавантаження конфігурації.`}},"gateway%2Eroles%2Edefault":{label:{"v1-12e6yd7-17":`Типова роль оператора (вмикає застосування правил)`},help:{"v1-18k9r00-7c":`Необов’язкова типова роль, яка вмикає застосування правил іменованих ролей і призначається автентифікованим профілям без дійсної ролі, призначеної явно або за логіном GitHub. Її назва має відповідати налаштованому визначенню. Якщо її не вказано, застосування правил іменованих ролей залишається вимкненим, навіть за наявності визначень.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Визначення ролей операторів`},help:{"v1-11qtcgr-6w":`Непорожній каталог ролей із назвами, заданими адміністратором, що об’єднує політики спільного доступу до сеансів, ізоляції пісочниці, доступу до агентів і повноважень оператора. Самі визначення не вмикають застосування правил; задайте gateway.roles.default, щоб застосувати іменовані ролі до автентифікованих профілів.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Визначення ролі оператора`},help:{"v1-p8tfws-6q":`Одна іменована роль оператора. Кожне визначення має явно задавати політику спільного доступу до сеансів, дозволених агентів для сеансів і запусків, а також верхню межу повноважень оператора. Воно також може вимагати ізоляції новостворених сеансів у пісочниці та політики доступу від плагіна.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Плагін політики доступу для ролі оператора`},help:{"v1-1gq4q08-9n":`Необов’язковий точний ID плагіна, чия політика доступу Gateway має надавати дозвіл цій ролі. Доступ заборонено, якщо плагін відсутній, вимкнений, не завантажується або не надає чинних повноважень. ID недоступних плагінів залишаються допустимими в конфігурації, щоб співробітники з незалежними ролями та власник Gateway могли відновити доступ. Якщо це поле не задано, залежність від плагіна не додається.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Дозволені агенти для ролі оператора`},help:{"v1-fvun18-4v":`Агенти, доступні для створення сеансів або виконання запусків із цією роллю: задайте "*", щоб дозволити всіх агентів, укажіть список ідентифікаторів агентів, щоб дозволити лише їх, або використайте порожній список, щоб вимкнути обидві можливості.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy":{label:{"v1-1b2q6cc-q":`Політика моделей для ролі оператора`},help:{"v1-r9daa-e8":`Необов’язкове обмеження набору моделей для запитів цієї ролі та їхніх нащадків. Порожній об’єкт дозволяє лише основну та резервні моделі, налаштовані для вихідного агента; відсутність політики залишає доступ до моделей без змін. Псевдоніми моделей розпізнаються до застосування обмежень, а заборонені моделі не можна використовувати під час повторних спроб або як резервні. Якщо перезавантаження конфігурації ввімкнено, зміни, що стосуються лише політик моделей наявних ролей, застосовуються після збереження без перезапуску дозволених завдань. Інші зміни ролей застосовуються без перезапуску та повторно підключають клієнтів із поточними повноваженнями.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2Eallow":{label:{"v1-zdw95f-s":`Дозволені моделі для ролі оператора`},help:{"v1-1dutf3o-8u":`Необов’язковий список дозволених моделей, що замінює початковий і містить посилання на моделі, налаштовані псевдоніми або префіксні шаблони із символом підстановки наприкінці, як-от "provider/*" чи "provider/family-*". Якщо його не вказано, використовуються основна та резервні моделі агента-джерела; порожній список забороняє всі моделі. Перша дозволена модель агента-джерела залишається моделлю за замовчуванням, за нею йдуть явно дозволені моделі.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2Edeny":{label:{"v1-1hx2vzz-t":`Виключені моделі для ролі оператора`},help:{"v1-1kx70ze-7o":`Посилання на моделі, псевдоніми агента-джерела або префіксні шаблони із символом підстановки наприкінці, виключені для цієї ролі. Шаблон на кшталт "provider/family-*" також виключає майбутні моделі цієї родини. Виключення зіставляються з визначеними ідентифікаторами моделей і мають пріоритет над дозволеними моделями та моделями агента-джерела.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2EsourceAgent":{label:{"v1-8bg4yu-w":`Агент-джерело моделей для ролі оператора`},help:{"v1-yf7mu-62":`Агент, основна та резервні моделі й псевдоніми моделей якого визначають політику моделей цієї ролі. За замовчуванням використовується налаштований системний агент чи агент за замовчуванням або єдиний агент. Укажіть його явно, якщо Gateway із кількома агентами не має власника, визначеного контекстом.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Ізоляція в пісочниці для ролі оператора`},help:{"v1-11bb0ps-6a":`Ізоляція виконання для новостворених сеансів: "inherit" (за замовчуванням) використовує політику агента; "required" завжди вимагає пісочниці, навіть коли режим пісочниці агента вимкнено, і блокує виконання, якщо бекенд недоступний.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Граничні повноваження ролі оператора`},help:{"v1-1selr2i-4s":`Вичерпний список повноважень оператора, що визначає максимальні права підключення для цієї ролі. Із запитаних повноважень, а також повноважень, отриманих через сполучення, наданих на основі ідентичності та розширених, залишаються лише ті, що входять до цього списку.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Доступ до сеансів для ролі оператора`},help:{"v1-hsoiop-45":`Дозволи на спільний доступ, надані цій ролі для сеансів, створених іншими автентифікованими користувачами; власні сеанси користувача залишаються доступними йому як власнику.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Доступ ролі оператора до інших сеансів`},help:{"v1-1pmaa4o-al":`Доступ до сеансів інших користувачів: "none" приховує їх навіть за наявності явного членства в сеансі, "view" дозволяє читання, "suggest" дозволяє подавати пропозиції, а "write" дозволяє участь без членства. Явне членство в сеансі може підвищити рівень доступу "view" або "suggest" для конкретного сеансу. Автори сеансів і підключення з правом operator.admin зберігають доступ до своїх сеансів.`}},"gateway%2Eroles%2Edefinitions%2E*%2EworkerProfiles":{label:{"v1-o0hlzf-t":`Профілі виконавців для ролі оператора`},help:{"v1-v6xpap-5r":`Профілі хмарних виконавців, до яких ця роль може явно спрямовувати власні сеанси. Якщо значення не вказано або воно порожнє, спрямування до хмари заборонено; адміністратори зберігають доступ. Налаштування та перенесення до хмарних профілів залишаються доступними лише адміністраторам.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Tailscale для Gateway`},help:{"v1-6ar9o-4x":`Налаштування інтеграції з Tailscale для надання доступу через Serve/Funnel та керування життєвим циклом під час запуску й завершення роботи Gateway. Залишайте вимкненим, якщо ваше розгортання не передбачає використання Tailscale для вхідного доступу.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Режим Tailscale для Gateway`},help:{"v1-6l2099-5a":`Режим публікації Tailscale: "off", "serve" або "funnel" для приватного чи публічного доступу. Використовуйте "serve" для доступу лише в межах tailnet, а "funnel" — лише коли потрібен доступ із загальнодоступного інтернету.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Запобіжник міграції зовнішнього Funnel у Tailscale для Gateway`},help:{"v1-1mntkor-7q":`Застарілий запобіжник міграції для mode='serve'. Якщо зовнішній Funnel досі спрямовує трафік на звичайний слухач Gateway, OpenClaw залишає доступ без змін і попереджає, що працюватимуть лише вебхуки з автентифікацією через плагін, доки не буде налаштовано автентифікацію за паролем і режим не буде змінено на 'funnel'.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Термінал оператора`},help:{"v1-1qtq5dc-88":`Термінал оператора, доступний у вебзастосунку та мобільних клієнтах: командна оболонка на основі PTY на хості шлюзу, доступна лише в сеансах оператора з правами адміністратора. Вона запускається в робочому просторі цільового агента. Для повністю ізольованих агентів (sandbox.mode 'all') доступ заборонено, щоб не надавати оболонку хоста без обмежень ізоляції.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Час очікування від’єднаного сеансу термінала оператора`},help:{"v1-k6qbgr-9e":`Час у секундах, протягом якого сеанс термінала зберігається після розриву з’єднання (перехід ноутбука в режим сну, перезавантаження сторінки). До нього можна повторно під’єднатися через terminal.attach з відтворенням останнього виводу. Установіть 0, щоб завершувати сеанси одразу після розриву з’єднання. Типове значення: 300 (5 хвилин). Від’єднані сеанси продовжують виконувати свої команди, тому зменште цей час на спільних або доступних ззовні хостах.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Термінал оператора ввімкнено`},help:{"v1-1nez06v-7p":`Вмикає термінал оператора для клієнтів із правами адміністратора (за замовчуванням: true). Це надає доступ до командної оболонки в браузері або на мобільному пристрої із середовищем процесу Gateway; установіть false, щоб вимкнути її в розгортаннях, де оператори-адміністратори не повинні мати доступ до командної оболонки хоста. Зміни застосовуються без перезапуску Gateway.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Командна оболонка термінала оператора`},help:{"v1-19mfe6t-5i":`Виконуваний файл командної оболонки, який запускає термінал оператора. Залиште параметр незаданим, щоб використовувати оболонку входу хоста ($SHELL в Unix, %ComSpec% у Windows), або явно вкажіть інтерпретатор для однакового середовища оператора.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`TLS для Gateway`},help:{"v1-1dx77dq-4z":`Налаштування TLS-сертифіката та ключа для термінації HTTPS безпосередньо в процесі Gateway. У виробничому середовищі використовуйте явно задані сертифікати й уникайте передавання незашифрованих даних у ненадійних мережах.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Автоматичне створення TLS-сертифіката для Gateway`},help:{"v1-1ld6uiu-4w":`Автоматично створює локальну пару TLS-сертифіката та ключа, якщо файли не задано явно. Використовуйте лише в локальних середовищах або середовищах розробки, а для виробничого трафіку замініть справжніми сертифікатами.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Шлях до пакета CA для TLS у Gateway`},help:{"v1-andqlu-52":`Необов’язковий шлях до пакета CA для перевірки клієнтів або виконання власних вимог до ланцюжка довіри на периметрі Gateway. Використовуйте, якщо розгортання передбачає приватну PKI або власні ланцюжки сертифікатів.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Шлях до сертифіката TLS для Gateway`},help:{"v1-1wznaof-4q":`Шлях у файловій системі до файлу сертифіката TLS, який використовує Gateway, коли TLS увімкнено. Використовуйте керовані шляхи до сертифікатів і узгоджуйте автоматичне поновлення з цим розташуванням.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`TLS у Gateway увімкнено`},help:{"v1-ykhwp0-4o":`Увімкнення термінації TLS на прослуховувачі Gateway, щоб клієнти підключалися безпосередньо через HTTPS/WSS. Залишайте увімкненим для прямого доступу з інтернету або на будь-якій межі з недовіреною мережею.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Шлях до ключа TLS для Gateway`},help:{"v1-15knri0-4i":`Шлях у файловій системі до файлу приватного ключа TLS, який використовує Gateway, коли TLS увімкнено. Обмежуйте права доступу до цього файлу ключа та змінюйте ключ відповідно до своєї політики безпеки.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Політика доступності інструментів у Gateway`},help:{"v1-1ffol26-5a":`Політика дозволу й заборони доступу до інструментів на рівні Gateway, яка може обмежувати доступність інструментів під час виконання незалежно від профілів агентів та інструментів. Використовуйте для загальних екстрених обмежень і посилення захисту робочого середовища.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Список дозволених інструментів Gateway`},help:{"v1-163khb1-4y":`Явний список дозволених інструментів на рівні Gateway для випадків, коли під час виконання має бути доступний лише обмежений набір інструментів. Використовуйте для середовищ із суворими обмеженнями, де набір інструментів потребує жорсткого контролю.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Список заборонених інструментів Gateway`},help:{"v1-1lhssnf-4o":`Явний список заборонених інструментів на рівні Gateway для блокування ризикованих інструментів, навіть якщо політики нижчого рівня їх дозволяють. Використовуйте правила заборони для екстреного реагування та посилення багаторівневого захисту.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`CIDR довірених проксі Gateway`},help:{"v1-n5zcvf-4f":`Список дозволених CIDR/IP проксі вищого рівня, яким дозволено передавати заголовки з ідентифікаційними даними клієнта. Обмежуйте цей список, щоб недовірені проміжні вузли не могли видавати себе за користувачів.`}},"gateway%2Euploads":{label:{"v1-pn01yp-m":`Завантаження файлів і зображень`},help:{"v1-ger7hh-3a":`Політика завантаження файлів і зображень клієнтами до шлюзу та вебзастосунку. Завантаження на пристрій і згенеровані агентами медіафайли залишаються доступними.`}},"gateway%2Euploads%2Eenabled":{label:{"v1-1m4q5zw-f":`Завантаження ввімкнено`},help:{"v1-1tqoi1v-93":`Дозволяє завантаження файлів і зображень із клієнта (типово: true). Установіть false, щоб Gateway відхиляв вкладення, завантаження в робочий простір або термінал, завантаження аватарів та імпорт архівів, зокрема через прямі запити до API. Зміни застосовуються без перезапуску. Це не пісочниця й не обмеження для медіафайлів у каналах, інструментів агента чи доступу оператора до командної оболонки.`}},hooks:{label:{"v1-j9ywl7-5":`Хуки`},help:{"v1-1mzh0ry-5v":`Інтерфейс автоматизації вхідних вебхуків для зіставлення зовнішніх подій із пробудженням або діями агента в OpenClaw. Перш ніж відкривати до нього доступ поза довіреними мережами, захистіть його явними обмеженнями для токенів, сеансів і агентів.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`Дозволені ID агентів для хуків`},help:{"v1-1imjux7-79":`Список дозволених фактичних ідентифікаторів агентів, на які можуть спрямовуватися запити хуків і зіставлення, включно з маршрутизацією до агента за замовчуванням, якщо agentId не вказано. Використовуйте цей список, щоб спрямовувати події автоматизації лише до спеціалізованих службових агентів і обмежити шкоду в разі витоку токена хука.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Дозволені префікси ключів сеансів для хуків`},help:{"v1-b346oh-4r":`Список дозволених префіксів ключів сеансів для вхідних запитів хуків, коли дозволено ключі, надані стороною, що викликає. Використовуйте вузько визначені префікси, щоб запобігти вставленню довільних ключів сеансів.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Дозволити ключ сеансу в запитах хуків`},help:{"v1-11n9ps-52":`За значення true дозволяє стороні, що викликає, надавати ключ сеансу в запитах хуків і таким чином керувати маршрутизацією. Залишайте false, якщо довіреним інтеграторам явно не потрібне власне групування запитів у сеанси.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Типовий ключ сеансу для хуків`},help:{"v1-bzdgkn-57":`Резервний ключ сеансу для доставки через хуки, якщо запит не надає його через дозволені канали. Використовуйте стабільний ключ з обмеженою областю дії, щоб не змішувати розмови непов’язаних процесів автоматизації.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Хуки ввімкнено`},help:{"v1-1mixmjf-4n":`Вмикає кінцеву точку хуків і конвеєр виконання зіставлень для вхідних запитів вебхуків. Залишайте вимкненим, якщо не спрямовуєте зовнішні події до Gateway.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Хук Gmail`},help:{"v1-4cibmt-4r":`Налаштування push-інтеграції Gmail для сповіщень Pub/Sub і необов’язкового локального обслуговування зворотних викликів. За можливості обмежте використання цієї інтеграції окремими обліковими записами Gmail для автоматизації.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Обліковий запис хука Gmail`},help:{"v1-12l1h96-4v":`Ідентифікатор облікового запису Google для операцій відстеження та підписки Gmail у цій інтеграції хуків. Використовуйте окремий поштовий обліковий запис для автоматизації, щоб ізолювати дозволи на виконання операцій.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Дозволити небезпечний зовнішній вміст у хуку Gmail`},help:{"v1-1w3gdvs-55":`Якщо ввімкнено, дозволяє передавати на обробку зовнішній вміст Gmail із менш ретельним очищенням. Для безпечнішої роботи залишайте вимкненим і вмикайте лише для довірених потоків пошти з контрольованими перетвореннями.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`URL зворотного виклику хука Gmail`},help:{"v1-19fhn6q-4z":`Загальнодоступна URL-адреса зворотного виклику, до якої звертаються Gmail або посередники для доставки сповіщень у цей конвеєр хуків. Захистіть цю URL-адресу перевіркою токена та обмежте доступ до неї з мережі.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Включати тіло повідомлення в хуку Gmail`},help:{"v1-14cf1c3-52":`Якщо встановлено true, отримувати й додавати вміст листа для подальшого зіставлення даних або обробки агентом. Залишайте false, якщо текст листа не потрібен, оскільки це збільшує обсяг і чутливість переданих даних.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Мітка хука Gmail`},help:{"v1-9zpdg8-4g":`Необов’язковий фільтр за мітками Gmail, що визначає, які позначені повідомлення активують події хука. Використовуйте вузькі фільтри, щоб не перевантажувати автоматизації нерелевантними вхідними листами.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Максимальний розмір вмісту листа для хука Gmail у байтах`},help:{"v1-2aaxx1-4b":`Максимальний обсяг даних Gmail у байтах, що обробляється за одну подію, коли ввімкнено includeBody. Установлюйте помірні обмеження, щоб зменшити витрати й ризики обробки надмірно великих повідомлень.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Перевизначення моделі для хука Gmail`},help:{"v1-1var65t-59":`Необов’язкове перевизначення моделі для запусків, ініційованих Gmail, коли автоматизаціям поштової скриньки потрібна спеціалізована поведінка моделі. Залишайте незаданим, щоб успадковувати типові налаштування агента, якщо поштові завдання не потребують спеціалізації.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Токен push-сповіщень хука Gmail`},help:{"v1-h1vx01-4o":`Спільний секретний токен, обов’язковий для зворотних викликів хука push-сповіщень Gmail перед обробкою сповіщень. Використовуйте підстановку зі змінних середовища та регулярно змінюйте токен, якщо кінцеві точки зворотних викликів доступні ззовні.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Інтервал поновлення хука Gmail (хв)`},help:{"v1-pr1z9-49":`Періодичність поновлення підписок на відстеження Gmail у хвилинах, щоб запобігти завершенню їхньої дії. Установіть інтервал, коротший за термін дії підписок у постачальника, і відстежуйте помилки поновлення в журналах.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Локальний сервер хука Gmail`},help:{"v1-hom4wq-54":`Блок налаштувань локального сервера зворотних викликів для прямого отримання сповіщень Gmail без окремого вхідного шару. Увімкніть лише тоді, коли цей процес має самостійно приймати й обробляти трафік вебхуків.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Адреса прив’язки сервера хуків Gmail`},help:{"v1-55bieu-4d":`Адреса прив’язки локального HTTP-сервера зворотних викликів Gmail, який використовується для безпосереднього обслуговування хуків. Використовуйте лише адресу зворотного зв’язку, якщо зовнішній вхідний доступ не потрібен навмисно.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Шлях сервера хуків Gmail`},help:{"v1-1jqhcw4-4h":`HTTP-шлях на локальному сервері зворотних викликів Gmail, за яким приймаються push-сповіщення. Узгодьте його з конфігурацією підписки, щоб уникнути втрати подій.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Порт сервера хуків Gmail`},help:{"v1-1yku7dz-43":`Порт локального HTTP-сервера зворотних викликів Gmail, коли ввімкнено режим обслуговування. Використовуйте окремий порт, щоб уникнути конфліктів з інтерфейсами шлюзу та керування.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Підписка на хуки Gmail`},help:{"v1-127h8vg-5b":`Підписка Pub/Sub, яку використовує шлюз для отримання сповіщень про зміни Gmail із налаштованої теми. Чітко визначте, хто використовує підписку, щоб уникнути неочікуваної конкуренції між кількома споживачами.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale для хуків Gmail`},help:{"v1-7jzidp-4l":`Блок конфігурації доступу через Tailscale для публікації зворотних викликів Gmail через маршрути Serve/Funnel. Перш ніж вмикати будь-який публічний вхідний доступ, використовуйте приватні режими мережі tailnet.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Режим Tailscale для хуків Gmail`},help:{"v1-vhm395-4u":`Режим доступу через Tailscale для зворотних викликів Gmail: "off", "serve" або "funnel". Використовуйте "serve" для приватної доставки в мережі tailnet, а "funnel" — лише коли потрібен вхідний доступ із публічного інтернету.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Шлях Tailscale для хука Gmail`},help:{"v1-fr8qi-4m":`Шлях, опублікований через Tailscale Serve/Funnel для пересилання зворотних викликів Gmail, коли цю функцію ввімкнено. Узгодьте його з конфігурацією вебхука Gmail, щоб запити надходили до потрібного обробника.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Ціль Tailscale для хука Gmail`},help:{"v1-1twwxge-47":`Адреса локального сервісу, на яку Tailscale Serve/Funnel пересилає запити (наприклад, http://127.0.0.1:8787). Явно вказуйте адреси зворотної петлі, щоб уникнути неоднозначної маршрутизації.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Перевизначення рівня міркування для хука Gmail`},help:{"v1-17owk9q-4z":`Перевизначення рівня зусиль на міркування для запусків агента, ініційованих Gmail: "off", "minimal", "low", "medium" або "high". Для повсякденної автоматизації вхідної пошти задавайте помірні значення за замовчуванням, щоб контролювати витрати та затримку.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Тема Pub/Sub для хука Gmail`},help:{"v1-fdm0kn-4t":`Назва теми Google Pub/Sub, яку механізм спостереження Gmail використовує для публікації сповіщень про зміни в цьому обліковому записі. Перш ніж увімкнути спостереження, перевірте, чи надають дозволи IAM теми доступ Gmail до публікації.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Внутрішні хуки`},help:{"v1-piq9k-4v":`Налаштування середовища виконання внутрішніх хуків для вбудованих і власних обробників подій, що завантажуються за шляхами модулів. Використовуйте їх для довірених автоматизацій усередині процесу та суворо обмежуйте набір обробників, які можна завантажувати.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Внутрішні хуки ввімкнено`},help:{"v1-1wv0289-4c":`Увімкнення обробки внутрішніх хуків і налаштованих записів у середовищі виконання внутрішніх хуків. Залишайте вимкненим, якщо внутрішні хуки не налаштовано навмисно.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Записи внутрішніх хуків`},help:{"v1-1ovi38l-4o":`Налаштовані записи внутрішніх хуків, що використовуються для реєстрації конкретних обробників середовища виконання та метаданих. Задавайте записи явно й контролюйте їхні версії, щоб поведінку у виробничому середовищі можна було перевірити.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Завантажувач внутрішніх хуків`},help:{"v1-11re5ph-4p":`Налаштування завантажувача внутрішніх хуків, що визначають, де шукати модулі обробників під час запуску. Обмежуйте кореневі каталоги завантаження, щоб зменшити ризик випадкових конфліктів або затінення модулів.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Додаткові каталоги внутрішніх хуків`},help:{"v1-1xfdqxg-4c":`Додаткові каталоги для пошуку модулів внутрішніх хуків поза стандартними шляхами завантаження. Зберігайте цей список мінімальним і контрольованим, щоб зменшити ризик випадкового затінення модулів.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Правила зіставлення хуків`},help:{"v1-frhp3v-5i":`Упорядковані правила зіставлення, що перевіряють вхідні запити хуків і вибирають дію пробудження або обробки агентом із необов’язковою маршрутизацією доставки. Розміщуйте конкретні правила першими, щоб правила із загальними шаблонами не перехоплювали всі запити.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Дія правила зіставлення хуків`},help:{"v1-i2kbzp-4h":`Тип дії зіставлення: "wake" додає сповіщення до черги сеансу-власника, а "agent" запускає незалежний хід агента. Сповіщення сеансу не переривають поточну роботу.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`Ідентифікатор агента для правила зіставлення хуків`},help:{"v1-l0uioz-4y":`ID цільового агента для виконання правила зіставлення, коли маршрутизація дій не має використовувати типові налаштування. Використовуйте окремих агентів автоматизації, щоб ізолювати роботу вебхуків від інтерактивних сеансів оператора.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Дозволити небезпечний зовнішній вміст у правилі зіставлення хука`},help:{"v1-1np9426-57":`Якщо встановлено true, вміст правила зіставлення може включати менш ретельно очищені дані зовнішнього корисного навантаження до згенерованих повідомлень. Залишайте false за замовчуванням і вмикайте лише для довірених джерел із перевіреною логікою перетворення.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Канал доставки для правила зіставлення хука`},help:{"v1-oz7pu5-5s":`Перевизначення каналу доставки для результатів правила зіставлення (наприклад, "last", "telegram", "discord", "slack", "signal", "imessage" або "msteams"). Задавайте перевизначення каналів явно, щоб уникнути випадкового надсилання до інших каналів.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Доставка відповіді для правила зіставлення хука`},help:{"v1-12tbbam-5o":`Визначає, чи доставляються результати виконання правила зіставлення назад до адресата в каналі, чи обробляються без надсилання повідомлень. Вимикайте доставку для фонових автоматизацій, які не мають публікувати результати для користувачів.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Ключ розгалуження для правила зіставлення хука`},help:{"v1-1d593op-7e":`Ключ масиву верхнього рівня в корисному навантаженні, за елементами якого розгалужується правило зіставлення: кожен елемент запускає власну дію, а шаблони чи перетворення отримують корисне навантаження, масив якого містить лише поточний елемент. Готове налаштування Gmail використовує forEach: messages, тому пакетні push-сповіщення запускають окреме виконання для кожного листа.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`ID правила зіставлення хука`},help:{"v1-q1t4zw-57":`Необов’язковий сталий ідентифікатор запису зіставлення хука, що використовується для аудиту, усунення несправностей і цільових оновлень. Використовуйте унікальні ідентифікатори, щоб журнали та порівняння конфігурацій могли однозначно посилатися на зіставлення.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Умови зіставлення хука`},help:{"v1-6u73k2-5a":`Об’єкт, що групує умови зіставлення, як-от шлях і джерело, перед застосуванням маршрутизації дій. Задавайте конкретні критерії зіставлення, щоб сторонній трафік вебхуків не запускав автоматизації.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Шлях для зіставлення хука`},help:{"v1-1d7dc5j-4k":`Умова відповідності шляху для зіставлення хука, яку зазвичай перевіряють за шляхом вхідного запиту. Використовуйте її, щоб розділяти поведінку автоматизації за групами шляхів кінцевих точок вебхуків.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Джерело для зіставлення хука`},help:{"v1-1nw7um7-4v":`Умова відповідності джерела для зіставлення хука, яку зазвичай задають довірені метадані від попереднього компонента або логіка адаптера. Використовуйте стабільні ідентифікатори джерел, щоб маршрутизація залишалася незмінною під час повторних спроб.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Шаблон повідомлення для зіставлення хука`},help:{"v1-m0lqv5-5t":`Шаблон для формування зі структурованих вхідних даних зіставлення остаточного вмісту повідомлення, що надсилається до цільового шляху дії. Забезпечте формування однакового повідомлення з однакових вхідних даних, щоб подальший розбір і поведінка залишалися стабільними.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Перевизначення моделі для зіставлення хука`},help:{"v1-10qyo4j-5e":`Необов’язкове перевизначення моделі для запусків, ініційованих зіставленням, коли автоматизація має використовувати модель, відмінну від типової моделі агента. Використовуйте це лише за потреби, щоб поведінка залишалася передбачуваною під час виконання зіставлень.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Назва зіставлення хука`},help:{"v1-zrd9tn-4v":`Зрозуміла назва зіставлення, що відображається в діагностиці та інтерфейсах налаштування для операторів. Використовуйте стислі й описові назви, щоб під час аналізу інцидентів призначення маршрутизації було очевидним.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Ключ сеансу зіставлення хука`},help:{"v1-lfnt1n-58":`Явне перевизначення ключа сеансу для повідомлень, доставлених через зіставлення, щоб керувати збереженням контексту гілки розмови. Використовуйте стабільні ключі з обмеженою областю дії, щоб повторні події пов’язувалися між собою, не потрапляючи до сторонніх розмов.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Режим сеансу зіставлення хука`},help:{"v1-1ggtdze-5k":`Керує збереженням контексту сеансу зіставлення: "isolated" створює новий сеанс запуску, а "persistent" повторно використовує визначений sessionKey. Залишайте "isolated", якщо інтеграція не потребує тривалого збереження контексту.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Текстовий шаблон зіставлення хука`},help:{"v1-1rg732b-4y":`Резервний шаблон лише з текстом, який використовується, коли розширене відображення корисного навантаження небажане або не підтримується. Використовуйте його, щоб надавати стислий підсумковий рядок у єдиному форматі для доставки в інтерфейси чату.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Перевизначення міркування для зіставлення хука`},help:{"v1-17hq8me-57":`Необов’язкове перевизначення інтенсивності міркування для запусків, ініційованих зіставленням, щоб збалансувати затримку та глибину міркування. Для хуків із великим обсягом викликів залишайте низький або мінімальний рівень, якщо немає явної потреби в глибшому міркуванні.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Час очікування зіставлення хука (с)`},help:{"v1-1r44ox2-4i":`Максимальний час виконання дії зіставлення до застосування обробки перевищення часу очікування. Використовуйте суворіші обмеження для джерел вебхуків із великим обсягом викликів, щоб запобігти накопиченню черг.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Місце призначення доставки для зіставлення хука`},help:{"v1-1p7928e-55":`Ідентифікатор місця призначення у вибраному каналі, якщо відповіді зіставлення потрібно спрямовувати до фіксованого одержувача. Перевірте формати місць призначення, специфічні для постачальника, перш ніж увімкнути зіставлення в робочому середовищі.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Перетворення зіставлення хука`},help:{"v1-118nw83-5j":`Блок конфігурації перетворення, що визначає попередню обробку за допомогою модуля та його експорту перед обробкою дії зіставлення. Використовуйте перетворення лише з перевіреного коду та забезпечуйте відтворювану поведінку для відтворюваної автоматизації.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Експорт перетворення хука`},help:{"v1-atn8v-4b":`Іменований експорт, який потрібно викликати з модуля перетворення; якщо не вказано, використовується експорт модуля за замовчуванням. Укажіть його, якщо один файл містить кілька обробників перетворення.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Модуль перетворення хука`},help:{"v1-56futq-4v":`Відносний шлях до модуля перетворення, що завантажується з hooks.transformsDir для зміни вхідних даних перед доставкою. Зберігайте модулі локально, перевіряйте їх і не допускайте шаблонів обходу каталогів у шляхах.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Режим пробудження для зіставлення хука`},help:{"v1-1vp6cpn-6m":`Режим планування пробудження: "now" негайно додає хід сеансу до черги, а "next-heartbeat" призначає сповіщення наступній відповідній запланованій автоматизації цього сеансу. Для відкладених пробуджень потрібна ввімкнена автоматизація, здатна отримати сповіщення.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Шлях кінцевої точки хуків`},help:{"v1-1l9ijzv-4u":"HTTP-шлях, який використовує кінцева точка хуків (наприклад, `/hooks`) на сервері керування шлюзом. Використовуйте шлях, який складно вгадати, і поєднуйте його з перевіркою токена для багаторівневого захисту."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Набори налаштувань хуків`},help:{"v1-dp8m0l-4v":`Іменовані набори налаштувань хуків, які застосовуються під час завантаження для задання стандартних зіставлень і типової поведінки. Явно вказуйте використання наборів, щоб оператори могли перевіряти, які автоматизації активні.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Токен автентифікації хуків`},help:{"v1-1ihf6mv-82":`Спільний токен Bearer, який перевіряється на вході хуків для автентифікації запитів перед виконанням зіставлень. Вважайте власників токена повністю довіреними ініціаторами запитів до вхідного інтерфейсу хуків, а не окремою роллю без прав власника. Використовуйте підстановку зі змінних середовища та регулярно змінюйте токен, якщо кінцеві точки вебхуків доступні з інтернету.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Каталог перетворень хуків`},help:{"v1-1ayj9p0-4t":`Базовий каталог для модулів перетворення хуків, на які посилаються шляхи transform.module у зіставленнях. Використовуйте контрольований каталог репозиторію, щоб динамічні імпорти залишалися доступними для перевірки та передбачуваними.`}},logging:{label:{"v1-rq08xq-7":`Журналювання`},help:{"v1-11an9pb-5e":`Налаштування журналювання: рівні важливості, місця виведення, форматування та приховування конфіденційних даних. У робочому середовищі встановлюйте достатньо суворі рівні та правила приховування, зберігаючи корисну діагностичну інформацію.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Журнал аудиту`},help:{"v1-1lauvy2-6w":`Обмежена історія аудиту лише з метаданими для перегляду оператором. Записи запусків та інструментів увімкнено за замовчуванням; метадані життєвого циклу повідомлень вмикаються окремо через ризики для конфіденційності. Фоновий записувач працює без гарантії збереження всіх даних і не є архівом без втрат для забезпечення нормативної відповідності.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Журнал аудиту ввімкнено`},help:{"v1-snknxb-4v":`Записує нові події аудиту запусків, інструментів і повідомлень, для яких увімкнено аудит. Типове значення: true. Зміни застосовуються негайно; прийняті операції запису завершуються, а збережені записи залишаються доступними для запитів до закінчення терміну їх зберігання.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Аудит ідентифікаційних даних виконання`},help:{"v1-1ucirwv-5b":`Зберігає обмежений обсяг даних про ідентичність виконавця для перевірки конкретного запуску. Типове значення: false. Потребує logging.audit.enabled і застосовується до нових допущених запусків; наявні контексти залишаються без змін.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Область аудиту повідомлень`},help:{"v1-1yg4lc3-76":`Керує записами життєвого циклу повідомлень без їхнього вмісту: "off" (типове значення), "direct" — лише для відомих особистих розмов або "all" — для особистих і групових розмов, каналів та розмов невідомого типу. Потребує logging.audit.enabled. Зміни застосовуються до наступних подій життєвого циклу.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Рівень журналювання в консолі`},help:{"v1-16badbd-5u":`Окремий пороговий рівень журналювання для консолі: "silent", "fatal", "error", "warn", "info", "debug" або "trace" для керування виведенням у термінал. Використовуйте його, щоб зменшити обсяг повідомлень у локальній консолі, за потреби зберігаючи докладніші журнали у файлі.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Стиль журналу консолі`},help:{"v1-d7u0iq-3q":`Стиль форматування виведення в консоль: "pretty" або "json". Використовуйте json для конвеєрів машинного оброблення, а pretty — для зручної роботи користувача в терміналі.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Шлях до файлу журналу`},help:{"v1-16gaitv-4w":`Необов’язковий шлях до файлу для збереження журналів на додачу до журналювання в консолі або замість нього. Використовуйте керований шлях із правом запису та узгодьте зберігання й ротацію журналів зі своєю політикою експлуатації.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Рівень журналювання`},help:{"v1-1r5yku0-5o":`Основний пороговий рівень журналювання під час виконання: "silent", "fatal", "error", "warn", "info", "debug" або "trace". У робочому середовищі залишайте "info" або "warn", а debug/trace використовуйте лише під час дослідження проблем.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Власні шаблони маскування`},help:{"v1-11x24rh-8c":`Власні рядки регулярних виразів замінюють стандартний список рядків для журналів і діагностики. Вбудований захист даних у тілах форм, структурованих даних автентифікації та окремих ключів AWS діє завжди. Аргументи інструментів, результати та історія чату не маскуються. Використовуйте цей параметр, щоб приховувати специфічні для розгортання токени та ідентифікатори в діагностичних даних.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Глобальні визначення серверів MCP, якими керує OpenClaw. Вбудований OpenClaw та інші адаптери середовища виконання можуть використовувати ці сервери без збереження їх у налаштуваннях проєкту, що належать середовищу виконання.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`Застосунки MCP`},help:{"v1-amyd91-38":`Підтримка інтерфейсу MCP Apps. Якщо ввімкнено, налаштовані сервери MCP можуть надавати інтерактивні HTML-подання результатів роботи своїх інструментів.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps увімкнено`},help:{"v1-ghqy98-3w":`Відображення MCP Apps і міст між застосунком та сервером, що вмикаються за бажанням. Залишайте вимкненими, якщо не довіряєте налаштованим серверам MCP, які надають ресурси інтерфейсу застосунків.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Джерело пісочниці MCP Apps`},help:{"v1-5lqj7v-6s":`Необов’язкове окреме публічне HTTP(S)-джерело для MCP Apps. Використовуйте його за зворотним проксі або термінатором TLS і спрямовуйте проксі-запити лише на налаштований порт ізольованого середовища MCP Apps. Воно має відрізнятися від джерела вебзастосунку й не повинно надавати вміст, що потребує автентифікації.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Порт пісочниці MCP Apps`},help:{"v1-1b8n71l-4p":`Виділений порт прослуховування пісочниці MCP Apps. За замовчуванням — порт Gateway плюс один. Укажіть вільний порт, якщо цей порт уже зайнятий іншою локальною службою або профілем Gateway.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`Сервери MCP`},help:{"v1-157ozoz-42":`Іменовані визначення серверів MCP. OpenClaw зберігає їх у власній конфігурації, а адаптери середовища виконання визначають, які транспорти підтримуються під час виконання.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`Автентифікація сервера MCP`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`Сертифікат клієнта MCP`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`Ключ клієнта MCP`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`Сертифікат клієнта MCP`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`Ключ клієнта MCP`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Проєкція MCP для Codex`},help:{"v1-slcmq1-6x":`Метадані проєкції OpenClaw лише для потоків Codex app-server. Вони не впливають на сеанси ACP або загальну конфігурацію середовища виконання Codex. Не додавайте цей блок, щоб сервер залишався доступним для всіх агентів Codex app-server зі стандартною поведінкою схвалення MCP у Codex.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Агенти MCP у Codex`},help:{"v1-1i6v0fm-6a":`Необов’язкові непорожні ідентифікатори агентів OpenClaw, яким слід надати цей сервер MCP у конфігурації потоку Codex app-server. Списки без дійсних ідентифікаторів агентів не надають доступу; якщо список не вказано, сервер додається до конфігурації всіх агентів Codex app-server.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Схвалення інструментів MCP у Codex`},help:{"v1-1xql0qr-3d":`Власна назва параметра Codex для того самого режиму схвалення інструментів MCP на рівні сервера. У конфігурації OpenClaw надавайте перевагу defaultToolsApprovalMode.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Схвалення інструментів MCP у Codex`},help:{"v1-y5vsqq-3s":`Необов’язковий режим схвалення інструментів MCP у Codex для цього сервера: "auto", "prompt" або "approve". Використовуйте лише для серверів MCP, яким ви свідомо довіряєте.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`Час очікування підключення MCP (мс)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`Сервер MCP увімкнено`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`OAuth для MCP`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`Профіль автентифікації OAuth для MCP`},help:{"v1-fcrb4u-5z":`Ідентифікатор профілю автентифікації з підтримкою оновлення, який використовується для передавання поточного токена Bearer цьому віддаленому серверу MCP. Якщо задано, OpenClaw визначає та оновлює профіль під час виконання й не передає дані для оновлення далі.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`URL метаданих клієнта OAuth для MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`Ідентичність OAuth для MCP`},help:{"v1-1ie6ys7-59":`Належність облікових даних OAuth для цього сервера. Пропустіть це поле або використайте "shared" для облікових даних, якими керує оператор; використайте "per-requester", щоб кожен автентифікований відправник міг підключити власний обліковий запис.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`URL перенаправлення OAuth для MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`Область доступу OAuth для MCP`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Час очікування запиту MCP (мс)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`Перевірка TLS для MCP`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`Перевірка TLS для MCP`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Паралельні виклики інструментів MCP`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Паралельні виклики інструментів MCP`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`Вибір інструментів MCP`},help:{"v1-10poyzb-4v":`Вибір інструментів MCP для кожного сервера. Використовуйте include, щоб зробити доступними лише інструменти MCP із вибраними назвами, або exclude, щоб приховати інструменти MCP із вибраними назвами. Записи підтримують точні назви та прості шаблони з '*'.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Виключені інструменти MCP`},help:{"v1-ijrc5y-1u":`Точні назви інструментів MCP або прості шаблони з '*', які визначають, які інструменти цього сервера слід приховати.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Включені інструменти MCP`},help:{"v1-89fdfq-3o":`Точні назви інструментів MCP або прості шаблони з '*', які визначають, які інструменти цього сервера слід надавати. Якщо не вказано, усі інструменти сервера залишаються доступними, окрім виключених.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL простою сеансу MCP (мс)`},help:{"v1-j9si74-87":`Необов’язковий час простою в мілісекундах, після якого видаляються середовища виконання MCP сеансу OpenClaw. Якщо не задано або встановлено 0, середовища виконання залишаються активними до очищення сеансу або завершення роботи Gateway. Додатні значення округлюються вниз; активні оренди та запити на отримання, що очікують виконання, запобігають видаленню. Середовища виконання, що належать окремому запуску, усе одно завершують роботу після закінчення цього одноразового запуску.`}},memory:{label:{"v1-oopaku-6":`Пам’ять`},help:{"v1-1wlx40m-13":`Налаштування вбудованої пам’яті (глобальні).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Режим посилань на джерела з пам’яті`},help:{"v1-1q6dxr5-4u":`Керує видимістю посилань на джерела у відповідях: "auto" показує їх, коли це корисно, "on" показує завжди, а "off" приховує. Залиште "auto" як типовий режим для збалансованого співвідношення корисної інформації та шуму.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Пошук у пам’яті`},help:{"v1-1ukbud1-25":`Векторний пошук у MEMORY.md та memory/*.md (підтримуються перевизначення для окремих агентів).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Кеш векторних представлень для пошуку в пам’яті`},help:{"v1-d8h2e4-5b":`Кешує обчислені векторні представлення фрагментів у SQLite, щоб пришвидшити повторне індексування та інкрементальні оновлення (типово: true). Залишайте ввімкненим, якщо не перевіряєте коректність кешу й не прагнете мінімізувати використання диска.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Тип вхідних даних документа для пошуку в пам’яті`},help:{"v1-1ui33sv-5f":"Необов’язкове значення `input_type`, специфічне для постачальника, для векторних подань документів та індексації пам’яті. Використовуйте його з OpenAI-сумісними кінцевими точками асиметричних векторних подань, які потребують позначки уривка або документа."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Увімкнути пошук у пам’яті`},help:{"v1-14f11b9-4t":`Головний перемикач індексації та пошуку в пам’яті для цього профілю агента. Залиште увімкненим для семантичного пригадування або вимкніть, якщо потрібні відповіді повністю без збереження стану.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Індекс сеансів для пошуку в пам’яті (експериментально)`},help:{"v1-1y8ykw2-3b":`Індексує історію чатів для пошуку в пам’яті. Залиште це розширене перевизначення, якщо успадкування налаштувань пригадування на кореневому рівні та на рівні окремих агентів відрізняється.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Додаткові шляхи пам’яті`},help:{"v1-ojqokq-7i":`Додає до індексу пам’яті додаткові каталоги або файли .md, окрім стандартних файлів пам’яті. Записи можуть бути рядками шляхів або об’єктами з glob-шаблоном відносно кореня. Коли мультимодальну пам’ять увімкнено, відповідні файли зображень і аудіо за цими шляхами також можуть індексуватися.`}},"memory%2Esearch%2EextraPaths%2E*%2Eevergreen":{label:{"v1-1pdtd1w-r":`Додатковий шлях пам’яті без часового знецінення`},help:{"v1-5y3z66-5f":`Виключає відповідні довідкові файли з додаткових шляхів із часового знецінення на основі часу зміни файлу (mtime) у файловій системі. Це змінює лише ранжування за давністю; вміст не стає довіреним, не отримує вищого пріоритету, а походження джерела не змінюється.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Додатковий шлях пам’яті`},help:{"v1-b9mbq8-3m":`Задає додатковий каталог або файл пам’яті. Відносні шляхи визначаються від робочого простору агента; якщо файл указано безпосередньо, індексується саме він.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Шаблон додаткового шляху пам’яті`},help:{"v1-j8br1v-4e":`Обмежує запис каталогу підтримуваними файлами, що відповідають цьому glob-шаблону відносно кореня, наприклад "runbooks/**/*.md". Не вказуйте його, щоб рекурсивно сканувати всі підтримувані файли.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Резервний провайдер пошуку в пам’яті`},help:{"v1-1r6368w-6p":`Резервний провайдер, що використовується, коли основний не може створити ембеддинги: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" або "none". Для надійної роботи у виробничому середовищі вкажіть реального резервного провайдера; використовуйте "none", лише якщо віддаєте перевагу явним помилкам.`}},"memory%2Esearch%2EinputFormat":{label:{"v1-1qisc0t-q":`Формат вхідних даних пошуку в пам’яті`},help:{"v1-xus8vr-b2":`Необов’язкова пара дослівних текстових префіксів для векторних подань запитів і документів, наприклад { query: "query: ", document: "passage: " }. Замінює автоматичне форматування моделі, зокрема для псевдонімів моделей. Обидва рядки обов’язкові; пробіли та переноси рядків зберігаються, а порожні рядки означають використання необробленого тексту. Непорожнє значення queryInstruction має пріоритет для запитів. Зміна префікса документа потребує повторної індексації.`}},"memory%2Esearch%2EinputFormat%2Edocument":{label:{"v1-ml4fv9-t":`Префікс документа для пошуку в пам’яті`},help:{"v1-m9hsjw-4q":`Дослівний префікс для векторних подань документів. Порожній рядок означає використання необробленого тексту документа. Зміна цього префікса змінює ідентичність індексу та кешу векторних подань і потребує повторної індексації.`}},"memory%2Esearch%2EinputFormat%2Equery":{label:{"v1-16lu8lu-q":`Префікс запиту для пошуку в пам’яті`},help:{"v1-hxaub1-3u":`Дослівний префікс для векторних подань запитів. Використовується, якщо не задано непорожнє значення queryInstruction; порожній рядок вимикає автоматичне форматування запитів.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Тип вхідних даних пошуку в пам’яті`},help:{"v1-26vbwe-5u":"Використовуйте це необов’язкове, специфічне для провайдера значення `input_type`, лише коли одна й та сама мітка має застосовуватися до запитів на створення ембеддингів як для пошукових запитів, так і для документів. Для асиметричних провайдерів надавайте перевагу queryInputType і documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Шлях до локальної моделі ембеддингів`},help:{"v1-13ymbnt-5q":"Визначає джерело локальної моделі ембеддингів для локального пошуку в пам’яті, наприклад шлях до файлу GGUF або URI `hf:`. Використовуйте лише тоді, коли provider має значення `local`, і перевіряйте сумісність моделі перед масштабними перебудовами індексу."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Модель пошуку в пам’яті`},help:{"v1-11pohrl-59":`Перевизначення моделі ембеддингів для вибраного провайдера пам’яті, коли потрібна модель, відмінна від типової. Задавайте це значення, лише якщо потрібно цілеспрямовано налаштувати якість пошуку або вартість поза межами типових налаштувань провайдера.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Мультимодальний пошук у пам’яті`},help:{"v1-1jn02s-9e":'Необов’язкові налаштування мультимодальної пам’яті для індексування зображень і аудіофайлів із налаштованих додаткових шляхів. Залишайте цю функцію вимкненою, якщо ваша модель ембеддингів явно не підтримує кросмодальні ембеддинги, а коли її ввімкнено, установіть для `memory.search.fallback` значення "none". Під час індексування відповідні файли надсилаються налаштованому віддаленому провайдеру ембеддингів.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Увімкнути мультимодальний пошук у пам’яті`},help:{"v1-1dk5d7o-7e":`Вмикає індексування зображень і аудіо з extraPaths у пам’яті. Наразі для цього потрібна модель Gemini embedding-2. У стандартних кореневих каталогах пам’яті й надалі індексуються лише файли Markdown, резервні провайдери пошуку в пам’яті вимикаються, а відповідний двійковий вміст завантажується до налаштованого віддаленого провайдера ембедингів.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Максимальний розмір мультимодального файлу для пошуку в пам’яті в байтах`},help:{"v1-1mmdrvk-5d":`Задає максимальний розмір мультимодального файлу в байтах, у разі перевищення якого файл пропускається під час індексування пам’яті. Використовуйте це обмеження, щоб зменшити витрати на завантаження та час індексування, або збільште його для коротких високоякісних аудіозаписів.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Модальності мультимодального пошуку в пам’яті`},help:{"v1-alp4vh-4l":`Визначає, які типи мультимодальних файлів індексуються з extraPaths: "image", "audio" або "all". Обмежуйте цей вибір, щоб уникнути ненавмисного індексування великих масивів двійкових даних.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Вихідна розмірність пошуку в пам’яті`},help:{"v1-jx51wj-dm":"Перевизначення розміру вихідного вектора для ембедингів пам’яті залежно від провайдера. Моделі Gemini підтримують від 128 до 3072 вимірів; рекомендовані значення — 768, 1536 або 3072. Сімейства моделей Bedrock, як-от Titan V2, Cohere V4 і Nova, мають власні допустимі розміри. Кінцеві точки, сумісні з OpenAI, отримують це значення як `dimensions` і мають повертати вектори саме такого розміру. Керовані локальні ембединги GGUF обрізаються та нормалізуються локально. Зміна цього значення потребуватиме повної переіндексації, оскільки розмірність збережених векторів має залишатися узгодженою."}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Провайдер пошуку в пам’яті`},help:{"v1-5evseb-71":`Вибирає бекенд ембедингів для створення векторів пам’яті та пошуку за ними. Типове значення — "openai"; установіть "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" або "local", якщо потрібен інший бекенд.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Максимальна кількість результатів пошуку в пам’яті`},help:{"v1-13ekath-4x":`Максимальна кількість збігів у пам’яті, які повертає пошук перед подальшим повторним ранжуванням і додаванням до промпту. Збільште для ширшого охоплення або зменште для компактніших промптів і швидших відповідей.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Мінімальна оцінка пошуку в пам’яті`},help:{"v1-1ww231l-4v":`Мінімальний поріг оцінки релевантності для включення результатів із пам’яті до підсумкової вибірки. Збільште, щоб зменшити кількість слабких або нерелевантних збігів, або зменште, якщо потрібні менш суворі критерії пошуку.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Тип вхідних даних запиту пошуку в пам’яті`},help:{"v1-831yrv-4q":"Необов’язкове, залежне від постачальника значення `input_type` для ембедингів пам’яті під час запиту. Використовуйте його з OpenAI-сумісними кінцевими точками асиметричних ембедингів, які вимагають мітки запиту."}},"memory%2Esearch%2EqueryInstruction":{label:{"v1-izdliq-v":`Інструкція для пошукових запитів у пам’яті`},help:{"v1-19u8npy-b1":`Необов’язковий дослівний префікс для векторних подань запитів, наприклад "search_query: ". Додайте потрібні пробіли або переноси рядків. Непорожні значення замінюють inputFormat.query та автоматичне форматування запитів; якщо значення не задано або воно порожнє, використовується inputFormat.query, якщо його задано, інакше — типові налаштування постачальника. Документи та ідентичність індексу не змінюються, тому повторна індексація не потрібна. Порожнє перевизначення для окремого агента очищує успадковану інструкцію.`}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Пам’ятати між розмовами`},help:{"v1-1r9xto0-7s":`Використовуйте доречний контекст з інших приватних розмов цього агента через захищене пригадування чатів. Типово ввімкнено, лише якщо глобальний параметр session.dmScope не задано або він має значення "main" і жодна прив’язка не перевизначає область приватних повідомлень; будь-яке налаштування ізоляції приватних повідомлень типово вимикає цю функцію. Явно задане значення true або false завжди має пріоритет.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`Ключ API віддаленого сервісу ембедингів`},help:{"v1-nfuuu-62":`Задає окремий ключ API для віддалених викликів створення ембедингів, що використовуються під час індексування пам’яті та обробки запитів. Використовуйте цей параметр, якщо для ембедингів пам’яті потрібні облікові дані, відмінні від глобальних типових значень або змінних середовища.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`Базова URL-адреса віддаленого сервісу ембедингів`},help:{"v1-1ugvqgt-5p":`Перевизначає кінцеву точку API ембедингів, наприклад проксі, сумісний з OpenAI, або власну базову URL-адресу Gemini. Використовуйте цей параметр лише для маршрутизації через власний шлюз або кінцеву точку постачальника; в інших випадках залишайте типові налаштування постачальника.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Віддалене пакетне створення ембедингів увімкнено`},help:{"v1-1fehqi-5x":`Вмикає пакетні API постачальника для завдань створення ембедингів, якщо вони підтримуються (OpenAI/Gemini), підвищуючи пропускну здатність під час індексування великих обсягів даних. Залишайте цей параметр увімкненим, окрім випадків налагодження збоїв пакетної обробки постачальника або роботи з дуже малими обсягами даних.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`Заголовки віддалених запитів ембедингів`},help:{"v1-1uic0kd-5i":`Додає власні HTTP-заголовки до віддалених запитів ембедингів, об’єднуючи їх із типовими заголовками постачальника. Використовуйте цей параметр для заголовків автентифікації проксі та маршрутизації орендарів і зводьте вміст значень до мінімуму, щоб уникнути витоку конфіденційних метаданих.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Джерела пошуку в пам’яті`},help:{"v1-1xxndig-4q":`Визначає, які джерела індексуються: "memory" читає MEMORY.md і файли пам’яті, а "sessions" включає історію чатів. Залиште ["memory"], якщо вам не потрібне пригадування попередніх чатів.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Векторний індекс пошуку в пам’яті`},help:{"v1-fbybkj-37":`Керує семантичним індексом sqlite-vec. Залиште це розширене перевизначення, якщо кореневі векторні політики відрізняються від політик окремих агентів.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Шлях до векторного розширення пошуку в пам’яті`},help:{"v1-1hysv5q-58":"Перевизначає автоматично виявлений шлях до бібліотеки розширення sqlite-vec (`.dylib`, `.so` або `.dll`). Використовуйте, якщо ваше середовище виконання не може знайти sqlite-vec автоматично або ви закріплюєте перевірену збірку."}},messages:{label:{"v1-1wwzqad-8":`Повідомлення`},help:{"v1-i5k0iw-5k":`Інфраструктура повідомлень і спільні для агентів типові налаштування. Сусідні розділи кореневого рівня відповідають за інфраструктуру та спільні для агентів типові налаштування; agents.defaults — за поведінку циклу агента; записи агентів можуть перевизначати і те, й інше, де це підтримується.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Емодзі реакції підтвердження`},help:{"v1-1iip0zs-1x":`Реакція емодзі для підтвердження отримання вхідних повідомлень (порожнє значення вимикає).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Область застосування реакцій підтвердження`},help:{"v1-1jvdg5n-7s":`Коли надсилати реакції підтвердження ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" підтверджує повідомлення в групах, що згадують агента, незалежно від того, чи потрібні згадки в групі; "group-all" підтверджує кожне повідомлення в групі. "off"/"none" повністю вимикає реакції підтвердження.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Правила групового чату`},help:{"v1-chqsvh-4l":`Налаштування обробки групових повідомлень, зокрема тригерів згадок і розміру вікна історії. Використовуйте вузькі шаблони згадок, щоб у групових каналах не було спрацьовувань на кожне повідомлення.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Ліміт історії групи`},help:{"v1-1mkbpw-9k":`Максимальна кількість попередніх групових повідомлень, що завантажуються як контекст на кожному кроці групового сеансу. Використовуйте більші значення для кращого збереження контексту або менші — для швидших і дешевших відповідей. Історія, що автоматично додається до промпту, обмежена 200 повідомленнями. Максимальне ціле значення JSON задає стандартне вікно історії каналу (50 для спільної групової історії), а не необмежене вікно.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Шаблони згадок у групах`},help:{"v1-i7h7qc-6f":`Безпечні шаблони регулярних виразів без урахування регістру для виявлення явних згадок і фраз-тригерів у групових чатах. Використовуйте точні шаблони, щоб зменшити кількість хибних спрацьовувань у каналах із великим потоком повідомлень; некоректні або небезпечні шаблони з вкладеними повтореннями ігноруються.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Вхідні повідомлення групи без згадок`},help:{"v1-17wef8h-5f":`Визначає, як передаються повідомлення групового чату без згадок у постійно активному режимі. "user_request" обробляє їх як запит користувача; "room_event" передає їх як фоновий контекст, для видимої відповіді на який потрібен інструмент message.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Видимі відповіді в групах`},help:{"v1-qa4z1s-aa":`Перевизначає вихідні відповіді, створені моделлю, для розмов у групах і каналах. Якщо глобальну політику видимих відповідей не задано, за замовчуванням використовується "automatic". Режим "message_tool" вимагає message(action=send) для звичайних відповідей асистента та стандартних медіаданих інструментів; вивід середовища виконання, явно позначений як такий, що належить хосту, залишається доступним для доставки, за винятком фонових подій кімнати. Режим "automatic" публікує звичайні відповіді, як і раніше.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Затримка об’єднання вхідних повідомлень`},help:{"v1-ebyu5x-4a":`Налаштування затримки об’єднання вхідних повідомлень, що застосовуються безпосередньо перед початком обробки черги або кроку. Налаштуйте їх для швидких серій повідомлень від одного відправника з урахуванням особливостей провайдера.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Затримка об’єднання вхідних повідомлень за каналами (мс)`},help:{"v1-wbz54j-4g":`Перевизначення затримки об’єднання вхідних повідомлень для окремих каналів у мілісекундах, де ключами є ідентифікатори провайдерів. Використовуйте, якщо деякі провайдери надсилають фрагменти повідомлень частіше за інших.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Затримка об’єднання вхідних повідомлень (мс)`},help:{"v1-1616yo2-7w":`Період очікування без нових повідомлень (мс) для об’єднання в пакет вхідних повідомлень, що швидко надходять від одного відправника. Для Telegram типове значення становить 300 мс, якщо не задано ні глобального перевизначення, ні перевизначення для каналу; для інших каналів — 0. Нуль вимикає звичайне пакетне об’єднання серій повідомлень, але Telegram усе одно об’єднує фрагменти довгих повідомлень, розмір яких наближається до граничного.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Черга вхідних повідомлень`},help:{"v1-hm2o31-48":`Стратегія черги для вхідних повідомлень, що надходять під час активного виконання сеансу. Використовуйте для налаштування коригування поточного виконання, відкладеної обробки наступних повідомлень, об’єднання або переривання.`}},"messages%2Equeue%2EallowCollaborativeSteering":{label:{"v1-95t3u6-s":`Дозволити спільне керування`},help:{"v1-1pyzwb-ip":`Дозволити допущеним вхідним повідомленням від людей у тій самій розмові спрямовувати активний хід зі збереженням його ідентичності та попередньо визначених дозволів, навіть якщо автор повідомлення має менше дозволів (типово: true). Вхідні повідомлення з WebUI зі спільними обліковими даними та з каналів також можуть продовжувати ту саму активну сесію. Якщо встановлено false, цей виняток потребує чинних повноважень адміністратора WebUI та власника каналу; можливість продовження з підтвердженням тієї самої особи також зберігається. В інших випадках collaborativeSteeringFallback визначає, чи слід без сповіщення поставити в чергу хід, що належить ініціатору запиту (queue), чи безумовно відмовити (reject). Поточні права доступу, чинні повноваження на виконання, перевірки параметрів виконання, режими черги та авторизація спрямування між сесіями залишаються чинними.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Режим черги за каналами`},help:{"v1-1vbyy4u-5q":`Перевизначення режиму черги для окремих каналів за ідентифікатором каналу, зокрема для каналів плагінів (наприклад, discord, telegram, x). Використовуйте, коли характер трафіку певного каналу потребує поведінки, відмінної від глобальних налаштувань за замовчуванням.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Місткість черги`},help:{"v1-16ql8c7-4j":`Максимальна кількість вхідних елементів, що зберігаються в черзі до застосування політики відкидання. Типове значення — 20; обмежуйте місткість для каналів із великим потоком повідомлень, щоб використання пам’яті залишалося передбачуваним.`}},"messages%2Equeue%2EcollaborativeSteeringFallback":{label:{"v1-3k0wft-v":`Резервна дія для спільного спрямування`},help:{"v1-peu9fu-8i":`Визначає, що відбувається, коли інша людина не може спрямовувати виконання через вимкнене спільне спрямування: "queue" (типово) обробляє її повідомлення як окремий хід без сповіщення про стан; "reject" зберігає сувору відмову та вимагає нового запиту /followup. Не вмикає спільне спрямування та не обходить перевірки доступу.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Резервна затримка об’єднання в черзі за каналами (мс)`},help:{"v1-1w7gk9b-54":`Перевизначення затримки обробки черги для окремих каналів за ідентифікатором каналу, зокрема для каналів плагінів. Використовуйте, щоб незалежно налаштовувати обробку сплесків повідомлень для чатів із різним темпом спілкування.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Стратегія відкидання з черги`},help:{"v1-ydb2rw-6m":`Стратегія відкидання повідомлень у разі перевищення ліміту черги. "summarize" відкидає найстаріші записи, але зберігає стислі підсумки; "old" відкидає найстаріші записи без підсумків; "new" відхиляє найновіший запис. Використовуйте "summarize" для тривалих чатів, у яких важливий контекст.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Режим черги`},help:{"v1-19k7gy1-67":`Режим черги для активних запусків. Використовуйте "steer", щоб додавати запити до активного запуску, "followup" — щоб виконувати їх пізніше, "collect" — щоб згодом обробляти сумісні повідомлення пакетно, або "interrupt" — щоб переривати активний запуск перед виконанням найновішого запиту.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Префікс вихідної відповіді`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Типовий режим показу статистики використання під відповіддю`},help:{"v1-l3shsx-dv":`Типовий режим показу статистики використання під кожною відповіддю ("off"|"tokens"|"full"), який застосовується до сеансів, де режим не вибрано через /usage. Також приймає "on" як застарілий псевдонім для "tokens". Приймає окремий режим або зіставлення режимів для каналів із резервним значенням "default". Пріоритет: значення сеансу -> значення каналу -> default -> off; явний вибір через /usage (зокрема off) зберігається та перевизначає типове значення. Використовуйте /usage reset (псевдоніми: inherit, clear, default), щоб скинути перевизначення для сеансу й знову успадкувати це налаштоване типове значення.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Реакції стану`},help:{"v1-193764l-3s":`Реакції, що відображають стан життєвого циклу й оновлюють емодзі на повідомленні, яке запустило агента, у міру його роботи (у черзі → обмірковування → інструмент → завершено/помилка).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Увімкнути реакції стану`},help:{"v1-1qnmmnc-7x":`Увімкнути реакції на статуси життєвого циклу в підтримуваних каналах. Discord вважає невстановлене значення ввімкненим, якщо активні реакції підтвердження; Slack, Signal, Telegram і WhatsApp використовують реакції життєвого циклу, лише якщо це значення дорівнює true. Для відображення прогресу Slack за замовчуванням використовує вбудований статус гілки асистента.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Шаблон нижнього колонтитула використання`},help:{"v1-1xibc23-47":`Власний шаблон нижнього колонтитула /usage full у вигляді вбудованого об’єкта або шляху до JSON-файлу. Якщо шаблон недійсний або недоступний, використовується вбудований рядок використання.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Видимі відповіді`},help:{"v1-7yfwc2-8t":`Керує вихідними відповідями моделі в особистих і групових розмовах та каналах. "message_tool" вимагає message(action=send) для звичайних відповідей асистента й загальних медіаданих інструментів; вивід середовища виконання, явно віднесений до хоста, і надалі може доставлятися, за винятком фонових подій кімнати. "automatic" публікує звичайні відповіді, як і раніше.`}},meta:{label:{"v1-1xpfxac-m":`Метадані сумісності`},help:{"v1-1owqhgn-2w":`Метадані сумісності, які залишаються доступними для читання старішими версіями, щоб ті могли відхиляти небезпечні пониження версії конфігурації.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Версія останньої зміни конфігурації`},help:{"v1-qykpv1-1i":`Версія OpenClaw, яка востаннє записала цю конфігурацію.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Маркери міграцій конфігурації`},help:{"v1-burt8q-1q":`Обмежений набір маркерів сумісності для завершених міграцій конфігурації.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Міграція списку дозволів політики моделей`},help:{"v1-5psop1-1z":`Фіксує, що обмеження застарілої мапи моделей було збережено або оцінено.`}},"meta%2Emigrations%2EskillLibraryToolSplit":{label:{"v1-1x6n7ed-y":`Міграція відокремлення інструмента бібліотеки навичок`},help:{"v1-jph48r-3s":`Фіксує, що політики інструментів, які охоплюють skill_workshop, було поширено на skill_library, коли створення вмісту особистої бібліотеки перенесли до окремого інструмента.`}},"meta%2Emigrations%2EskillWorkshopPlugin":{label:{"v1-1703542-v":`Міграція плагіна Skill Workshop`},help:{"v1-1y4ur5t-2i":`Фіксує, що політику плагіна Skill Workshop, записану тоді, коли Workshop був вбудованим, було видалено.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Міграція для відокремлення допоміжних моделей`},help:{"v1-vzdfqx-2t":`Фіксує, що неявно визначені основні моделі з попередньої конфігурації було збережено перед відокремленням вибору допоміжних моделей.`}},models:{label:{"v1-hzmwb-6":`Моделі`},help:{"v1-1h1niol-5q":`Кореневий розділ каталогу моделей для визначень постачальників, режимів об’єднання/заміни та необов’язкової інтеграції виявлення Bedrock. Задавайте визначення постачальників явно й перевіряйте їх, перш ніж покладатися на резервні маршрути у виробничому середовищі.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Оновлення каталогу моделей`},help:{"v1-1hess4t-40":`Керує фоновими оновленнями вбудованого каталогу моделей. Віддалені записи можуть оновлювати метадані моделей, але не можуть змінювати кінцеві точки чи заголовки постачальників.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Оновлення каталогу моделей увімкнено`},help:{"v1-1fogpjj-3j":`Отримувати оновлення розміщеного каталогу моделей у фоновому режимі (типово: true). Установіть false, щоб вимкнути весь мережевий обмін із віддаленим каталогом моделей.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`URL оновлення каталогу моделей`},help:{"v1-ai1thy-6o":`Замініть URL розміщеного каталогу моделей на URL власного HTTPS-дзеркала (для тестування дозволено HTTP на localhost). Під час наступної перевірки каталогу запущений Gateway припинить використовувати каталог із попереднього джерела й перейде на каталог дзеркала без перезапуску.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Режим каталогу моделей`},help:{"v1-1ofrnsp-es":`Керує поведінкою каталогу постачальників: "merge" зберігає вбудованих постачальників і накладає на них ваших власних, тоді як "replace" використовує лише налаштованих вами постачальників. У режимі "merge" для постачальників з однаковими ID зберігаються непорожні значення baseUrl з файлу models.json агента, а значення apiKey зберігаються лише тоді, коли постачальник не керується через SecretRef у поточному контексті конфігурації/профілю автентифікації; постачальники, керовані через SecretRef, оновлюють apiKey за поточними маркерами джерел, а для contextWindow/maxTokens відповідних моделей використовується більше зі значень у явних і неявних записах.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Постачальники моделей`},help:{"v1-7b5l2y-fo":`Конфігурації кінцевих точок моделей із ключами за ідентифікатором постачальника. Для незалежної власної кінцевої точки виберіть новий ідентифікатор, наприклад gpu-a або my-lab. Вбудовані ідентифікатори й псевдоніми, а також ті, що належать розширенням, зберігають семантику своїх інтеграцій; налаштування такого ідентифікатора накладається на відповідну інтеграцію. Ідентифікатор не визначає протокол обміну даними — його визначає api. Кілька власних ідентифікаторів можуть використовувати той самий адаптер із різними базовими URL-адресами, обліковими даними та моделями. Для незалежного сервера використовуйте окремий ідентифікатор, а не перепризначайте openai лише через сумісність сервера з OpenAI. Власні записи мають містити baseUrl і models.`}},"models%2Eproviders%2E*":{help:{"v1-1sjqhly-54":`Одна іменована конфігурація постачальника. Замініть * на вибраний ідентифікатор або на ідентифікатор наявної інтеграції, яку ви навмисно хочете перевизначити. Пошук у схемі працює ще до налаштування власного ідентифікатора.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Середовище виконання провайдера моделей`},help:{"v1-1luy4fb-5o":`Необов’язкова низькорівнева політика середовища виконання агента для цього провайдера. Використовуйте політику середовища виконання на рівні провайдера або моделі замість фіксації середовища для всього агента; якщо значення не вказано або залишено типовим, OpenClaw вибере середовище виконання для вибраного провайдера.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`Ідентифікатор середовища виконання провайдера моделей`},help:{"v1-1gusd9s-69":`Ідентифікатор середовища виконання агента провайдера: "openclaw", "auto", ідентифікатор зареєстрованої оболонки виконання плагіна, наприклад "codex", або підтримуваний псевдонім бекенду CLI, наприклад "claude-cli". Для OpenAI на офіційній кінцевій точці за відсутності значення типово використовується оболонка виконання Codex.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`Адаптер API провайдера моделей`},help:{"v1-jpi8x4-6e":`Адаптер протоколу обміну даними, незалежний від ідентифікатора постачальника. Chat Completions: openai-completions; Responses: openai-responses; Messages: anthropic-messages. Виберіть інші адаптери з дозволених значень відповідно до протоколу вашого зовнішнього сервісу.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`Ключ API провайдера моделей`},help:{"v1-1p84k96-54":`Облікові дані провайдера для автентифікації за ключем API, коли провайдер вимагає прямої автентифікації за ключем. Використовуйте підстановку секретів або змінних середовища й не зберігайте справжні ключі у файлах конфігурації, доданих до системи контролю версій.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Режим автентифікації провайдера моделей`},help:{"v1-1g4jg7x-et":`Вибирає спосіб автентифікації провайдера: "api-key" — автентифікація за ключем API, "token" — за токеном пред’явника, "oauth" — за обліковими даними OAuth, "aws-sdk" — визначення облікових даних AWS, а "none" — для власних кінцевих точок openai-completions, які не вимагають автентифікації. Явно задане значення "none" пропускає облікові дані та не надсилає заголовок Authorization; інші фактично застосовані адаптери відхиляються. "native-command" делегує роботу з обліковими даними явно налаштованому середовищу виконання Codex для власного провайдера Responses через HTTPS; цей режим не можна поєднувати з ключами API, профілями або перевизначеннями параметрів запиту.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Заголовок Authorization провайдера моделей`},help:{"v1-1gn3lt3-59":`Якщо встановлено true, облікові дані надсилаються через HTTP-заголовок Authorization, навіть якщо можлива альтернативна автентифікація. Використовуйте лише тоді, коли провайдер або проксі явно вимагає пересилання Authorization.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`Базова URL-адреса провайдера моделей`},help:{"v1-1ku88v8-53":`Базова URL-адреса кінцевої точки провайдера, яка обслуговує запити до моделей для цього запису провайдера. Використовуйте кінцеві точки HTTPS і за потреби задавайте URL-адреси для конкретного середовища за допомогою шаблонів конфігурації.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Заголовки провайдера моделей`},help:{"v1-chg59u-4x":`Статичні HTTP-заголовки, що додаються до запитів провайдера для маршрутизації за орендарями, автентифікації проксі або виконання особливих вимог шлюзу. Використовуйте їх помірковано та зберігайте конфіденційні значення заголовків у секретах.`}},"models%2Eproviders%2E*%2Eicon":{label:{"v1-1cwoqcc-j":`Піктограма постачальника моделей`},help:{"v1-opei4i-9m":`Необов’язкове зображення постачальника: локальний файл, публічна HTTPS-адреса зображення або вбудована піктограма. Вихідні зображення PNG, JPEG, WebP і GIF обмежені розміром 2 МіБ і 4096 пікселями на сторону та надаються як очищені статичні PNG. Відносні шляхи до файлів визначаються від каталогу активного файлу конфігурації. Якщо зображення недійсне, використовується фірмова піктограма постачальника або перша літера його відображуваного імені.`}},"models%2Eproviders%2E*%2Eicon%2Ename":{label:{"v1-btu3z4-r":`Вбудована піктограма постачальника моделей`},help:{"v1-14mjg6a-3j":`Назва вбудованої піктограми вебзастосунку, наприклад server. Якщо назва невідома, використовується вбудована фірмова піктограма постачальника або перша літера його відображуваного імені.`}},"models%2Eproviders%2E*%2Eicon%2Epath":{label:{"v1-1pddy1u-o":`Файл піктограми постачальника моделей`},help:{"v1-1fgtl8e-73":`Шлях до локального файлу PNG, JPEG, WebP або GIF на Gateway. Відносні шляхи визначаються від каталогу, що містить активний файл конфігурації; ~/ розгортається в домашній каталог користувача Gateway. Через маршрут ресурсів, обмежений цим постачальником, доступне лише це налаштоване зображення.`}},"models%2Eproviders%2E*%2Eicon%2Esource":{label:{"v1-13ahm5t-q":`Джерело піктограми постачальника моделей`},help:{"v1-173lyjy-3i":`Джерело зображення: file для локального зображення на Gateway, url для загальнодоступного зображення за HTTPS або builtin для іконки, що постачається з вебзастосунком.`}},"models%2Eproviders%2E*%2Eicon%2Eurl":{label:{"v1-1euf5yl-n":`URL піктограми постачальника моделей`},help:{"v1-147pn2x-65":`Публічна HTTPS-адреса зображення PNG, JPEG, WebP або GIF без вбудованих облікових даних чи фрагмента. Gateway завантажує й очищує зображення із захистом від доступу до приватних мереж і небезпечних переспрямувань; браузер ніколи не звертається до цієї URL-адреси безпосередньо.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Додавання num_ctx провайдером моделей (сумісність з OpenAI)`},help:{"v1-53rmcr-6n":"Визначає, чи додає OpenClaw `options.num_ctx` для провайдерів Ollama, налаштованих за допомогою адаптера, сумісного з OpenAI (`openai-completions`). Типове значення — true. Установлюйте false, лише якщо ваш проксі або сервер вище за ланцюжком відхиляє невідомі поля `options` у тілі запиту."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Локальна служба провайдера моделей`},help:{"v1-9r1lm6-4y":`Необов’язковий процес локального сервера моделей для цього постачальника, що запускається на вимогу. OpenClaw перевіряє healthUrl, за потреби запускає команду, очікує готовності, а потім надсилає запит до моделі.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Аргументи локальної служби постачальника моделей`},help:{"v1-t12wib-27":`Список аргументів, що передаються команді локального сервера моделей без розгортання оболонкою.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Команда локальної служби постачальника моделей`},help:{"v1-64k3ef-4h":`Абсолютний шлях до виконуваного файлу процесу локального сервера моделей. Указуйте цей шлях явно, щоб запуск провайдера був передбачуваним і не залежав від пошуку в PATH оболонки.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Робочий каталог локальної служби постачальника моделей`},help:{"v1-fi3xlx-1h":`Робочий каталог процесу локального сервера моделей.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Середовище локальної служби постачальника моделей`},help:{"v1-1lwb9k1-3k":`Додаткові змінні середовища для процесу локального сервера моделей. Значення, схожі на секретні, приховуються у знімках конфігурації.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL перевірки працездатності локальної служби постачальника моделей`},help:{"v1-12nvqxl-36":`URL для перевірки готовності перед запитами до моделі. Якщо не вказано, OpenClaw використовує baseUrl постачальника з доданим /models.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Зупинка локальної служби постачальника моделей у разі бездіяльності`},help:{"v1-1efg054-3z":`Час у мілісекундах, протягом якого локальний сервер моделей, запущений OpenClaw, продовжує працювати після завершення останнього запиту. Установіть 0, щоб він працював до завершення роботи OpenClaw.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Час очікування готовності локальної служби постачальника моделей`},help:{"v1-bwmfqa-2r":`Максимальний час очікування успішної перевірки готовності локального сервера моделей після запуску процесу, у мілісекундах.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Максимальна кількість токенів постачальника моделей`},help:{"v1-fnj50y-38":`Типова максимальна кількість вихідних токенів для моделей цього постачальника, якщо в записі моделі не задано maxTokens.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Список моделей постачальника`},help:{"v1-1vbm0gt-63":`Задекларований список моделей постачальника, що містить ідентифікатори, метадані, специфічні для постачальника параметри та необов’язкові відомості про сумісність і вартість. Ідентифікатори мають точно відповідати значенням у каталозі постачальника, щоб вибір і перехід до резервної моделі працювали коректно.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Середовище виконання моделі`},help:{"v1-1k70g2n-3g":`Необов’язкова низькорівнева політика середовища виконання агента для цієї конкретної моделі. Політика середовища виконання моделі має пріоритет над політикою середовища виконання постачальника.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`Ідентифікатор середовища виконання моделі`},help:{"v1-1llzv33-42":`Ідентифікатор середовища виконання агента моделі: "openclaw", "auto", зареєстрований ідентифікатор виконавчого модуля плагіна, наприклад "codex", або підтримуваний псевдонім бекенду CLI, наприклад "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Медіавхід моделі`},help:{"v1-wxtj8e-2x":`Необов’язкові метадані про можливості моделі щодо медіа, які інструменти використовують для вибору обережних типових параметрів стиснення зображень.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Вхідні зображення моделі`},help:{"v1-1nviirq-3c":`Необов’язкові обмеження для вхідних зображень цієї моделі, як-от максимальна довжина сторони, максимальна кількість пікселів і бажана довжина сторони для стиснення.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Максимальний розмір зображення моделі в байтах`},help:{"v1-c2469j-23":`Максимальний розмір закодованих даних зображення, який постачальник приймає для цієї моделі.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Максимальна кількість пікселів зображення моделі`},help:{"v1-9d6yqp-1u":`Максимальна кількість пікселів зображення, яку постачальник приймає для цієї моделі.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Максимальна довжина сторони зображення моделі`},help:{"v1-1gbci08-1y":`Максимальна ширина або висота зображення, яку постачальник приймає для цієї моделі.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Бажана довжина сторони зображення моделі`},help:{"v1-1u1mpcg-2x":`Бажана довжина сторони під час зміни розміру зображення для збалансованого стиснення. Залиште незаданою, щоб використовувати обережне типове значення OpenClaw.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Режим обліку токенів зображень моделі`},help:{"v1-1oy6z7v-1z":`Спосіб обліку токенів зображень у провайдера: "tile", "detail" або "provider".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EresponseModelEquivalent":{help:{"v1-1hociw2-d7":`Установіть true для створеного користувачем запису власного провайдера, якщо маршрутизатор або брокер самостійно визначає цей ідентифікатор моделі. Тоді будь-який ідентифікатор у відповіді, повідомлений кінцевою точкою, вважається еквівалентним, зокрема й у разі внутрішніх підмін на кінцевій точці. Ідентифікатор фактично використаної моделі та дані про використання й надалі записуються; повідомлення OpenClaw про резервне перемикання та перевизначення зберігаються. Вбудовану або офіційну політику неможливо перевизначити. Записи плагінів і каталогу, записи в models.json агента та записи models-add не можуть надавати еквівалентність. Якщо параметр не вказано або встановлено false, зберігається звичайне визначення маршруту.`}},"models%2Eproviders%2E*%2Ename":{label:{"v1-ioaceo-r":`Відображувана назва постачальника моделей`},help:{"v1-jio82-3z":`Необов’язкова назва, що відображається в налаштуваннях постачальника та списках вибору моделей. Не змінює ідентифікатор постачальника, посилання на моделі, облікові дані чи маршрутизацію.`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Параметри виконання провайдера моделей`},help:{"v1-464sgu-4t":`Специфічні для провайдера параметри виконання, які інтерпретуються його плагінами. Використовуйте ключі, задокументовані провайдером, і віддавайте перевагу явним вказівкам у документації провайдера, а не довільним загальним припущенням.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Регіон провайдера моделей`},help:{"v1-yq7rxk-5h":`Необов’язковий регіон розгортання/API провайдера, який інтерпретується провайдерами з регіональними кінцевими точками. Підтримувані значення наведено в документації провайдера; якщо також задано перевизначення baseUrl, воно зазвичай має пріоритет.`}},"models%2Eproviders%2E*%2Eremote":{label:{"v1-ih3vfx-11":`Часові параметри сторожового таймера для хмарного постачальника моделей`},help:{"v1-bsr5s-9g":`Перевизначення часових параметрів лише сторожового таймера для локальних ретрансляторів перед хмарними API. Якщо встановлено true, сторожові таймери простою LLM та очікування першої події використовують часові параметри для хмарних сервісів навіть за наявності локального baseUrl, ідентифікатора постачальника, localService або маркера локальної автентифікації. Якщо значення відсутнє або встановлено false, зберігається визначення локальності. Явно заданий timeoutSeconds і ліміти часу виконання або агента зберігають пріоритет.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Перевизначення параметрів запитів до провайдера моделей`},help:{"v1-1lkxryk-87":`Необов’язкові перевизначення параметрів запитів до провайдера моделей, зокрема додаткові заголовки, перевизначення автентифікації, маршрутизація через проксі, налаштування клієнта TLS і необов’язковий параметр allowPrivateNetwork для довірених кінцевих точок на власній інфраструктурі. Використовуйте їх лише тоді, коли ваш зовнішній сервіс або шлях через корпоративну мережу потребує налаштування транспортного рівня.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Дозволити приватну мережу для запитів до провайдера моделей`},help:{"v1-1nbtcjk-fo":`Якщо встановлено true, дозволяє HTTP-запити до постачальника моделей у приватні, CGNAT або подібні діапазони через захисний механізм HTTP-запитів постачальника (fetchWithSsrFGuard). Для користувацьких і локальних базових URL постачальників уже діє довіра до точно налаштованого джерела, крім джерел метаданих, link-local і NAT64 для локального використання (64:ff9b:1::/48); установіть false, щоб вимкнути цю довіру. OpenAI Responses WebSocket повторно використовує request для заголовків і TLS, але не використовує цей шлях запитів із захистом від SSRF. Використовуйте true лише для самостійно розгорнутих кінцевих точок під контролем оператора, яким потрібен доступ до приватних джерел поза джерелом, налаштованим у baseUrl.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Перевизначення автентифікації запитів до постачальника моделей`},help:{"v1-ucdgnf-1w":`Перевизначає поведінку автентифікації запитів для цього постачальника.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Назва заголовка автентифікації запитів до постачальника моделей`},help:{"v1-1881nqr-1i":`Користувацька назва заголовка автентифікації, що використовується в режимі автентифікації header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Режим автентифікації запитів до постачальника моделей`},help:{"v1-1lhv8hs-24":`Режим перевизначення автентифікації: "provider-default", "authorization-bearer" або "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Префікс заголовка автентифікації запитів до постачальника моделей`},help:{"v1-1rbm9lz-21":`Необов’язковий префікс, що додається перед request.auth.value у режимі автентифікації header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Токен Bearer для запитів до постачальника моделей`},help:{"v1-6rcasw-1l":`Токен Bearer, що використовується в режимі автентифікації authorization-bearer.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Значення заголовка автентифікації запитів до постачальника моделей`},help:{"v1-1v69ej-1j":`Власне значення заголовка автентифікації, що використовується в режимі автентифікації header.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Заголовки запитів до постачальника моделей`},help:{"v1-zj3orj-2i":`Додаткові заголовки, що додаються до запитів до постачальника після визначення стандартної атрибуції та автентифікації.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Проксі для запитів до постачальника моделей`},help:{"v1-md5uj8-4j":`Необов’язкове перевизначення проксі для запитів до постачальника моделей. Використовуйте "env-proxy", щоб враховувати налаштування проксі із середовища, або "explicit-proxy", щоб спрямовувати запити через проксі з указаною URL-адресою.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Режим проксі для запитів до постачальника моделей`},help:{"v1-1dx0ozg-29":`Режим перевизначення проксі для запитів до постачальника моделей: "env-proxy" або "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`TLS проксі для запитів до постачальника моделей`},help:{"v1-rdx62w-1v":`Необов’язкові налаштування TLS, що використовуються під час підключення до налаштованого проксі.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`CA TLS проксі для запитів до постачальника моделей`},help:{"v1-11pg2fd-1s":`Власний набір сертифікатів CA для перевірки ланцюжка TLS-сертифікатів проксі.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`TLS-сертифікат проксі для запитів до постачальника моделей`},help:{"v1-x8nk2q-22":`Клієнтський сертифікат TLS, що надається проксі, коли потрібна взаємна автентифікація TLS.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Пропуск перевірки TLS для проксі запитів до постачальника моделей`},help:{"v1-12vjdm9-2j":`Пропускає перевірку сертифіката TLS проксі. Використовуйте лише в контрольованих середовищах розробки.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`Ключ TLS для проксі запитів до постачальника моделей`},help:{"v1-1skyr56-1w":`Приватний ключ, що відповідає request.proxy.tls.cert, для взаємної автентифікації TLS із проксі.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`Парольна фраза TLS для проксі запитів до постачальника моделей`},help:{"v1-wjvoxd-1m":`Необов’язкова парольна фраза для розшифрування request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`Ім’я сервера TLS для проксі запитів до постачальника моделей`},help:{"v1-b4oabu-22":`Необов’язкове перевизначення SNI/імені сервера під час установлення TLS-з’єднання з проксі.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`URL проксі для запитів до постачальника моделей`},help:{"v1-kvbgou-48":`Явно задана URL-адреса проксі, яка використовується, коли request.proxy.mode має значення explicit-proxy. Облікові дані, вбудовані в URL-адресу, вважаються конфіденційними та приховуються у знімках.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS для запитів до постачальника моделей`},help:{"v1-16u7v7h-2b":`Необов’язкові налаштування TLS для прямого підключення до кінцевої точки моделі на стороні постачальника.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`Центр сертифікації TLS для запитів до постачальника моделей`},help:{"v1-ny8y3e-1v":`Власний набір сертифікатів центрів сертифікації для перевірки ланцюжка TLS-сертифікатів постачальника.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`TLS-сертифікат для запитів до постачальника моделей`},help:{"v1-1lltmhw-2e":`Клієнтський TLS-сертифікат, що надається кінцевій точці постачальника, коли потрібна взаємна автентифікація TLS.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Пропуск перевірки TLS для запитів до постачальника моделей`},help:{"v1-1006cuy-2m":`Пропускає перевірку TLS-сертифіката постачальника. Використовуйте лише в контрольованих середовищах розробки.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`Ключ TLS для запитів до постачальника моделей`},help:{"v1-w2agir-1t":`Приватний ключ у парі з request.tls.cert для взаємної автентифікації TLS із постачальником.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`Парольна фраза TLS для запитів до постачальника моделей`},help:{"v1-10ds42f-1g":`Необов’язкова парольна фраза для розшифрування request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`Ім’я сервера TLS для запитів до постачальника моделей`},help:{"v1-18yt7x9-1y":`Необов’язкове перевизначення SNI/імені сервера для встановлення TLS-з’єднання з постачальником.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Час очікування запиту до постачальника моделей`},help:{"v1-t3yn8l-ih":`Необов’язковий час очікування запиту до моделі в секундах для окремого провайдера. Налаштування запитів на рівні провайдера впливають на явно задані записи моделей цього провайдера; вони не створюють неявних моделей. Для власних провайдерів задайте його разом із baseUrl та models провайдера. Застосовується до HTTP-запитів провайдера, зокрема до встановлення з’єднання, отримання заголовків і тіла та обробки переривання всього запиту, а також підвищує для цього провайдера граничний час контролю бездіяльності/потоку LLM понад неявне стандартне значення ~120 с. Використовуйте це налаштування для повільних локальних або самостійно розміщених серверів моделей чи для хмарних провайдерів, які буферизують токени міркування, не передаючи даних мережею (Gemini preview, Claude/Opus із великим обсягом даних інструментів), замість зміни глобальних тайм-аутів агента.`}},"models%2Eusage":{label:{"v1-1frhz6j-e":`Використання ресурсів провайдера`},help:{"v1-hn2n9r-18":`Налаштування кешу даних про використання тарифного плану, які надає провайдер.`}},"models%2Eusage%2EcacheTtlMs":{label:{"v1-1g6hvog-t":`TTL кешу даних про використання ресурсів провайдера (мс)`},help:{"v1-jltn3b-4j":`Повторно використовувати знімки даних про використання ресурсів провайдера протягом зазначеної кількості мілісекунд (за замовчуванням: 60000). Застосовується до звичайного зчитування та зчитування після виконання; 0 вимикає повторне використання. Не вмикає опитування під час простою.`}},nodeHost:{label:{"v1-nb8lk1-9":`Хост вузла`},help:{"v1-8recuz-4z":`Налаштування хоста вузла для функцій, які цей вузол шлюзу надає іншим вузлам або клієнтам. Залиште стандартні значення, якщо не плануєте навмисно проксіювати локальні можливості через мережу вузлів.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Запуски агента на вузлі`},help:{"v1-4uz5ur-2k":`Увімкніть виконання нативних ходів агента, що потребують схвалення, на цьому хості вузла без графічного інтерфейсу. Стандартно вимкнено.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Запуски агента Claude на вузлі`},help:{"v1-g8az5y-2l":`Визначає, чи може цей хост вузла без графічного інтерфейсу повідомляти шлюзу про доступність ходів агента Claude CLI.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Запуски агента Claude на вузлі ввімкнено`},help:{"v1-1ke804l-44":`Повідомляти про можливість продовження сеансу Claude на спареному вузлі, коли доступний локальний виконуваний файл claude (стандартно: false). Запуски й надалі потребують схвалення виконання команд на вузлі.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Автоматичні оновлення вузлів`},help:{"v1-16xjk4e-5n":`Керує автоматичними оновленнями окремого середовища виконання для хостів вузлів без графічного інтерфейсу, що постачаються як готові пакети. Перевіряє оновлення щогодини й очікує завершення всіх завдань вузла перед перезапуском; інтервал між автоматичними перезапусками становить щонайменше 12 годин.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Автоматичні оновлення вузлів увімкнено`},help:{"v1-1sa0yeg-7w":`Увімкніть автоматичні оновлення зі стабільного або бета-каналу для тривало працюючих вузлів без графічного інтерфейсу, що постачаються як готові пакети (за замовчуванням: true). Установіть false, щоб відмовитися від них. Також вимикається через update.checkOnStart=false або OPENCLAW_NO_AUTO_UPDATE=1; для робочих копій вихідного коду, нативних застосунків, приватних робочих процесів, dev і extended-stable оновлення не застосовуються автоматично.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Проксі браузера вузла`},help:{"v1-2xrew7-4f":`Групує налаштування браузерного проксі для надання доступу до локального керування браузером через маршрутизацію вузла. Увімкніть, лише якщо робочим процесам віддаленого вузла потрібні ваші локальні профілі браузера.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Дозволені профілі браузерного проксі вузла`},help:{"v1-1ew5dkm-8b":`Необов’язковий список дозволених назв профілів браузера, доступних через проксі-маршрутизацію вузла. Залиште порожнім, щоб зберегти повний доступ до профілів за замовчуванням, зокрема до маршрутів створення й видалення профілів. Якщо список задано, OpenClaw обмежує доступ до профілів за принципом найменших привілеїв і блокує створення та видалення постійних профілів через проксі.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Браузерний проксі вузла ввімкнено`},help:{"v1-pa04pd-5b":`Надає доступ до локального сервера керування браузером через проксі-маршрутизацію вузла, щоб віддалені клієнти могли використовувати можливості браузера цього хоста. Залишайте вимкненим, якщо віддалена автоматизація явно цього не потребує.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`MCP хоста вузла`},help:{"v1-1mdhrwl-48":`Використовуйте як інструменти агента сервери MCP, запущені хостом вузла без графічного інтерфейсу та опубліковані на сполученому з ним Gateway. Перезапустіть хост вузла після зміни цього розділу.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Сервери MCP хоста вузла`},help:{"v1-19m002f-3x":`Іменовані визначення серверів MCP, локальні для цього вузла. Використовує ту саму структуру сервера, що й mcp.servers; хост вузла не підтримує сервери OAuth.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Skills хоста вузла`},help:{"v1-v8txza-41":`Використовуйте цей розділ, щоб публікувати навички, встановлені в ~/.openclaw/skills, із хоста вузла без графічного інтерфейсу. Перезапустіть хост вузла після зміни файлів навичок.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Skills хоста вузла ввімкнено`},help:{"v1-1ggpkqb-36":`Сканувати й публікувати навички, розміщені на вузлі, після підключення (типово: true). Установіть false, щоб вимкнути публікацію навичок вузла.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Запуски робочих процесів на вузлі`},help:{"v1-1w83rox-2p":`Увімкніть повноцінне розміщення сеансів робочих процесів OpenClaw із пакетів, керованих Gateway. Типово вимкнено.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Ліміт запусків робочих процесів на вузлі`},help:{"v1-10nvk8f-3w":`Максимальна кількість одночасних сеансів робочих процесів на цьому вузлі (типово: кількість доступних ядер процесора). Має бути цілим числом від 1 до 1024.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Образ контейнера для запуску робочих процесів на вузлі`},help:{"v1-1tmr1le-5y":`Необов’язковий образ Node 24.22.1+ або 26.12.1+ для робочих процесів, ізольованих у контейнерах (за замовчуванням: "node:24.22.1-slim"). За потреби використовуйте образ із фіксованим дайджестом, із приватного реєстру або попередньо завантажений образ; відсутні образи завантажуються під час першого використання.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Запуски робочих процесів на вузлі ввімкнено`},help:{"v1-b3t0xp-2t":`Дозволити цьому сполученому вузлу розміщувати сеанси саме з тих пакетів, які встановив його Gateway (типово: false).`}},"nodeHost%2EworkerRuns%2Efolders":{label:{"v1-1waimc-r":`Папки сеансів робочого процесу вузла`},help:{"v1-ald547-9v":`Необов’язкові базові каталоги, які обмежують сеанси роботи на місці цими каталогами та їхніми підкаталогами. Якщо значення не задано, дозволено будь-який наявний каталог, крім кореневих каталогів файлової системи та приватного сховища робочого процесу; [] вимикає сеанси в папках пристрою. Використовуйте абсолютні шляхи або шляхи з ~/. Наявні файли залишаються на пристрої; видалення сеансу ніколи не видаляє ці папки. Потрібен параметр workerRuns.enabled.`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Ізоляція запусків робочих процесів на вузлі`},help:{"v1-19i6swo-58":`Виберіть межу ізоляції процесів для робочих сеансів: "none" — запуск безпосередньо на хості вузла (типово); "container" — потрібен працездатний рушій, сумісний із Docker, без переходу до виконання на хості в разі збою.`}},plugins:{label:{"v1-10renyj-7":`Плагіни`},help:{"v1-1qbev2k-5c":`Засоби керування системою плагінів для ввімкнення розширень, обмеження області завантаження, налаштування записів і відстеження встановлень. У виробничих середовищах задавайте політику плагінів явно й дотримуйтеся принципу найменших привілеїв.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Список дозволених плагінів`},help:{"v1-1w1dsc3-ek":`Необов’язковий список дозволених ідентифікаторів плагінів; непорожній список обмежує завантаження, за винятком вибраного плагіна пам’яті (зокрема memory-core, вибраного за замовчуванням), плагінів context-engine із тим самим ідентифікатором і явно ввімкнених вбудованих каналів чату. Власники context-engine з іншими назвами мають бути окремо ввімкнені або додані до списку дозволених, а також включені до будь-якого непорожнього списку дозволених. Інструменти плагінів, яких немає в списку дозволених, залишаються недоступними. Використовуйте plugins.deny або plugins.entries.<id>.enabled: false, щоб заблокувати плагін незалежно від вибору слота.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Список заборонених плагінів`},help:{"v1-4gyt4z-4i":`Необов’язковий список ідентифікаторів плагінів, які блокуються, навіть якщо їх включено до списків дозволених плагінів або шляхів. Використовуйте правила заборони для екстреного відкочування та безумовного блокування ризикованих плагінів.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Увімкнути плагіни`},help:{"v1-pnygd7-50":`Глобально вмикає або вимикає завантаження плагінів і розширень під час запуску та перезавантаження конфігурації (за замовчуванням: true). Залишайте ввімкненим, лише якщо у вашому розгортанні потрібні можливості розширень.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Записи плагінів`},help:{"v1-cn74rf-54":`Налаштування окремих плагінів, згруповані за ідентифікатором плагіна, зокрема стан увімкнення та специфічні для плагіна параметри виконання. Використовуйте їх для точкового налаштування плагінів без зміни глобальної політики завантаження.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`Ключ API плагіна`},help:{"v1-ctytg2-53":`Необов’язкове поле ключа API для плагінів, які підтримують безпосереднє налаштування ключа в параметрах запису. Використовуйте підстановку секретів або змінних середовища й не зберігайте справжні облікові дані у файлах конфігурації.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Конфігурація плагіна`},help:{"v1-1he672p-51":`Дані конфігурації, визначені плагіном, які він обробляє за власною схемою та правилами перевірки. Використовуйте лише поля, описані в документації плагіна, щоб уникнути ігнорування налаштувань або помилок у них.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Плагін увімкнено`},help:{"v1-12soc0h-9a":`Перевизначення стану ввімкнення окремого плагіна, що застосовується поверх глобальної політики плагінів. У стандартному гібридному режимі перезавантаження зміни оновлюють середовище виконання плагіна на льоту для нових ходів агента без перезапуску Gateway, якщо плагін не вимагає перезапуску для цього шляху. Використовуйте це для поступового розгортання плагіна в різних середовищах.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Змінні середовища плагіна`},help:{"v1-p39pu4-52":`Набір змінних середовища окремого плагіна, що передається лише в контекст його середовища виконання. Використовуйте це, щоб обмежити доступ до облікових даних постачальника одним плагіном замість використання спільного глобального середовища процесу.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Політика хуків плагіна`},help:{"v1-1oslnrf-4c":`Налаштування політики типізованих хуків окремого плагіна для перевірок безпеки, які забезпечує ядро. Використовуйте це, щоб обмежити категорії хуків зі значним впливом, не вимикаючи весь плагін.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Дозволити хуки доступу до розмови`},help:{"v1-xqz31z-7e":"Визначає, чи може цей плагін читати необроблений вміст розмови через типізовані хуки, як-от `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` і `agent_end`. Для плагінів, що не входять до комплекту, цей дозвіл потрібно надати явно."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptModification":{label:{"v1-1ufndoc-e":`Змінювати промпти`},help:{"v1-10llywv-8b":`Дозволяє цьому плагіну додавати або змінювати контекст та інструкції, що надсилаються моделі, а це може впливати на її відповіді. Надавайте цей дозвіл лише плагінам, яким довіряєте. Типово дозволено. Установіть false, щоб заблокувати хуки, які змінюють промпти, вказівки для промптів інструментів, доповнення до промптів наступного кроку та спрямування поточного виконання.`}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Час очікування хука плагіна (мс)`},help:{"v1-4ra6b7-74":`Типовий час очікування в мілісекундах для типізованих хуків цього плагіна, обмежений значенням 600000. Якщо значення не задано, кожен хук використовує час очікування, оголошений плагіном, або політику Gateway для відповідного хука; єдиного фіксованого типового значення немає. Значення для окремих хуків у hooks.timeouts мають пріоритет.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Перевизначення часу очікування хуків плагіна`},help:{"v1-yphl9b-5s":`Перевизначення часу очікування для окремих хуків у мілісекундах, де ключами є назви типізованих хуків, а значення обмежені числом 600000. Використовуйте точкові перевизначення для відомих повільних хуків, як-от before_prompt_build або agent_end, замість збільшення часу очікування для всіх хуків.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`Політика LLM плагіна`},help:{"v1-dlca6c-4j":`Налаштування api.runtime.llm.complete для окремого плагіна, що визначають довіру до перевизначення моделі й агента. Залиште цей параметр незаданим, якщо плагіну не потрібно явно керувати викликами генерації, що належать основній системі.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Дозволити плагіну перевизначати агента LLM`},help:{"v1-k8c08b-4n":`Явно дозволяє цьому плагіну викликати api.runtime.llm.complete з ідентифікатором агента, відмінним від стандартного. Залиште false, якщо плагіну не довірено доступ до моделей інших агентів.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Дозволити плагіну перевизначати профіль автентифікації LLM`},help:{"v1-9ityw9-4x":`Дозволяє цьому плагіну вибирати профіль автентифікації, відмінний від стандартного, для генерації в ізольованому середовищі виконання агента. Залиште false, якщо плагіну не довірено явну ізольовану маршрутизацію облікових даних.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Дозволені моделі генерації LLM для плагіна`},help:{"v1-1kgxs8j-55":`Дозволені цільові моделі для кожної генерації LLM плагіна у вигляді повних посилань "provider/model", зокрема типові значення, визначені хостом, і перевизначення. Використовуйте "*", лише якщо свідомо дозволяєте будь-яку модель.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Дозволені моделі LLM для плагіна`},help:{"v1-h9m5ew-48":`Дозволені цільові моделі для перевизначення в довірених викликах LLM плагіна у вигляді повних посилань "provider/model". Використовуйте "*", лише якщо свідомо дозволяєте перевизначення на будь-яку модель.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Дозволити плагіну перевизначати модель LLM`},help:{"v1-uw4jmc-47":`Явно дозволяє цьому плагіну запитувати перевизначення моделі в api.runtime.llm.complete. Залишайте false, якщо плагіну не довірено керувати вибором моделі.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Політика субагентів плагіна`},help:{"v1-wbf4m1-4d":`Окремі для кожного плагіна налаштування виконання субагентів: довіра до перевизначення моделі та списки дозволених моделей. Залишайте це поле незаданим, якщо плагіну не потрібно явно керувати вибором моделі субагента.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Дозволені моделі субагентів плагіна`},help:{"v1-hdzz51-43":`Дозволені цільові моделі для перевизначення в довірених запусках субагентів плагіна у вигляді повних посилань "provider/model". Використовуйте "*", лише якщо свідомо дозволяєте будь-яку модель.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Дозволити плагіну перевизначати модель субагента`},help:{"v1-1r5tzm1-4g":`Явно дозволяє цьому плагіну запитувати перевизначення постачальника/моделі під час фонових запусків субагентів. Залишайте false, якщо плагіну не довірено керувати вибором моделі.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Завантажувач плагінів`},help:{"v1-1myjwbi-52":`Група налаштувань завантажувача плагінів для визначення шляхів файлової системи, у яких виконується пошук плагінів. Задавайте шляхи завантаження явно та перевіряйте їх, щоб уникнути випадкового завантаження недовірених розширень.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Шляхи завантаження плагінів`},help:{"v1-o689p1-4z":`Додаткові файли або каталоги плагінів, які завантажувач сканує на додачу до стандартних вбудованих розташувань. Використовуйте окремі каталоги для розширень і уникайте шляхів із широким охопленням, що містять сторонній виконуваний вміст.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Слоти плагінів`},help:{"v1-zx6crl-5f":`Визначає, які плагіни займають ексклюзивні слоти середовища виконання, як-от пам’ять, щоб лише один плагін надавав відповідну функціональність. Явно призначайте власників слотів, щоб уникнути дублювання постачальників із суперечливою поведінкою.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-tp8do7-h":`Ідентифікатор рушія контексту`},help:{"v1-1ww2hr0-4h":`Визначає ідентифікатор зареєстрованого рушія контексту. Плагіни, у яких ідентифікатори плагіна та рушія відрізняються, оголошують contextEngineIds у своєму маніфесті, щоб OpenClaw міг завантажити плагін-власник.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Плагін пам’яті`},help:{"v1-6kb575-6d":`Виберіть активний плагін пам’яті за ідентифікатором (за замовчуванням: memory-core) або "none", щоб вимкнути плагіни пам’яті. Вибраний плагін може завантажуватися, навіть якщо його немає в plugins.allow; plugins.deny та явне вимкнення окремого плагіна все одно мають пріоритет.`}},presence:{label:{"v1-10fdwo4-8":`Присутність`}},proxy:{label:{"v1-ji57pa-d":`Керований проксі`},help:{"v1-vui6bx-58":`Керована оператором маршрутизація через прямий проксі для HTTP, HTTPS, WebSocket і підтримуваних каналів вихідного трафіку низького рівня в середовищі виконання OpenClaw. Використовуйте, якщо централізований контроль вихідного трафіку входить до меж розгортання.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Керований проксі ввімкнено`},help:{"v1-1456xdw-49":`Явне перевизначення режиму керованого проксі. Наявність URL типово вмикає маршрутизацію; установіть false, щоб ігнорувати URL проксі з конфігурації або середовища, не видаляючи їх.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Режим loopback керованого проксі`},help:{"v1-1kaiuh0-3c":`Керує маршрутизацією площини керування Gateway через loopback, коли активний режим керованого проксі: "gateway-only", "proxy" або "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`URL керованого проксі`},help:{"v1-p36b5l-3v":`URL керованого прямого проксі. Використовуйте http:// для звичайного CONNECT-проксі або https://, якщо саме з’єднання з кінцевою точкою проксі має використовувати TLS.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS керованого проксі`},help:{"v1-6i0vu-3q":`Налаштування TLS для підключення до кінцевої точки керованого проксі. Ці налаштування застосовуються до TLS проксі, а не до TLS цільового сервера після CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`Файл CA для TLS керованого проксі`},help:{"v1-1ntzjia-2p":`Шлях у файловій системі до власного набору сертифікатів CA, що використовується для перевірки сертифіката кінцевої точки керованого HTTPS-проксі.`}},repositoryBranchPrefix:{label:{"v1-1sxh9u9-o":`Префікс гілок репозиторію`},help:{"v1-10w2bot-41":`Префікс для нових гілок сеансів у віддаленому репозиторії. За замовчуванням — openclaw; гілки мають формат <prefix>/<workspace GUID>. Наявні гілки залишаються без змін.`}},secrets:{label:{"v1-1sihgpy-7":`Секрети`},help:{"v1-jgn0o9-2l":`Постачальники посилань на секрети, поведінка спільного сховища та необов’язковий захист вихідного трафіку підпроцесів.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Проксі вихідного трафіку для секретів`},help:{"v1-1qfgid-4n":`Loopback-проксі під керуванням Gateway, який замінює маркери секретів зі спільного сховища лише під час надсилання вихідного запиту. Перезапустіть Gateway після зміни цього розділу, налаштування якого застосовуються під час запуску.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Дозволені хости проксі вихідного трафіку для секретів`},help:{"v1-9ypodl-6t":`Необов’язковий список дозволених напрямків трафіку для запитів і тунелів CONNECT. Якщо його задано, адреси призначення мають бути в цьому списку, у прив’язці хоста до окремого секрету або в bypassHosts. Порожній список дозволяє лише прив’язані хости або хости обходу. Після зміни перезапустіть Gateway.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Хости обходу вихідного проксі для секретів`},help:{"v1-1oiiomv-57":`Точні імена хостів, які використовують автентифіковані тунелі CONNECT без перевірки вмісту для клієнтів із закріпленими сертифікатами. Маркери-заповнювачі залишаються зашифрованими й не пройдуть автентифікацію в постачальника, замість того щоб розкрити відкритий текст.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Вихідний проксі для секретів увімкнено`},help:{"v1-u99b1i-2h":`Увімкнення підстановки секретів у вихідному трафіку для підпроцесів агента, що працюють у Gateway. Типове значення: false.`}},"security%2Eaudit":{label:{"v1-16w033o-e":`Аудит безпеки`}},"security%2Eaudit%2Esuppressions":{label:{"v1-1l4qjwk-i":`Приховані результати аудиту`},help:{"v1-1deyl5p-4f":`Прийняті результати аудиту безпеки, які слід виключити з поточного зведення та списку результатів. Відповідні результати залишаються доступними в полі suppressedFindings у виводі JSON.`}},"security%2Eaudit%2Esuppressions%2E*%2EcheckId":{label:{"v1-pfzkxp-e":`Ідентифікатор перевірки аудиту`}},"security%2Eaudit%2Esuppressions%2E*%2EdetailIncludes":{label:{"v1-ykrpzg-n":`Опис результату містить`}},"security%2Eaudit%2Esuppressions%2E*%2Ereason":{label:{"v1-1581z0k-i":`Причина приховування`}},"security%2Eaudit%2Esuppressions%2E*%2EtitleIncludes":{label:{"v1-18y11at-m":`Заголовок результату містить`}},"security%2EinstallPolicy":{label:{"v1-1dbuvhm-e":`Політика встановлення`}},"security%2EinstallPolicy%2Eenabled":{label:{"v1-bfdyp9-l":`Увімкнути політику встановлення`},help:{"v1-67yonn-4i":`Увімкнути довірену локальну команду політики для встановлення й оновлення навичок і плагінів. Якщо ввімкнено без налаштованої команди, встановлення підтримуваних об’єктів блокується.`}},"security%2EinstallPolicy%2Eexec":{label:{"v1-433033-m":`Команда політики встановлення`},help:{"v1-1hyg77m-46":`Довірена локальна команда, що повертає рішення щодо встановлення: "allow", "warn" або "block". Укажіть абсолютний шлях до виконуваного файлу; OpenClaw запускає його без командної оболонки.`}},"security%2EinstallPolicy%2Eexec%2Eargs":{label:{"v1-17c9br2-o":`Аргументи команди політики`}},"security%2EinstallPolicy%2Eexec%2Ecommand":{label:{"v1-l86c0l-h":`Виконуваний файл політики`}},"security%2EinstallPolicy%2Eexec%2Eenv":{label:{"v1-f7gtc3-s":`Змінні середовища політики`}},"security%2EinstallPolicy%2Eexec%2EmaxOutputBytes":{label:{"v1-1jz3qk1-r":`Обмеження виводу політики (байти)`}},"security%2EinstallPolicy%2Eexec%2EnoOutputTimeoutMs":{label:{"v1-bu8clf-o":`Час очікування за бездіяльності політики (мс)`}},"security%2EinstallPolicy%2Eexec%2EpassEnv":{label:{"v1-uzu2wx-12":`Успадковані змінні середовища політики`}},"security%2EinstallPolicy%2Eexec%2Esource":{label:{"v1-wv29f-l":`Джерело команди політики`}},"security%2EinstallPolicy%2Eexec%2EtimeoutMs":{label:{"v1-i9ag7r-j":`Час очікування політики (мс)`}},"security%2EinstallPolicy%2Eexec%2EtrustedDirs":{label:{"v1-1kkqbtr-q":`Довірені каталоги політики`}},"security%2EinstallPolicy%2Etargets":{label:{"v1-ss3w1g-m":`Цілі політики встановлення`},help:{"v1-1ar6u6h-2v":`Застосовуйте політику встановлення до "skill", "plugin" або обох типів. Не вказуйте цей список, щоб охопити всі підтримувані цілі.`}},session:{label:{"v1-8yh9jr-7":`Сеанс`},help:{"v1-j86s32-5d":`Глобальні налаштування маршрутизації та скидання сеансів, політики доставки й обслуговування історії розмов. Залиште типові значення, якщо вам не потрібні суворіші обмеження щодо ізоляції, зберігання чи доставки.`}},"session%2Ecommunication":{label:{"v1-133tjjf-u":`Стандартні параметри обміну повідомленнями між сеансами`},help:{"v1-1y4eege-63":`Стандартні параметри для нових повідомлень між сеансами. Для кожного напрямку можна вказати always, ask або never; стандартне значення — always. Сеанси успадковують ці значення, доки людина не перевизначить їх; наявні обмеження доступу залишаються чинними.`}},"session%2Ecommunication%2Ereceive":{label:{"v1-efg2gh-10":`Отримувати повідомлення від інших сеансів`},help:{"v1-t6w901-5q":`Стандартний параметр приймання нових повідомлень від інших сеансів: always дозволяє, ask вимагає схвалення людини перед передаванням даних моделі або початком нової роботи, а never блокує. Це не змінює видимість історії чи доступ людини.`}},"session%2Ecommunication%2Esend":{label:{"v1-1chq2bl-v":`Надсилати повідомлення іншим сеансам`},help:{"v1-92cfz7-65":`Стандартний параметр ініціювання надсилання повідомлень іншим сеансам: always дозволяє, ask вимагає схвалення людини перед надсиланням, а never блокує. Для запитаних відповідей і дозволеного обміну повідомленнями в межах делегованих завдань зберігаються наявні повноваження.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Область сеансу особистих повідомлень`},help:{"v1-ql362c-5l":`Область сеансів особистих повідомлень: "main" зберігає безперервність, а "per-peer", "per-channel-peer" і "per-account-channel-peer" посилюють ізоляцію. Використовуйте ізольовані режими для спільних скриньок вхідних повідомлень або розгортань із кількома обліковими записами.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Область групового сеансу`},help:{"v1-1fdezx2-6i":`Область сеансів груп і каналів: "per-group" розділяє кімнати, а головний сеанс агента стежить за ними у фоновому режимі незалежно від dmScope; "main" об’єднує контекст кімнат у головному сеансі й не потребує стеження. Використовуйте "main" лише для довірених кімнат.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Зв’язки ідентичностей сеансу`},help:{"v1-4mwmyr-5k":`Зіставляє спільні ідентичності з ідентифікаторами співрозмовників із префіксом провайдера, щоб повідомлення від того самого користувача потрапляли в одну гілку особистого листування (приклад: telegram:123456). Використовуйте, коли та сама людина спілкується через кілька каналів або облікових записів.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Ключ основного сеансу`},help:{"v1-18p638h-3q":`Приймається, але ігнорується: суфікс основного сеансу для кожного агента завжди має значення "main". Не вказуйте це поле; для глобальної області сеансів натомість використовується "global".`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Обслуговування сеансів`},help:{"v1-hdyrb-68":`Параметри автоматичного обслуговування сховища сеансів: архівування сеансів застосунку, видалення за давністю, обмеження кількості записів, зберігання архівів скинутих сеансів і очищення для дотримання дискового ліміту. Почніть із режиму warn, щоб оцінити вплив, а після налаштування порогових значень увімкніть enforce.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Архівувати неактивні сеанси панелі керування через`},help:{"v1-1krn130-60":"Архівує неактивні сеанси, розпочаті в застосунку OpenClaw, після вказаного періоду (наприклад, `7d`), щоб вони залишалися доступними, не перевантажуючи список активних сеансів. Установіть `false` або `0`, щоб вимкнути автоматичне архівування."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-ogfwwy-h":`Холодне сховище чатів`},help:{"v1-kqjx1d-5m":`Переміщує неактивні чати до стиснених архівів JSONL, зберігаючи метадані сеансів. Архівні файли стають обов’язковою частиною історії та мають входити до резервних копій. Зміни застосовуються без перезапуску Gateway.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Архівувати після вказаної кількості днів неактивності`},help:{"v1-1f9pk9f-55":`Архівувати чати після вказаної кількості днів неактивності (додатне ціле число, типово 30). Поточну роботу захищено; зміна порогу набуває чинності під час наступного проходу фонового процесу без перезапуску Gateway.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-17fys4q-v":`Автоматично архівувати старі чати`},help:{"v1-1sdhnti-5s":`Вмикає фонове архівування чатів (типове значення — true). Установіть false, щоб вимкнути подальше перенесення до архіву. Фоновий процес щохвилини перевіряє наявність чатів, що відповідають умовам архівування. Ця політика архівування діє окремо від видалення та очищення для дотримання ліміту дискового простору.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Цільовий верхній поріг використання диска сеансами`},help:{"v1-143vh09-7z":`Цільовий розмір після очищення в межах дискового ліміту (верхній поріг). За замовчуванням становить 80% від maxDiskBytes; задайте явно для інтенсивнішого звільнення місця на дисках з обмеженою місткістю. Якщо обчислене значення дорівнює нулю, використовується значення за замовчуванням; від’ємні значення неприпустимі. Для вимкнення ліміту використовуйте maxDiskBytes.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Максимальний дисковий ліміт сеансів`},help:{"v1-ocx4rx-cl":'Ліміт фізичного дискового простору для кожного агента, що охоплює основний файл SQLite, WAL і враховані артефакти каталогу сеансів (наприклад, `500mb`). Типове значення — `10gb`; через захищені дані використання простору може перевищувати цільове значення. У разі перевищення режим warn повідомляє про нестачу простору, а режим enforce видаляє старі артефакти скидання й видалення, історію без посилань на неї, а потім архіви, створені через обмеження кількості записів. Архіви, створені вручну, за правилами зберігання за давністю, для сеансів застосунку чи відновлення, а також архіви старого формату залишаються захищеними. Установіть `false`, `0` або `"0"`, щоб вимкнути.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Максимальна кількість записів сеансів`},help:{"v1-1w2egrh-7u":`Обмежує кількість неархівованих записів сеансів (за замовчуванням — 5000). Придатні для архівування довготривалі розмови понад ліміт архівуються разом з історією; одноразові записи автоматизації видаляються. Наявні архіви не враховуються в ліміті. Захищені активні записи й надалі враховуються та можуть утримувати кількість записів у сховищі понад ліміт.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Режим обслуговування сеансів`},help:{"v1-qhc707-7c":`Визначає, чи система лише повідомляє про дії, передбачені політиками очищення та обмеження дискового простору ("warn"), чи виконує їх ("enforce"). Під час упровадження залиште "warn" і перейдіть на "enforce" після перевірки безпечності порогових значень. Холодне сховище ввімкнено за замовчуванням; для його вимкнення є окреме налаштування.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Зберігати нещодавні сеанси`},help:{"v1-138q5wx-89":"Захищає інтерактивні сеанси, активні протягом цього періоду (наприклад, `7d`), від автоматичного видалення історії за віком, кількістю та лімітом дискового простору. Якщо значення не задано або встановлено `false`, діє звичайна політика видалення найстаріших записів першими. Синтетичні записи запусків моделі, cron, hook, heartbeat, ACP і субагентів залишаються доступними для очищення в установлених межах."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Очищати сеанси після`},help:{"v1-1xn50w7-76":"Архівує придатні для цього довготривалі розмови та видаляє тимчасові записи автоматизації, старші за вказаний період (типово `30d`; наприклад, `12h`). Архівовані розмови зберігають свою історію та можуть бути відновлені; захищені розмови або розмови з можливістю маршрутизації залишаються активними."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Зберігання архівів скинутих сеансів`},help:{"v1-3rw301-7l":"Зберігання архівованих чатів залежно від їхнього віку (`*.reset.<timestamp>` і `*.deleted.<timestamp>`). За замовчуванням архіви зберігаються, доки ліміт дискового простору не спричинить їх видалення, починаючи з найстаріших; задайте тривалість (наприклад, `30d`), щоб увімкнути видалення за фактичним часом, або `false`, щоб явно вимкнути його."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Сповіщати головну сесію про створення сесії`},help:{"v1-14mr1ov-8m":`Додавати системне сповіщення до черги в сеансі Home агента-власника під час створення сеансу (типово: true). Сповіщення містять доступні метадані назви та автора й зчитуються під час наступного ходу Home або запланованої автоматизації. Установіть false, щоб вимкнути; чернетки, сеанси інкогніто, внутрішні сеанси та заплановані запуски cron виключено.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Політика скидання сеансів`},help:{"v1-1hmt7n3-6r":`Визначає об’єкт типової політики скидання, який використовується, якщо немає перевизначення для конкретного типу чи каналу. Типово сеанси не скидаються автоматично; щоб увімкнути автоматичне скидання, налаштуйте щоденний розклад або скидання після періоду бездіяльності. Команди /new і /reset залишаються доступними будь-коли.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Година щоденного скидання сеансів`},help:{"v1-wry8cv-59":`Задає годину за місцевим часом (0–23) для режиму щоденного скидання, щоб сеанси починалися заново в передбачуваний час. Використовуйте з mode=daily та узгоджуйте з очікуваним часовим поясом оператора, щоб поведінка була зрозумілою.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Хвилини бездіяльності до скидання сеансу`},help:{"v1-1kzj0id-5e":`Задає період бездіяльності до скидання у відповідному режимі, а також може слугувати додатковою умовою скидання в щоденному режимі. Використовуйте більші значення для збереження безперервності або менші — для частішого оновлення короткотривалих гілок розмов.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Режим скидання сеансів`},help:{"v1-e5ie4w-5b":`Вибирає стратегію скидання: "none" вимикає автоматичне скидання (типове значення), "daily" виконує скидання о заданій годині, а "idle" — після періоду неактивності. /new і /reset залишаються доступними в усіх режимах.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Скидання сеансу за каналом`},help:{"v1-1uxsulx-5h":`Дає змогу перевизначати параметри скидання для окремих каналів за ідентифікатором постачальника/каналу, щоб точно керувати поведінкою. Використовуйте це лише тоді, коли одному каналу потрібна особлива поведінка скидання, що виходить за межі політик для типу чату.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Скидання сеансу за типом чату`},help:{"v1-ypdr7u-52":`Перевизначає поведінку скидання за типом чату (direct, group, thread), коли типових налаштувань недостатньо. Використовуйте це, коли для спілкування в групах або гілках потрібна інша частота скидання, ніж для особистих повідомлень.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Скидання сеансу (особистий чат)`},help:{"v1-22e702-54":`Визначає політику скидання для особистих чатів і замінює базову конфігурацію session.reset для цього типу. Використовуйте як актуальне перевизначення для особистих повідомлень замість застарілого псевдоніма dm.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Скидання сеансу (груповий чат)`},help:{"v1-hl1200-4u":`Визначає політику скидання для сеансів групових чатів, де безперервність спілкування та характер інформаційного шуму відрізняються від особистих повідомлень. Для активних груп використовуйте коротші періоди неактивності, якщо відхилення контексту стає проблемою.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Скидання сеансу (гілка)`},help:{"v1-1hgpeke-4w":`Визначає політику скидання для сеансів у межах гілки, зокрема для цілеспрямованої роботи в гілках каналів. Використовуйте це, коли сеанси гілок мають завершуватися швидше або повільніше, ніж сеанси інших типів чатів.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Тригери скидання сеансу`},help:{"v1-rcabsw-5a":`Перелік тригерів повідомлень, які примусово скидають сеанс у разі збігу у вхідному вмісті. Використовуйте їх обмежено й лише для явних фраз скидання, щоб контекст не втрачався несподівано під час звичайної розмови.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Область дії сеансу`},help:{"v1-axt4ds-5z":`Задає базову стратегію групування сеансів: "per-sender" ізолює їх за відправником, а "global" використовує один спільний сеанс у межах контексту каналу. Залишайте "per-sender" для безпечнішої роботи з кількома користувачами, якщо спільний контекст не є цілеспрямованою вимогою.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Політика надсилання між сеансами`},help:{"v1-17zdvww-61":`Керує доставленням повідомлень сеансу за допомогою правил allow/deny, які перевіряються за каналом, chatType і префіксами ключів. Це окремий механізм, незалежний від дозволів на вхідні й вихідні повідомлення між сеансами; для їхніх стандартних параметрів використовуйте session.communication.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Типова дія політики надсилання між сеансами`},help:{"v1-15plhut-53":`Задає дію за відсутності збігів із правилами sendPolicy: "allow" або "deny". Залишайте "allow" для простіших конфігурацій або вибирайте "deny", якщо для кожного місця призначення потрібне явне правило дозволу.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Правила політики надсилання між сеансами`},help:{"v1-o217za-5h":'Упорядковані правила дозволу й заборони, що перевіряються перед застосуванням типової дії, наприклад `{ action: "deny", match: { channel: "discord" } }`. Розміщуйте найконкретніші правила першими, щоб загальні правила не перекривали винятки.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Дія правила надсилання між сеансами`},help:{"v1-178vm80-54":`Визначає рішення правила як "allow" або "deny", коли відповідні критерії збігу виконано. Щоб забезпечити суворі обмеження з явними винятками для дозволу, розміщуйте правила заборони першими.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Умови збігу правила надсилання сеансу`},help:{"v1-18qh5qg-5d":`Визначає необов’язкові умови збігу правила, які можуть поєднувати обмеження за channel, chatType і префіксом ключа. Задавайте вузькі умови збігу, щоб призначення політики залишалося зрозумілим, а налагодження — простим.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Канал правила надсилання сеансу`},help:{"v1-u5erwx-50":`Обмежує застосування правила певним ідентифікатором каналу або провайдера (наприклад, discord, telegram, slack). Використовуйте, коли один канал має дозволяти або забороняти доставку незалежно від інших.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Тип чату правила надсилання сеансу`},help:{"v1-7cv4f9-4z":`Обмежує застосування правила типом чату (direct, group, thread), щоб поведінка залежала від форми розмови. Використовуйте, коли для особистих і групових повідомлень потрібні різні обмеження безпеки.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Префікс ключа правила надсилання сеансу`},help:{"v1-ac4dee-5n":`Перевіряє збіг із нормалізованим префіксом ключа сеансу після внутрішніх етапів нормалізації ключа в компонентах, що застосовують політику. Використовуйте для загального керування за префіксом, а коли потрібне точне зіставлення з повним ключем, віддавайте перевагу rawKeyPrefix.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Префікс необробленого ключа правила надсилання сеансу`},help:{"v1-1g9w044-5e":`Зіставляє вихідний, ненормалізований префікс ключа сеансу для точного застосування політики за повним ключем. Використовуйте, коли нормалізований keyPrefix охоплює забагато сеансів і потрібна точність з урахуванням префікса агента або конкретного транспорту.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Режими спільного доступу до сеансів`},help:{"v1-xbh52d-5a":`Визначає, які режими співпраці можуть вибирати власники сеансів та адміністратори. Якщо логічні значення не задано, відповідні режими типово ввімкнено; установіть для режиму false, щоб прибрати його зі списку вибору та заборонити його подальший вибір.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Дозволити чернеткові сеанси`},help:{"v1-1lzap27-2p":`Дозволяє чернетковий режим видимості, який приховує сеанси від операторів, що не є їхніми власниками чи адміністраторами. Типове значення: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Дозволити сеанси лише для читання`},help:{"v1-upl3nu-21":`Дозволяє робити сеанси доступними лише для читання для тих, хто не є учасником. Типове значення: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Дозволити сеанси з пропозиціями`},help:{"v1-4i8owu-4g":`Дозволяє режим видимості з пропозиціями. На цьому етапі він застосовує ту саму політику допуску, що й режим лише для читання; налаштування черг пропозицій буде доступне в майбутній функції. Типове значення: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Шлях до сховища сеансів`},help:{"v1-hreznz-56":`Задає шлях до файлу сховища сеансів, який використовується для збереження записів сеансів між перезапусками. Указуйте явний шлях лише тоді, коли потрібні нестандартне розміщення на диску, окремий шлях для резервного копіювання або зберігання на змонтованому томі.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Прив’язки сеансів до гілок`},help:{"v1-zbzihu-4s":`Спільні типові налаштування створення та маршрутизації сеансів, прив’язаних до гілок, у підтримуваних каналах. Задайте тут глобальні типові налаштування та перевизначайте їх для окремих каналів лише тоді, коли поведінка відрізняється.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Контекст створення сеансу в гілці`},help:{"v1-gnhqsg-46":`Типовий власний контекст субагента для запусків, прив’язаних до гілки. Використовуйте "fork", щоб почати з чату ініціатора запиту, або "isolated", щоб створити дочірній агент із чистим контекстом. За замовчуванням: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Прив’язування до гілок увімкнено`},help:{"v1-foomtc-3f":`Головний глобальний перемикач створення, маршрутизації та доставки для сеансів, прив’язаних до гілок. Вимкніть, щоб глобально вимкнути прив’язування до гілок.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Час очікування бездіяльності прив’язки до гілки (години)`},help:{"v1-gffnx3-3h":`Типовий період бездіяльності в годинах для сеансів, прив’язаних до гілок, у всіх постачальників і каналах (0 вимикає завершення через бездіяльність). Типове значення: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Максимальний термін дії прив’язки до гілки (години)`},help:{"v1-1xfcyhw-39":`Необов’язковий жорсткий ліміт терміну дії в годинах для сеансів, прив’язаних до гілок, у всіх постачальників і каналах (0 вимикає жорсткий ліміт). Типове значення: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Створення сеансів, прив’язаних до гілок`},help:{"v1-1lqwbdl-46":`Глобальний типовий дозвіл на створення робочих сеансів, прив’язаних до гілок, через sessions_spawn і створення гілок ACP. Типове значення: true, коли прив’язування до гілок увімкнено.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Дозволені цілі символічних посилань навички`},help:{"v1-xzybiq-4t":`Довірені кореневі каталоги фактичних цілей, на які можуть указувати символічні посилання навичок поза налаштованим кореневим каталогом джерела. Обмежте цей перелік, наприклад каталогом навичок у сусідньому репозиторії.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Додаткові каталоги навичок`},help:{"v1-11o7opu-53":`Додаткові спільні кореневі каталоги навичок для сканування з найнижчим пріоритетом. Використовуйте для сусідніх репозиторіїв або спільних наборів навичок, які мають бути доступні без копіювання до робочого простору OpenClaw.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Відстеження Skills`},help:{"v1-1g8a3b0-8g":`Увімкніть виявлення навичок за подіями файлової системи з контрольним повторним скануванням кожні 30 хвилин на випадок пропущених подій. Якщо вимкнути цю функцію, явні зміни навичок OpenClaw, відповідні зміни конфігурації та запуск Gateway і надалі негайно оновлюватимуть навички. Наявні сеанси використовуватимуть змінені знімки під час наступного ходу агента.`}},storage:{label:{"v1-eop0jq-7":`Зберігання`},help:{"v1-j0mwbg-4w":`Розташування для зберігання артефактів OpenClaw, які можна використовувати повторно. Ядро системи зберігання відповідає за ідентифікацію розташувань, шифрування та стан; провайдери передають об’єкти, а споживачі вирішують, що зберігати.`}},"storage%2Elocations":{label:{"v1-uok3ae-h":`Розташування сховищ`},help:{"v1-1ipmwky-5k":`Іменовані розташування для зберігання. Назви містять від 1 до 63 малих літер, цифр або дефісів і починаються з літери чи цифри. Кожне розташування зберігає маркер ініціалізації, який ніколи не створюється під час запису даних у процесі роботи.`}},"storage%2Elocations%2E*":{label:{"v1-1pbn8xd-g":`Розташування сховища`},help:{"v1-7yhxyl-4n":`Одне іменоване розташування для зберігання з налаштуваннями провайдера та явно вибраним режимом шифрування. Перед записом об’єктів ініціалізуйте нове розташування за допомогою openclaw storage init.`}},"storage%2Elocations%2E*%2Eencryption":{label:{"v1-1qp46kf-i":`Шифрування сховища`},help:{"v1-19oj6cx-6d":`Обов’язковий вибір режиму шифрування: об’єкт passphrase забезпечує шифрування об’єктів перед вивантаженням; "none" явно вимикає шифрування. Резервні копії можуть містити облікові дані, тому використовуйте "none" лише тоді, коли розташування вже забезпечує належний захист.`}},"storage%2Elocations%2E*%2Eencryption%2Epassphrase":{label:{"v1-1x3jq0t-t":`Парольна фраза для шифрування сховища`},help:{"v1-1o63v7d-4o":`Парольна фраза для шифрування цього розташування. Надавайте перевагу SecretRef і зберігайте копію, яку можна відновити: втрата або зміна парольної фрази унеможливлює читання наявних зашифрованих об’єктів.`}},"storage%2Elocations%2E*%2Eprovider":{label:{"v1-1dujppr-g":`Провайдер сховища`},help:{"v1-16srbor-3w":`Ідентифікатор постачальника сховища, наприклад "filesystem". Посилання на вбудованого постачальника автоматично вмикає його плагін, якщо політика плагінів не забороняє цього.`}},"storage%2Elocations%2E*%2Esettings":{label:{"v1-268wio-p":`Налаштування постачальника сховища`},help:{"v1-drbso5-5t":`Налаштування JSON з обмеженнями, визначені постачальником. Для значень із секретними даними потрібно використовувати об’єкти SecretRef, які постачальник розв’язує лише за потреби. Постачальник filesystem вимагає абсолютного шляху до наявного каталогу.`}},surfaces:{label:{"v1-exl2ye-g":`Політики інтерфейсів`},help:{"v1-vgtjbs-50":`Перевизначення політик повідомлень для окремих інтерфейсів, де ключем є визначений ідентифікатор інтерфейсу доставки. Використовуйте лише тоді, коли одному з розгорнутих інтерфейсів потрібна суворіша обробка мовчазних відповідей, ніж типова для агента.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Політика мовчазних відповідей інтерфейсу`},help:{"v1-1un880p-4z":`Перевизначає групову політику відсутності відповіді для одного визначеного каналу доставки. Незадані поля успадковують agents.defaults.silentReply. Прямі чати та внутрішні сеанси завжди вимагають відповіді.`}},talk:{label:{"v1-15ukbjj-4":`Розмова`},help:{"v1-1gx10xa-5g":`Налаштування синтезу мовлення в режимі Talk: характеристики голосу, вибір моделі, формат виводу та поведінка під час переривання. Використовуйте цей розділ, щоб налаштувати взаємодію з користувачем через голос, контролюючи затримку та витрати.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Агент Talk`},help:{"v1-iee5l9-2b":`Агент, якому належать сеанси Talk, створені без явно заданого ключа сеансу, прив’язаного до агента.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Швидкий режим консультацій Talk`},help:{"v1-syf3xk-2o":`Використовуйте цей параметр, щоб установити значення true або false для швидкого режиму звичайного запуску агента, який забезпечує консультації Talk у реальному часі.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Рівень міркування для консультацій Talk`},help:{"v1-1ft5njw-2o":`Використовуйте цей параметр, щоб перевизначити рівень міркування для звичайного запуску агента, який забезпечує консультації Talk у реальному часі.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Переривання Talk під час мовлення користувача`},help:{"v1-8n9q4o-3l":`Якщо встановлено true (типове значення), мовлення асистента припиняється, коли користувач починає говорити в режимі Talk. Залиште ввімкненим для почергового обміну репліками.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Активний провайдер Talk`},help:{"v1-wgnxhg-1g":`Ідентифікатор активного провайдера Talk (наприклад, "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Налаштування провайдерів Talk`},help:{"v1-oh0yuv-30":`Налаштування Talk для окремих провайдерів, згруповані за ідентифікаторами провайдерів. Під час міграції надавайте їм перевагу над застарілими ключами talk.*.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Конфігурація провайдера Talk`},help:{"v1-36pblg-1r":`Поля конфігурації Talk, визначені провайдером із відповідним ідентифікатором.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Ключ API провайдера Talk`},help:{"v1-1a1p9wp-v":`Ключ API провайдера для режиму Talk.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk у реальному часі`},help:{"v1-c2re7j-3z":`Постачальник, модель, голос, режим, транспорт і стратегія міркування для Talk у реальному часі. Зберігайте конфігурацію постачальника мовлення/TTS у talk.provider і talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Міркування Talk у реальному часі`},help:{"v1-opsatw-37":`Стратегія міркування Talk: agent-consult для допомоги агента через Gateway, direct-tools для локальних викликів інструментів або none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Маршрутизація консультацій Talk у реальному часі`},help:{"v1-10qjcvk-5f":`Резервне пересилання остаточних транскрипцій мовлення користувача через Gateway, коли постачальник реального часу пропускає openclaw_agent_consult. provider-direct зберігає відповіді постачальника; force-agent-consult спрямовує запити через OpenClaw.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Інструкції Talk у реальному часі`},help:{"v1-1jaaj84-5p":`Додаткові системні інструкції, що додаються до вбудованого запиту OpenClaw для Talk у реальному часі. Використовуйте їх для налаштування стилю голосу, тону та іншої поведінки постачальника в реальному часі, не змінюючи настанови agent-consult.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Режим Talk у реальному часі`},help:{"v1-1u2xui1-1l":`Режим виконання Talk: realtime, stt-tts або transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Модель Talk у реальному часі`},help:{"v1-amou5a-27":`Перевизначення ідентифікатора моделі постачальника реального часу для сеансів Talk у браузері або під керуванням Gateway.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Попередній аудіобуфер Talk у реальному часі (мс)`},help:{"v1-1cwg07n-22":`Кількість мілісекунд аудіо, що зберігається перед виявленням голосової активності в реальному часі.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Постачальник Talk у реальному часі`},help:{"v1-wwsmpt-1o":`Ідентифікатор активного постачальника голосового зв’язку в реальному часі, наприклад openai або google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Налаштування постачальників Talk у реальному часі`},help:{"v1-ruagcu-1r":`Налаштування голосового зв’язку в реальному часі для окремих постачальників, згруповані за ідентифікатором постачальника.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Конфігурація постачальника Talk у реальному часі`},help:{"v1-edfpxm-1u":`Власна конфігурація голосового зв’язку в реальному часі постачальника з відповідним ідентифікатором.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Ключ API постачальника Talk у реальному часі`},help:{"v1-1fbmgpx-z":`Ключ API постачальника для Talk у реальному часі.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Рівень міркування Talk у реальному часі`},help:{"v1-157xd3e-2t":`Рівень міркування, специфічний для постачальника, у сеансах Talk у реальному часі, наприклад minimal, low, medium або high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Тривалість тиші в Talk у реальному часі (мс)`},help:{"v1-1grnu06-1y":`Тривалість тиші в мілісекундах, після якої репліка користувача в Talk у реальному часі вважається завершеною.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Голос мовця Talk у реальному часі`},help:{"v1-1kgb166-2h":`Перевизначення назви голосу мовця постачальника реального часу для сеансів Talk у браузері або під керуванням Gateway.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Ідентифікатор голосу мовця Talk у реальному часі`},help:{"v1-1k8w6vk-2f":`Перевизначення ідентифікатора голосу мовця постачальника реального часу для сеансів Talk у браузері або під керуванням Gateway.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Транспорт Talk у реальному часі`},help:{"v1-2otjgn-2g":`Транспорт байтів/сеансів Talk: webrtc, provider-websocket, gateway-relay або managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Поріг VAD у реальному часі для Talk`},help:{"v1-nf5l2t-2j":`Поріг виявлення голосової активності в реальному часі від 0 (найвища чутливість) до 1 (найнижча чутливість).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Час очікування тиші в Talk (мс)`},help:{"v1-1kim32f-59":`Тривалість мовчання користувача в мілісекундах, після якої режим Talk завершує та надсилає поточну транскрипцію. Залиште незаданим, щоб використовувати стандартну тривалість паузи для платформи (700 мс на macOS та Android, 900 мс на iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Локаль мовлення Talk`},help:{"v1-1un3x4l-4c":`Ідентифікатор локалі BCP 47 для розпізнавання мовлення Talk на вузлах пристроїв і резервного використання системного голосу iOS, наприклад "ru-RU". Залиште незаданим, щоб використовувати стандартну локаль кожного пристрою.`}},telemetry:{label:{"v1-sqprmo-9":`Телеметрія`},help:{"v1-1o5tru3-55":`Явна згода на анонімну статистику використання функцій, що надсилається разом зі щоденною перевіркою оновлень. Статистику використання функцій типово вимкнено; вона ніколи не містить повідомлень, облікових даних чи ідентифікаторів.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Часова позначка згоди на статистику використання функцій`},help:{"v1-1t051az-3t":`Часова позначка у форматі ISO, що фіксує, коли оператор погодився на анонімну статистику використання функцій або відмовився від неї. Запобігає повторному запиту в майстрі налаштування.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Анонімна статистика використання функцій`},help:{"v1-1ptrwuq-4r":`Надсилає назви ввімкнених каналів і постачальників, кількість плагінів і нещодавніх сеансів разом зі щоденною перевіркою оновлень. Типово вимкнено й завжди вимкнено, коли DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Інструменти`},help:{"v1-1el54kl-5h":`Інфраструктура інструментів і типові налаштування взаємодії між агентами. Сусідні розділи кореневого рівня відповідають за інфраструктуру й типові налаштування взаємодії між агентами; agents.defaults — за поведінку циклу агента; записи окремих агентів можуть перевизначати обидві групи налаштувань, якщо це підтримується.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Доступ до інструментів між агентами`},help:{"v1-1ynpa5f-cf":`Політика міжагентних викликів інструментів сеансів: надсилання, отримання списку, історії, пошук і читання стану (типово ввімкнено). Використовуйте allow, щоб обмежити пари агентів; enabled=false блокує звичайний міжагентний доступ. Власні сеанси вбудованих субагентів і дочірні сеанси ACP агента-запитувача залишаються доступними за видимості tree або all. Для суворого розмежування встановіть tools.sessions.visibility у значення agent або self (tree усе ще допускає доступ до власних дочірніх сеансів вбудованих субагентів і ACP агента-запитувача) або використовуйте окремі шлюзи.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Список дозволених цільових агентів для міжагентного доступу`},help:{"v1-1jt2ari-76":`Ідентифікатори агентів або шаблони з *, що визначають учасників міжагентних викликів; і агент-запитувач, і цільовий агент мають відповідати списку. Міжагентний доступ типово ввімкнено, а відсутній або порожній allow дозволяє всі пари. Задайте явний список, щоб обмежити доступ; порожні записи забороняють доступ.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Увімкнути інструмент міжагентної взаємодії`},help:{"v1-w950oq-ba":`Вмикає міжагентний доступ до інструментів сеансів (типове значення: true); відсутній або порожній allow дозволяє всі пари агентів. Установіть false, щоб заблокувати звичайний міжагентний доступ; власні сеанси вбудованих субагентів і дочірні сеанси ACP агента-запитувача залишаються доступними за видимості tree або all. Для суворого розмежування встановіть tools.sessions.visibility у значення agent або self (tree усе ще допускає доступ до власних дочірніх сеансів вбудованих субагентів і ACP агента-запитувача) або використовуйте окремі шлюзи.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Список дозволених інструментів`},help:{"v1-1is3eaq-4v":`Абсолютний список дозволених інструментів, який замінює типові налаштування профілю для середовищ із суворими обмеженнями. Використовуйте його лише тоді, коли навмисно обмежуєте роботу ретельно дібраним набором можливостей інструментів.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Доповнення до списку дозволених інструментів`},help:{"v1-1xw9zp8-57":`Додаткові записи списку дозволених інструментів, які додаються до вибраного профілю інструментів і типової політики. Цей список має бути коротким і чітким, щоб під час аудиту можна було швидко визначити навмисні винятки з політики.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Політика інструментів за постачальниками`},help:{"v1-c1lj2f-bh":`Перевизначення дозволів і заборон для інструментів окремих провайдерів, прив’язані до ID каналу/провайдера, дають змогу налаштовувати можливості для кожного інтерфейсу. Використовуйте це, коли одному провайдеру потрібні суворіші обмеження, ніж передбачено глобальною політикою інструментів. exec.mode задає граничний режим виконання на хості для ходів цього провайдера або пари провайдер/модель, який може лише посилювати обмеження (він ніколи не скасовує обов’язкових схвалень і не послаблює суворіший режим), тому режим "auto" спрямовує на перевірку виконання лише ті запити цієї моделі, які не відповідають правилам дозволеного виконання.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Режим коду`},help:{"v1-1ecc39k-6k":'Загальний режим OpenClaw Code Mode. Якщо глобальне налаштування відсутнє, стандартне значення — `"auto"`; явно заданий об’єкт без `enabled` залишається вимкненим. Під час запусків агента з увімкненим режимом моделі доступні лише `exec` і `wait`, а доступ до звичайних інструментів здійснюється через міст каталогу.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Увімкнути режим коду`},help:{"v1-c7oqjw-ah":'Глобальна активація OpenClaw Code Mode. Якщо глобальне налаштування повністю відсутнє, типове значення — `"auto"`; явно заданий об’єкт без `enabled` залишає режим вимкненим. `"auto"` активує режим для рекомендованих каталогом моделей, а `true` — для запусків із підтримкою інструментів. Перевизначення активації для агента й моделі мають пріоритет. Якщо середовище виконання недоступне, запуск з активованим режимом блокується замість надання повного списку інструментів.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Виконавець режиму коду`},help:{"v1-4tbmdg-7h":`Виконавець JavaScript: "node" (типово) використовує Node vm для довіреного коду й не є захищеною пісочницею; "quickjs" використовує вбудований плагін QuickJS WASM для гостьового виконання з посиленим захистом. Дозволи інструментів застосовуються до обох. Code Mode не може працювати, якщо вибраний виконавець недоступний.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Обмеження обсягу виводу режиму коду`},help:{"v1-1hmij9q-1n":`Максимальна кількість серіалізованих байтів, що повертаються через вивід режиму коду.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Ліміт незавершених викликів інструментів у режимі коду`},help:{"v1-3b5tyd-2i":`Максимальна кількість одночасних вкладених викликів інструментів, які віртуальна машина в режимі коду може запустити, перш ніж їй доведеться призупинитися й відновити виконання пізніше.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Максимальна кількість результатів пошуку в режимі коду`},help:{"v1-1gpue5r-28":`Максимальна кількість результатів пошуку в прихованому каталозі, які може запитати програма в режимі коду.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Ліміт розміру знімка стану в режимі коду`},help:{"v1-1mmgkqy-1x":`Максимальна кількість серіалізованих байтів, що зберігаються для одного знімка призупиненого стану QuickJS.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Ліміт пам’яті в режимі коду`},help:{"v1-xetora-6n":`Ліміт купи гостьового середовища QuickJS або орієнтовний бюджет купи V8 робочого потоку Node у байтах. Накладні витрати середовища виконання Node і мінімальні виділення пам’яті рушієм впливають на фактичний бюджет; зовнішні буфери та RSS процесу не враховуються. Це не є гарантією безпеки.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Інтерфейс режиму коду`},help:{"v1-dsp2b9-2x":'Інтерфейс для моделі. Підтримується лише "only": надає доступ до `exec` і `wait` у режимі коду та приховує звичайні інструменти.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Кількість результатів пошуку за замовчуванням у режимі коду`},help:{"v1-1io42lu-2m":"Кількість результатів пошуку в прихованому каталозі, які `catalog.search` повертає за замовчуванням у режимі коду."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`Час життя знімка стану в режимі коду`},help:{"v1-1nxfczz-28":"Протягом якого часу призупинені запуски Code Mode можна відновити за допомогою `wait`, перш ніж строк їхньої дії спливе."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Час очікування в режимі коду`},help:{"v1-8csycm-1p":"Максимальний час у мілісекундах для одного виклику `exec` або `wait` у режимі коду."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Список заборонених інструментів`},help:{"v1-wilr1b-4p":`Глобальний список заборонених інструментів, який блокує зазначені інструменти, навіть якщо правила профілю або провайдера дозволяють їх. Використовуйте правила заборони для екстреного блокування та довгострокового багаторівневого захисту.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Доступ до інструментів із підвищеними привілеями`},help:{"v1-ehcm0r-5a":`Налаштування доступу до інструментів із підвищеними привілеями для інтерфейсів привілейованих команд, доступних лише довіреним відправникам. Залишайте вимкненими, якщо робочі процеси оператора явно не потребують дій із підвищеними привілеями.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Правила дозволу для інструментів із підвищеними привілеями`},help:{"v1-1u9bhih-54":`Правила, що дозволяють відправникам використовувати інструменти з підвищеними привілеями, зазвичай із ключами у форматах ідентифікаторів каналу чи провайдера. Указуйте конкретні ідентифікатори вузького кола користувачів, щоб сторонні користувачі не могли запускати привілейовані команди.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Увімкнути доступ до інструментів із підвищеними привілеями`},help:{"v1-1n8oyal-4l":`Дозволяє виконання інструментів із підвищеними привілеями після успішної перевірки відправника та політик. Залишайте вимкненим у публічних і спільних каналах та вмикайте лише в довірених середовищах під керуванням власника.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Інструмент exec`},help:{"v1-p5piic-56":`Група політик інструмента exec для хоста виконання команд оболонки, режиму безпеки, порядку схвалення та прив’язок середовища виконання. У виробничому середовищі зберігайте обмежувальні налаштування за замовчуванням і посилюйте обмеження на виконання з підвищеними привілеями.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Список дозволених моделей для apply_patch`},help:{"v1-4q5ovf-1x":`Необов’язковий список дозволених ідентифікаторів моделей (наприклад, "gpt-5.4" або "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`Увімкнути apply_patch`},help:{"v1-1erkir4-31":`Увімкнути або вимкнути apply_patch для моделей OpenAI та OpenAI Codex, якщо це дозволено політикою інструментів (типове значення: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch лише в робочій області`},help:{"v1-1m4u5cn-4l":`Обмежити шляхи apply_patch на хості каталогом робочого простору (типово: false). Установіть true, щоб дозволити доступ лише в межах робочого простору; вимоги щодо кореневих каталогів і обмеження сеансу залишаються чинними.`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Сповіщення про виконання після схвалення exec (мс)`},help:{"v1-1gwwann-4z":`Затримка в мілісекундах перед показом сповіщення про виконання після схвалення exec. Збільште її, щоб зменшити мерехтіння для швидких команд, або зменште, щоб швидше інформувати оператора.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Запит схвалення exec`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Підсвічування команд exec`},help:{"v1-kyxd4o-4n":`Показувати підсвічування команд на основі синтаксичного аналізу в запитах на схвалення exec (типове значення: false). Увімкніть, щоб відображати підсвічений текст команд без зміни політики схвалення exec.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Строк дії постійного дозволу (дні)`},help:{"v1-5uxe2j-6r":`Типовий строк дії в днях (1-3650) для постійних дозволів, створених через allow-always під час схвалення автоматизацій. Якщо значення не задано, дозволи діють до відкликання або зміни автоматизації, якій вони належать. Умови фіксуються під час створення, тому зміна цього параметра впливає лише на майбутні дозволи.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Ціль виконання exec`},help:{"v1-rno1mf-5q":`Вибирає стратегію визначення цільового середовища для виконання команд оболонки. Використовуйте "auto" для врахування середовища виконання (sandbox, якщо доступне, інакше gateway) або явно задайте sandbox/gateway/node, якщо потрібне фіксоване середовище.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Режим виконання`},help:{"v1-1qscgnt-5q":`Селектор нормалізованої політики exec. Використовуйте "auto", щоб випадки без попереднього схвалення перевіряв класифікатор, "ask" — щоб їх перевіряла людина, "allowlist" — для команд, схвалених фіксованими правилами, або "full" — для довіреної локальної роботи.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Прив’язка вузла виконання`},help:{"v1-rfnz54-4s":`Налаштування прив’язки вузла для інструментів виконання, коли виконання команд делегується через підключені вузли. Використовуйте явну прив’язку вузла лише тоді, коли потрібна маршрутизація між кількома вузлами.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Сповіщення про завершення виконання`},help:{"v1-eyedrx-3r":`Якщо true (типово), завершення фонових сеансів exec і події життєвого циклу exec на вузлі додають до черги подальшу обробку для вихідного сеансу.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Сповіщення про успішне виконання без виводу`},help:{"v1-l4v70o-6g":`Якщо встановлено true (типове значення), успішне завершення фонового exec без виводу все одно активує сеанс, з якого його запущено, щоб той повідомив про завершення очікування. Установіть false, щоб успішне завершення без виводу не спричиняло сповіщень; тоді агент збиратиме ці результати за допомогою process poll.`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Додавання на початок PATH для виконання`},help:{"v1-s1aimc-1r":`Каталоги, які додаються на початок PATH для запусків команд (gateway/sandbox).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Перевіряльник виконання`},help:{"v1-12y548k-4x":`Засіб перевірки exec на основі моделі, який використовується в автоматичному режимі перед переходом до схвалення людиною. Укажіть тут окрему модель, якщо хочете ізолювати перевірку exec від основної моделі агента.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Швидкий режим перевірки виконання`},help:{"v1-175bx14-8u":`Необов’язковий швидкий режим для перевірок схвалення в OpenClaw: true запитує пріоритетну обробку на підтримуваних маршрутах OpenAI Responses і ChatGPT/OAuth; false запитує стандартну обробку. Не вказуйте, щоб зберегти типові налаштування постачальника. Швидкий режим може коштувати дорожче та залежить від доступності в постачальника. Не налаштовує вбудований Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Модель засобу перевірки exec`},help:{"v1-1lltiy5-3i":`Необов’язкове перевизначення постачальника/моделі для агента перевірки exec. Залиште незаданим, щоб використовувати налаштовану основну модель цільового агента.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Міркування під час перевірки виконання`},help:{"v1-yg2gby-6u":`Необов’язковий рівень зусиль для міркування під час перевірок схвалення за допомогою моделі в OpenClaw: minimal, low, medium, high, xhigh або max. Не вказуйте, щоб зберегти типові налаштування постачальника. Підтримувані рівні узгоджуються з вибраною моделлю. Не налаштовує вбудований Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Час очікування перевірки exec (мс)`},help:{"v1-1o30chi-3w":`Час очікування для кожного етапу перевірки exec в мілісекундах — підготовки моделі та генерування відповіді — перед переходом до схвалення людиною (типово: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Профілі безпечних виконуваних файлів exec`},help:{"v1-4cdcwe-29":`Необов’язкові профілі безпеки для окремих виконуваних файлів (обмеження позиційних аргументів + дозволені/заборонені прапорці).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Безпечні виконувані файли exec`},help:{"v1-1of1m2s-21":`Дозволити запуск безпечних виконуваних файлів, які отримують дані лише через stdin, без явних записів у списку дозволених.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Довірені каталоги безпечних виконуваних файлів exec`},help:{"v1-zljbcn-2v":`Додаткові явно вказані каталоги, довірені для перевірки шляхів до безпечних виконуваних файлів (каталоги з PATH ніколи не вважаються довіреними автоматично).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Безпека exec`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Вимагати схвалення виконання вбудованого коду`},help:{"v1-jkmgo7-5z":"Вимагати явного схвалення для викликів інтерпретатора з вбудованим кодом, як-от `python -c`, `node -e`, `ruby -e` або `osascript -e`. Запобігає непомітному повторному використанню списку дозволених і для таких викликів замінює постійний дозвіл на запит щоразу."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Час очікування виконання (секунди)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Інструменти файлової системи лише для робочого простору`},help:{"v1-1mhuvka-2s":`Обмежити дію інструментів файлової системи (read/write/edit/apply_patch) каталогом робочого простору (типово: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`Обліковий запис GitHub CLI та автор Git`},help:{"v1-1fl77im-5s":`Керований локальний профіль GitHub CLI та необов’язкові дані автора Git для інструментів агента. Не вказуйте цей об’єкт, щоб зберегти власний обліковий запис і дані автора користувача, від імені якого працює Gateway; облікові дані для доступу до віддалених репозиторіїв ніколи не перевизначаються.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Електронна адреса автора Git`},help:{"v1-kol5g6-1i":`Необов’язкова електронна адреса автора та комітера Git, що діє лише в межах процесу.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Ім’я автора Git`},help:{"v1-z5bl1f-1h":`Необов’язкове ім’я автора та комітера Git, що діє лише в межах процесу.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Тип облікових даних GitHub`},help:{"v1-qi3qun-3q":`Позначає керований профіль OAuth, ротаційними обліковими даними для оновлення якого володіє Gateway. Профілі без цього параметра використовують особистий токен доступу.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`Версія профілю GitHub`},help:{"v1-4lzl0-27":`Згенерована версія профілю без внутрішньої семантики, що використовується для атомарного перемикання керованих облікових даних.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Увімкнути аналіз посилань`},help:{"v1-23t2io-59":`Увімкнути автоматичний попередній аналіз посилань, щоб стислий виклад вмісту за URL-адресами був доступний до початку міркувань агента. Залиште ввімкненим для повнішого контексту або вимкніть, якщо потрібна суворо мінімальна обробка.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Максимальна кількість посилань для аналізу`},help:{"v1-ksxmcv-52":`Максимальна кількість посилань, вміст яких розгортається за один хід під час аналізу посилань. Використовуйте менші значення, щоб контролювати затримку й витрати в активних обговореннях, і більші, коли контекст із кількох посилань є критично важливим.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Моделі для аналізу посилань`},help:{"v1-6j3mnw-5a":`Список бажаних моделей для завдань аналізу посилань. За наявності підтримки моделі використовуються послідовно як резервні варіанти. Для звичайного підсумовування спочатку використовуйте легкі моделі, а потужніші — лише за потреби.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Область застосування аналізу посилань`},help:{"v1-183cwpa-55":`Визначає, коли запускається аналіз посилань залежно від контексту розмови й типу повідомлення. Обмежуйте область застосування, щоб уникати зайвого завантаження вмісту посилань із повідомлень, де вони не потребують обробки.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Час очікування аналізу посилань (с)`},help:{"v1-61v30o-4p":`Граничний час аналізу кожного посилання в секундах, після якого необроблені посилання пропускаються. Обмежуйте цей час, щоб уникати тривалих затримок, коли зовнішні сайти працюють повільно або недоступні.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-108r5c7-h":`Захист від повторних викликів інструментів`},help:{"v1-wrvlew-5k":`Керує захистом від повторних викликів інструментів. Під час третього поспіль однакового виклику інструмента захист додає вказівку змінити підхід, а на двадцятому — завершує хід. Не вказуйте цей параметр або встановіть true, щоб залишити захист увімкненим; встановіть false, щоб вимкнути його.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Політика вкладень для аналізу аудіо`},help:{"v1-1s3t9s5-3o":`Виберіть, які відповідні аудіовкладення обробляти. Обробляйте лише перше вкладення, якщо транскрибування кількох вкладень не є навмисним.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Формат повторного виведення транскрипції`},help:{"v1-glpdzh-3i":`Задайте формат транскрипції для надсилання за допомогою заповнювача {transcript}. Залиште заповнювач незмінним, щоб надіслане повідомлення містило транскрипцію.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Надсилати транскрипцію в чат`},help:{"v1-1dedp8c-3r":`Надсилати транскрипцію аудіо в початковий чат перед обробкою агентом. Увімкніть, якщо користувачам потрібно перевіряти, що почула система.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Увімкнути розуміння аудіо`},help:{"v1-1v0x7te-2m":`Увімкніть розуміння аудіо, щоб транскрибувати голосові нотатки або аудіозаписи для контексту агента.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Мова розуміння аудіо`},help:{"v1-1ruqt97-3z":`Мовна підказка за замовчуванням для постачальників послуг транскрибування аудіо. Задайте її, якщо основна мова мовлення відома, а її автоматичне визначення постачальником ненадійне.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Максимальна кількість байтів для розуміння аудіо`},help:{"v1-1mcckc8-43":`Обмеження розміру вхідного аудіо за замовчуванням для налаштованих і автоматично виявлених моделей. Установіть найбільший розмір запису, який мають приймати ваші постачальники та мережа.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Максимальна кількість символів для розуміння аудіо`},help:{"v1-eo1dp-43":`Максимальна довжина транскрипції за замовчуванням для налаштованих і автоматично виявлених моделей. Використовуйте менше значення, щоб довгі голосові нотатки не збільшували контекст агента.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Пріоритетна модель розуміння аудіо`},help:{"v1-1n5zya1-3c":`Надавати перевагу одному запису tools.media.models із позначкою відповідної можливості для транскрибування аудіо перед рештою сумісних резервних варіантів.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Промпт для розуміння аудіо`},help:{"v1-1v5jtay-4b":`Типовий промпт для транскрибування аудіо, якщо запис моделі не перевизначає його. Зберігайте інструкцію незмінною, якщо подальші робочі процеси залежать від стилю транскрипції.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Область застосування розуміння аудіо`},help:{"v1-1pptfg0-3w":`Обмежуйте розуміння аудіо за каналом, типом чату або ключем джерела. Звужуйте цю область там, де автоматичне транскрибування пов’язане з конфіденційними даними або значними витратами.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Час очікування розуміння аудіо (с)`},help:{"v1-n8wc6c-3b":`Типовий час очікування для запитів на розуміння аудіо. Збільшуйте його для довгих записів або повільніших локальних моделей транскрибування.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Паралельність розуміння медіа`},help:{"v1-13kr9np-58":`Максимальна кількість одночасних операцій розуміння медіа за один хід для всіх завдань із зображеннями, аудіо та відео. Зменшуйте це значення в розгортаннях з обмеженими ресурсами, щоб запобігти перевантаженню процесора чи мережі.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Політика вкладень для розуміння зображень`},help:{"v1-11hofbw-3e":`Виберіть, які вкладення із зображеннями, що відповідають умовам, оброблятимуться. Обробляйте лише перше, якщо аналіз кількох зображень не є навмисним.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Увімкнути розуміння зображень`},help:{"v1-1b2zw34-50":`Увімкніть розуміння зображень, щоб вкладені зображення або зображення за посиланнями можна було інтерпретувати як текстовий контекст. Вимкніть, якщо потрібна робота лише з текстом або ви хочете уникнути витрат на обробку зображень.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Максимальна кількість байтів для розуміння зображень`},help:{"v1-jwwpd1-3v":`Типове обмеження розміру вхідного зображення для налаштованих і автоматично виявлених моделей. Установіть значення відповідно до обмежень провайдера на розмір запитів і пропускної здатності мережі розгортання.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Максимальна кількість символів для розуміння зображень`},help:{"v1-ebnxhk-3q":`Типова максимальна довжина опису зображення. Використовуйте менше значення для стислого контексту або більше — для детального оптичного розпізнавання тексту й аналізу сцени.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Пріоритетна модель розуміння зображень`},help:{"v1-1o2uwo6-3c":`Надайте одному запису tools.media.models із позначкою відповідної можливості пріоритет для розуміння зображень перед рештою сумісних резервних варіантів.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Промпт для розуміння зображень`},help:{"v1-3a7piy-3p":`Типовий промпт для розуміння зображень, якщо запис не перевизначає його. Використовуйте фіксований промпт, якщо споживачі покладаються на стабільні описи.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Область застосування розуміння зображень`},help:{"v1-tievo1-3s":`Обмежте розуміння зображень за каналом, типом чату або ключем джерела. Звужуйте цю область у завантажених або ненадійних каналах, щоб контролювати обробку.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Час очікування розуміння зображень (с)`},help:{"v1-1wcm84x-31":`Час очікування за замовчуванням для запитів на аналіз зображень. Збільште його для великих зображень або повільніших локальних моделей комп’ютерного зору.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Спільні моделі аналізу медіа`},help:{"v1-1bbsp4f-3x":`Список моделей для розуміння медіа. Додавайте до кожного запису теги можливостей image, audio або video, щоб кожен конвеєр вибирав лише сумісні резервні варіанти.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Політика вкладень для аналізу відео`},help:{"v1-1qm1qrc-3e":`Виберіть, які відповідні відеовкладення обробляти. Обробляйте лише перше вкладення, якщо аналіз кількох відео не є вашою метою.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Увімкнути аналіз відео`},help:{"v1-1ltx5gl-58":`Увімкніть аналіз відео, щоб створювати текстові підсумки відеокліпів для подальших міркувань і відповідей. Вимкніть, якщо обробка відео суперечить політиці або є надто дорогою для вашого розгортання.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Максимальна кількість байтів для аналізу відео`},help:{"v1-2mp77v-3v":`Обмеження розміру вхідного відео за замовчуванням для налаштованих і автоматично виявлених моделей. Установіть значення відповідно до обмежень провайдера на обсяг даних і пропускної здатності мережі вашого розгортання.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Максимальна кількість символів для аналізу відео`},help:{"v1-1j0x40b-3j":`Максимальна довжина опису відео за замовчуванням. Використовуйте менше значення для стислого контексту або більше — для докладних підсумків сцен.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Пріоритетна модель аналізу відео`},help:{"v1-1cygq5k-3c":`Надавати перевагу одному запису tools.media.models із позначкою відповідної можливості для розуміння відео перед рештою сумісних резервних варіантів.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Промпт для розуміння відео`},help:{"v1-692dhv-3m":`Типовий промпт для розуміння відео, якщо запис не перевизначає його. Використовуйте фіксований промпт, якщо споживачі покладаються на стабільні підсумки.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Область застосування розуміння відео`},help:{"v1-7gfrx3-3s":`Обмежуйте розуміння відео за каналом, типом чату або ключем джерела. У завантажених або ненадійних каналах звужуйте цю область, щоб контролювати обробку.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Час очікування розуміння відео (с)`},help:{"v1-e8rzsy-33":`Типовий час очікування для запитів на розуміння відео. Збільшуйте його для довших роликів або повільніших локальних моделей аналізу.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Список дозволених дій із повідомленнями`},help:{"v1-1iceqwa-5c":`Глобальний список дозволених дій із повідомленнями для інструмента message. Використовуйте лише тоді, коли все середовище виконання має надавати й приймати скорочений набір дій; для публічних або ізольованих агентів віддавайте перевагу окремим спискам дозволених дій для кожного агента.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Увімкнути розсилку повідомлень`},help:{"v1-1ms74z7-14":`Увімкнути дію розсилки (типове значення: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Дозволити взаємодію між контекстами (між провайдерами)`},help:{"v1-276qxo-2s":`Дозволити надсилання між різними провайдерами (типово: true). Установіть false, щоб заблокувати обмін повідомленнями між провайдерами.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Дозволити надсилання між контекстами (той самий провайдер)`},help:{"v1-1sg4x49-1z":`Дозволити надсилання в інші канали в межах того самого провайдера (за замовчуванням: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Позначка надсилання між контекстами`},help:{"v1-1fg6jrp-1z":`Додавати видиму позначку джерела під час надсилання між контекстами (за замовчуванням: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Префікс позначки надсилання між контекстами`},help:{"v1-eblsru-1p":`Текстовий префікс для позначок надсилання між контекстами (підтримує "{channel}").`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Суфікс позначки надсилання між контекстами`},help:{"v1-1nk0jub-1p":`Текстовий суфікс для позначок надсилання між контекстами (підтримує "{channel}").`}},"tools%2Eopenclaw":{label:{"v1-m2tz7g-j":`Делегування OpenClaw`},help:{"v1-4bdi5v-26":`Політика схвалення постійних змін, делегованих системному агенту OpenClaw.`}},"tools%2Eopenclaw%2EautoApproveChanges":{label:{"v1-1arx74u-u":`Автоматичне схвалення делегованих змін`},help:{"v1-1gy96r5-br":`Постійний дозвіл на дозволене делеговане адміністрування, зокрема на налаштування, які можуть виконувати код на хості Gateway. Значення true дозволяє зміни без окремого схвалення, навіть коли інструменти прямого виконання заборонено; значення false завжди вимагає схвалення. Якщо значення не задано, використовується явно наданий Full Access або незалежно підтверджений дозвіл на необмежене виконання на Gateway. Обмеження файлової системи, пісочниці, операцій і поточного запуску залишаються чинними.`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Профіль інструментів`},help:{"v1-h6k98q-5k":`Назва глобального профілю інструментів для вибору попередньо визначеної базової політики інструментів перед застосуванням перевизначень дозволів і заборон. Використовуйте це налаштування для узгодженої конфігурації середовища всіх агентів і зберігайте назви профілів незмінними.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Політика інструментів пісочниці`},help:{"v1-ea7awo-4k":`Обгортка політики інструментів для запусків агентів у пісочниці, що дає змогу встановлювати для них окремі межі можливостей. Використовуйте це налаштування для посилення безпеки в контекстах пісочниці.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Політика дозволів і заборон інструментів пісочниці`},help:{"v1-ub701o-4t":`Політика дозволів і заборон інструментів, що застосовується під час запуску агентів в ізольованих середовищах виконання. Обмежуйте дозволи в політиках до мінімуму, щоб завдання в пісочниці не могли призводити до зайвих зовнішніх дій.`}},"tools%2Esessions%2EallowThreadTargets":{label:{"v1-1o1dl7e-p":`Дозволити надсилання в гілки`},help:{"v1-1ppcmoz-6v":`Дозволити sessions_send спрямовувати повідомлення в сеанси чату, прив’язані до гілок або тем, як-от теми форуму Telegram чи гілки Slack/Discord (типове значення: false). Цільовий агент працює в цьому сеансі; усе, що він надсилає за допомогою інструмента message, потрапляє в гілку, видиму користувачам.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Видимість сеансів для інструментів`},help:{"v1-1p13n9k-fm":`Визначає, до яких сеансів можна звертатися через sessions_list/sessions_history/sessions_search/sessions_send/session_status. ("all" за замовчуванням = будь-який сеанс на Gateway, включно із сеансами інших агентів і користувачів; "agent" = будь-який сеанс із поточним ідентифікатором агента; "self" = лише поточний; "tree" = поточний сеанс + сеанси створених субагентів). Міжагентний доступ увімкнено за замовчуванням, а його межі визначає tools.agentToAgent; використовуйте вужчу видимість, щоб обмежити читання та звичайне надсилання. Явно вказані адресати в agents.entries.<id>.tools.agentToAgent.send можуть дозволяти надсилання без розширення доступу до читання.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Політика інструментів субагентів`},help:{"v1-1xoug01-4z":`Обгортка політики інструментів для створених субагентів, що обмежує або розширює доступність інструментів порівняно зі стандартними налаштуваннями батьківського агента. Використовуйте її, щоб можливості делегованих агентів відповідали меті завдання.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Політика дозволів і заборон інструментів субагентів`},help:{"v1-7vxsbf-5d":`Політика дозволів і заборон інструментів, що застосовується до середовищ виконання створених субагентів. Надавайте їм вужчий доступ, ніж батьківському агенту. Інструменти батьківського агента, як-от progress_card, завжди заборонені, зокрема й через allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Рій`},help:{"v1-1q96vvs-45":`Оркестрація субагентів у режимі збирача. Увімкнено за замовчуванням; установіть false, щоб вимкнути. Дозволи інструментів і надалі застосовуються до agents_wait та параметрів створення рою.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Типовий агент рою`},help:{"v1-p4alpg-2m":`Типовий цільовий агент для створення агентів рою без зазначеного agentId. Список дозволених субагентів і надалі застосовується.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Увімкнути рій`},help:{"v1-1nnnrq9-2e":`Вмикає субагентів у режимі збирача та agents_wait. Увімкнено за замовчуванням; установіть false, щоб вимкнути.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Активні дочірні агенти на групу рою`},help:{"v1-kfx6qp-1c":`Максимальна кількість активних дочірніх агентів-збирачів на групу рою.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1a16wrf-z":`Кількість одночасних дочірніх агентів на групу рою`},help:{"v1-1ednj37-70":`Максимальна кількість активних дочірніх агентів-збирачів в окремій смузі виконання кожної групи рою (за замовчуванням: 32), незалежно від кількості одночасно активних звичайних субагентів. Кожен активний дочірній агент використовує один потік моделі та одне ізольоване середовище робочого процесу Code Mode. Обмеження допуску до групи залишаються чинними.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Загальна кількість дочірніх агентів на групу рою`},help:{"v1-1gc9vl1-1e":`Максимальна кількість створень агентів-збирачів за весь час існування групи рою.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Максимальний час очікування рою`},help:{"v1-bog18y-1g":`Максимальний час очікування, який приймає agents_wait, у секундах.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Пошук інструментів`},help:{"v1-g2rpl8-80":`Стискайте великі каталоги інструментів OpenClaw, MCP і клієнтів. Якщо значення не задано, середовища виконання OpenClaw автоматично використовують структурований Tool Search; увімкнений Code Mode має пріоритет, а Codex використовує власний пошук. Установіть false, щоб вимкнути цю функцію, true — для структурованого пошуку, або скористайтеся об’єктною формою, щоб вибрати режим.`}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Увімкнути пошук інструментів`},help:{"v1-1naa8jz-3v":`Увімкнення Tool Search. Коли цю функцію ввімкнено, OpenClaw приховує великі каталоги інструментів за структурованими інструментами пошуку, опису й виклику під час запусків у вбудованому середовищі виконання.`}},"tools%2EtoolSearch%2Eexclude":{label:{"v1-1040rv9-t":`Селектори виключення з пошуку інструментів`},help:{"v1-pmx6vl-60":`Інструменти, які залишаються безпосередньо видимими замість додавання до каталогу. Використовує ті самі селектори, що й include; виключення має пріоритет. Якщо параметр не задано або має значення [], нічого не виключається. Не надає дозволів і не змінює правил для інструментів, доступних лише напряму або обов’язкових під час виконання.`}},"tools%2EtoolSearch%2Eexclude%5B%5D%2Ename":{label:{"v1-7sh15i-i":`Назва виключеного інструмента`},help:{"v1-ke0ysb-4v":`Зареєстрована назва інструмента або шаблон із *, що визначає інструменти, які залишаються доступними напряму, з нормалізацією за політикою інструментів. Селектори лише за назвою шукають збіги в усіх джерелах; уточніть джерело, щоб уникнути небажаних збігів.`}},"tools%2EtoolSearch%2Eexclude%5B%5D%2Esource":{label:{"v1-1u3p208-k":`Джерело виключеного інструмента`},help:{"v1-1r3h9ad-2x":`Джерело, яке слід виключити з каталогу: "openclaw", "mcp" або "client". Якщо також задано name, обидві умови поєднуються логічним І.`}},"tools%2EtoolSearch%2Einclude":{label:{"v1-130v30b-t":`Селектори включення до пошуку інструментів`},help:{"v1-1567ter-7t":`Селектори відображення для інструментів, які дозволені політикою та можуть бути додані до каталогу. Якщо параметр не задано, вибираються всі придатні інструменти; [] не вибирає жодного. Поля в межах селектора поєднуються логічним І, а селектори — логічним АБО. Невибрані інструменти залишаються доступними для прямого виклику. Не впливає на незалежний Code Mode або вбудований пошук Codex.`}},"tools%2EtoolSearch%2Einclude%5B%5D%2Ename":{label:{"v1-ewc3qk-i":`Назва включеного інструмента`},help:{"v1-8gy1xg-4o":`Зареєстрована назва інструмента або шаблон із *, з нормалізацією за політикою інструментів (включно з псевдонімами). Селектори лише за назвою шукають збіги в усіх джерелах. Регулярні вирази та розгортання груп інструментів не підтримуються.`}},"tools%2EtoolSearch%2Einclude%5B%5D%2Esource":{label:{"v1-31fgve-k":`Джерело включеного інструмента`},help:{"v1-19ewj5n-52":`Походження інструмента: "openclaw" для основних плагінів і плагінів, що не належать до MCP, "mcp" для зареєстрованих інструментів MCP або "client" для інструментів, наданих клієнтом. Уточнюйте назви за допомогою джерела, щоб уникнути збігів зі схожими назвами.`}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Максимальна кількість результатів пошуку інструментів`},help:{"v1-7du4kh-32":`Максимальна кількість результатів пошуку інструментів, яку може запитати модель. Під час виконання значення обмежуються підтримуваним діапазоном 1..50.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Інтерфейс пошуку інструментів`},help:{"v1-1uvcg7i-6z":`Виберіть інтерфейс для моделі: "tools" (за замовчуванням) надає структуровані інструменти пошуку, опису й виклику; "directory" залишає видимим обмежений каталог інструментів, надає обмежений набір імовірно потрібних або обов’язкових схем, а доступ до решти відкладає до використання інструментів пошуку, опису й виклику.`}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Кількість результатів пошуку інструментів за замовчуванням`},help:{"v1-1uchq7t-39":"Кількість результатів пошуку інструментів, що повертаються за замовчуванням, якщо модель не вказує обмеження. Під час виконання це значення обмежується `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Увімкнути інструмент структурованого планування`},help:{"v1-1xgegme-4o":"Єдиний інструмент стану `progress_card` для збережених планів і описових нотаток у батьківських сеансах. Увімкнено за замовчуванням; установіть false, щоб вимкнути. Завжди недоступний субагентам."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Вебінструменти`},help:{"v1-fpsy5-4y":`Група налаштувань політики вебінструментів для налаштування постачальників пошуку й отримання даних, обмежень і резервної поведінки. Узгоджуйте ввімкнені налаштування з наявністю ключів API та політикою вихідних мережевих з’єднань.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`TTL кешу отримання вебданих (хв)`},help:{"v1-1hk89qp-17":`TTL кешу в хвилинах для результатів web_fetch.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Увімкнути інструмент отримання вебданих`},help:{"v1-yrswld-1f":`Увімкнути інструмент web_fetch (спрощене отримання даних через HTTP).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Заголовки запитів отримання вебвмісту`},help:{"v1-16bjkv5-me":"Додаткові заголовки, що надсилаються з прямими запитами web_fetch, наприклад заголовки маршрутизації шлюзу або автентифікації. Кожне налаштоване значення вважається конфіденційним і приховується в доступній для перегляду конфігурації та записах налагодження. Значення є звичайними рядками, підтримують підстановку ${VAR} і глобальне екранування $${VAR} для буквального значення та надсилаються на URL-адреси, вибрані моделлю. Записи перевіряються під час формування запиту, а не під час завантаження конфігурації, тому заголовок із некоректною назвою або значенням, яке неможливо надіслати, відкидається з відповідним записом у журналі замість вимкнення функції; Accept, Accept-Language, User-Agent і заголовки обрамлення, як-от Transfer-Encoding, також відкидаються. Щоб змінити агент користувача, використовуйте tools.web.fetch.userAgent. У разі перенаправлення на інше джерело зберігаються лише заголовки зі списку безпечних дозволених заголовків guarded-fetch, а зміна фактично надісланих заголовків розділяє кеш отримання."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Максимальна кількість символів отриманого вебвмісту`},help:{"v1-12d1fw7-1d":`Максимальна кількість символів, які повертає web_fetch (решта обрізається).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Жорстке обмеження кількості символів отриманого вебвмісту`},help:{"v1-cl2mf1-1v":`Жорстке обмеження maxChars для web_fetch (застосовується до конфігурації та викликів інструмента).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Максимальна кількість перенаправлень під час отримання вебвмісту`},help:{"v1-t6eak9-1h":`Максимальна кількість перенаправлень, дозволених для web_fetch (за замовчуванням: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Максимальний розмір завантаження вебвмісту (байти)`},help:{"v1-q6ld9c-10":`Максимальний розмір завантаження до обрізання.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Постачальник отримання вебвмісту`},help:{"v1-6pb3nv-v":`Ідентифікатор резервного постачальника для отримання вебвмісту.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Видобування вебвмісту за допомогою Readability`},help:{"v1-19exqzx-2c":`Використовувати Readability для видобування основного вмісту з HTML (резервний варіант — базове очищення HTML).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`Політика SSRF для отримання вебвмісту`},help:{"v1-qtn7zx-3c":`Вибіркові перевизначення політики SSRF для web_fetch. Обмежуйте їхню дію та вмикайте лише для відомих проксі-середовищ у локальній мережі.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Дозволені імена хостів для отримання вебвмісту`},help:{"v1-1j9ctya-35":`Точні імена хостів або літеральні IP-адреси, дозволені для web_fetch, зокрема адреси, які інакше були б заблоковані. Зберігайте список мінімальним.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Дозволити діапазон унікальних локальних IPv6-адрес для отримання вебвмісту`},help:{"v1-1eyz55i-3b":`Дозволити унікальні локальні IPv6-адреси (fc00::/7) для сумісності з довіреними проксі, що використовують fake-IP, як-от sing-box, Clash або Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Дозволити діапазон тестування продуктивності RFC 2544 для отримання вебвмісту`},help:{"v1-u5asdb-2y":`Дозволити IP-адреси з діапазону тестування продуктивності RFC 2544 (198.18.0.0/15) для сумісності з проксі, що використовують fake-IP, як-от Clash або Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Заблоковані імена хостів для отримання вебвмісту`},help:{"v1-1164vvk-66":`Шаблони імен хостів, які блокуються перед перевіркою DNS і правил дозволу під час кожного переспрямування web_fetch. Підтримуються точні імена хостів і "*.example.com" лише для піддоменів; додайте "example.com" окремо, щоб заблокувати кореневий домен. Порожнє або невстановлене значення не додає заборон.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Небезпечний дозвіл доступу до приватної мережі для отримання вебвмісту`},help:{"v1-2s6mv7-3t":`Дозволяє web_fetch доступ до ресурсів приватних і внутрішніх мереж. Залишайте вимкненим, якщо вибрані моделлю URL-адреси не є довіреними в цьому розгортанні.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Час очікування отримання вебвмісту (с)`},help:{"v1-1c3yfr4-16":`Час очікування запитів web_fetch у секундах.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`User-Agent для отримання вебвмісту`},help:{"v1-s7pe8j-1e":`Перевизначає заголовок User-Agent для запитів web_fetch.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Довірений проксі зі змінних середовища для отримання вебвмісту`},help:{"v1-1ypkqj7-54":`Спрямовує web_fetch через довірений HTTP(S)-проксі, заданий у змінних середовища, і доручає проксі виконувати визначення адрес через DNS. Увімкніть, лише якщо цей проксі контролюється оператором і застосовує політику вихідного трафіку після визначення адрес через DNS.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`TTL кешу вебпошуку (хв)`},help:{"v1-6trzlf-18":`TTL кешу результатів web_search у хвилинах.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Увімкнути інструмент вебпошуку`},help:{"v1-n1cm4y-27":`Увімкнути керований web_search і необов’язковий вбудований пошук Codex для сумісних моделей.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Максимальна кількість результатів вебпошуку`},help:{"v1-mrw7mi-z":`Кількість результатів для повернення (1–10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Дозволені домени Codex`},help:{"v1-1cv4y44-43":`Список дозволених доменів для вбудованого web_search у Codex. Під час ходів із вбудованим пошуком він також обмежує керований web_fetch; ходи з керованим провайдером залишаються без змін.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Розмір контексту пошуку Codex`},help:{"v1-antack-1u":`Рекомендований розмір контексту вбудованого пошуку Codex: "low", "medium" або "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Увімкнути вбудований вебпошук Codex`},help:{"v1-ek2jzd-1k":`Увімкнути вбудований вебпошук Codex для моделей із підтримкою Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Режим вебпошуку Codex`},help:{"v1-1ahyq9f-32":`Бажаний режим вбудованого вебпошуку Codex: "cached" (за замовчуванням; під час ходів Codex без обмежень застосовується live) або "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Місто користувача Codex`},help:{"v1-1y95orp-1d":`Приблизне місто перебування, що передається вбудованому вебпошуку Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Країна користувача Codex`},help:{"v1-1xkm5ms-1g":`Приблизна країна перебування, що передається вбудованому вебпошуку Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Регіон користувача Codex`},help:{"v1-lhar02-1l":`Приблизний регіон або штат, що передається до вбудованого вебпошуку Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Часовий пояс користувача Codex`},help:{"v1-fgv9fh-1h":`Приблизний часовий пояс, що передається до вбудованого вебпошуку Codex.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Постачальник вебпошуку`},help:{"v1-10omglr-1x":`Ідентифікатор постачальника пошуку. Якщо не вказано, визначається автоматично за доступними ключами API.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Час очікування вебпошуку (с)`},help:{"v1-i0egvw-17":`Час очікування запитів web_search у секундах.`}},transcripts:{label:{"v1-1iqk6o8-b":`Стенограми`},help:{"v1-1i0sc09-66":`Основні налаштування запису стенограм для нотаток зустрічей, інструментів агента з можливістю запису та налаштованих джерел автоматичного запуску для зустрічей у реальному часі. Плагіни зустрічей за замовчуванням зберігають нотатки для тривалого використання; установіть enabled на false, щоб вимкнути це для всіх джерел.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Джерела автоматичного запуску стенограм`},help:{"v1-1mzsl79-5s":`Джерела стенограм у реальному часі, якими система керує автоматично від моменту запуску Gateway. Наявність запису вмикає відповідне джерело; видаліть запис, щоб вимкнути його. Джерела ведуть безперервний запис, якщо whenOccupied не ввімкнено.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`Ідентифікатор облікового запису стенограм`},help:{"v1-6g2kjj-4b":`Необов’язковий ідентифікатор облікового запису постачальника або робочого простору для джерел стенограм, яким потрібне однозначне визначення облікового запису. Використовуйте формат ідентифікатора облікового запису, зазначений у документації постачальника.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`Ідентифікатор каналу стенограм`},help:{"v1-1lk9d5o-4u":`Ідентифікатор каналу постачальника для джерела транскрипції в реальному часі, наприклад голосового каналу Discord або каналу зустрічей Slack. Перш ніж увімкнути автоматичний запуск, перевірте особливості використання ідентифікаторів у конкретного постачальника.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`Ідентифікатор сервера Discord`},help:{"v1-fyfgnk-4l":`Необов’язковий ідентифікатор сервера Discord для джерел транскрипції голосових каналів Discord. Укажіть його разом із відповідним channelId, якщо постачальнику потрібно шукати голосовий канал у межах сервера.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`URL зустрічі для транскрипції`},help:{"v1-1xtt9ci-4f":`Необов’язковий URL зустрічі для постачальників, які приєднуються за URL, а не за ідентифікатором каналу. Використовуйте лише надійні посилання на зустрічі, оскільки автоматичний запуск може призвести до приєднання до зустрічі та її запису.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`Ідентифікатор постачальника джерела транскрипції`},help:{"v1-1uur06p-3s":`Ідентифікатор постачальника джерела транскрипції, наприклад постачальника голосових каналів Discord або майбутнього постачальника зустрічей Slack. Використовуйте точний ідентифікатор, наданий плагіном постачальника.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`Ідентифікатор сеансу транскрипції`},help:{"v1-xyo4x5-5o":`Необов’язковий фіксований ідентифікатор сеансу транскрипції для цього джерела автоматичного запуску. Ігнорується, коли whenOccupied має значення true. Залиште незаданим, щоб ідентифікатори генерувалися автоматично, якщо вам не потрібен стабільний щоденний селектор і ви не можете уникнути конфліктів у межах одного дня.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Назва транскрипції`},help:{"v1-ycjnmp-5y":`Необов’язкова назва для майбутніх записів транскрипцій. Зміна лише назв не перериває поточні записи й не змінює їхні початкові назви або збережені нотатки. Інші зміни джерел обробляються за звичайними правилами перезапуску.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Запис транскрипції за наявності людей`},help:{"v1-34jid4-78":`Починати новий сеанс транскрипції щоразу, коли в джерелі присутні люди, і зупиняти його (зі створенням нотаток), коли остання людина виходить. Потрібен провайдер, який повідомляє про присутність людей, наприклад discord-voice. Типове значення: false (безперервний запис від запуску Gateway).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Транскрипції ввімкнено`},help:{"v1-fyqqr0-6d":`Увімкнення автоматичних нотаток зустрічей із постійним зберіганням, інструмента транскрипцій для агента та налаштованих джерел автоматичного запуску. Типове значення: true. Установіть false, щоб вимкнути постійне зберігання та інструмент; явно вибраний режим транскрибування зустрічі й далі зберігатиме обмежений останній фрагмент транскрипції в реальному часі.`}},tts:{label:{"v1-bmxkk9-e":`Синтез мовлення`},help:{"v1-1o27tk2-4n":`Політика синтезу мовлення для читання відповідей агента вголос у підтримуваних голосових або аудіоінтерфейсах. Залишайте вимкненою, якщо голосове відтворення не є частиною робочого процесу оператора чи користувача.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`Голосовий образ TTS`},help:{"v1-1r0opcb-29":`Ідентифікатор типового голосового образу TTS. Локальні налаштування голосового образу TTS можуть перевизначати його для кожного хоста.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`Голосові образи TTS`},help:{"v1-19aybhl-2l":`Іменовані голосові образи TTS, що визначають сталу голосову ідентичність і прив’язки мовлення для конкретних провайдерів.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`Голосовий образ TTS`},help:{"v1-10s52ah-2l":`Один голосовий образ TTS. Використовуйте прив’язки для конкретних провайдерів, щоб точно задавати голоси, моделі та шаблони промптів.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Прив’язки профілю TTS до провайдерів`},help:{"v1-993jop-3e":`Прив’язки профілю TTS для окремих провайдерів, де ключами є ідентифікатори провайдерів мовлення. Для активного профілю вони об’єднуються з tts.providers, перевизначаючи відповідні значення.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`Налаштування провайдерів TTS`},help:{"v1-1k80nl4-4y":`Налаштування TTS для окремих провайдерів, де ключами є ідентифікатори провайдерів мовлення. Використовуйте їх замість вбудованих ключів верхнього рівня для окремих провайдерів, щоб плагіни мовлення залишалися незалежними від основної схеми конфігурації.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`Конфігурація провайдера TTS`},help:{"v1-dwapva-3d":`Конфігурація TTS для одного ідентифікатора провайдера мовлення. Обмежуйте поля областю дії плагіна, якому належить цей провайдер.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`Ключ API провайдера TTS`},help:{"v1-1m2fj0i-2o":`Ключ API, який використовує цей провайдер мовлення, коли його плагін вимагає автентифікації для доступу до TTS.`}},tui:{label:{"v1-c8hus1-b":`Термінальний інтерфейс`},help:{"v1-1fg9vw2-3s":`Налаштування відображення термінального інтерфейсу. Використовуйте цей розділ для налаштування вигляду лише в терміналі, не змінюючи поведінку Gateway чи інших інтерфейсів.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Нижня панель термінального інтерфейсу`},help:{"v1-6e12l3-3k":`Налаштування відображення нижньої панелі термінального інтерфейсу. Подавайте додатковий контекст стисло, щоб інформація про сеанс, модель, мету й токени залишалася читабельною.`}},ui:{label:{"v1-ye4dff-2":`Інтерфейс`},help:{"v1-dt1924-42":`Налаштування вигляду інтерфейсу для акцентів і параметрів відображення оператора. Використовуйте їх для покращення читабельності, не змінюючи поведінку під час виконання.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Акцентний колір користувача`},help:{"v1-mpxaka-4y":`Акцентний колір вебзастосунку: #RRGGBB для власного кольору або 'theme' для палітри вибраної теми. Перевизначає ui.seamColor; очистьте значення, щоб успадкувати налаштований акцентний колір або типовий колір теми.`}},"ui%2Eprefs%2Elocale":{label:{"v1-sk0cbe-i":`Мова інтерфейсу`},help:{"v1-6mqtbz-6x":`Мова вебзастосунку у вигляді підтримуваного ідентифікатора локалі, наприклад en, de або zh-CN. Залиште незаданим, щоб використовувати мову браузера або системи. Налаштовується в меню Налаштування → Вигляд → Мова. Не задає часовий пояс асистента (agents.defaults.userTimezone).`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Акцентний колір`},help:{"v1-14q3r4h-4g":`Основний акцентний колір елементів інтерфейсу для виділення, значків і візуальної ідентифікації. Використовуйте висококонтрастні значення, які забезпечують читабельність у світлих і темних темах.`}},update:{label:{"v1-k12u1x-7":`Оновлення`},help:{"v1-11c5k8v-5c":`Канал оновлень і поведінка перевірки під час запуску для підтримання актуальності версій середовища виконання OpenClaw. У робочих середовищах використовуйте консервативні канали, а більш експериментальні — лише в контрольованих середовищах.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Автоматичне оновлення ввімкнено`},help:{"v1-49xs2h-3c":`Увімкнути фонове автоматичне оновлення для встановлень із пакетів stable і beta; оновлення extended-stable ніколи не застосовуються автоматично (типово: false).`}},"update%2Eauto%2Eschedule":{label:{"v1-1t6cr06-p":`Розклад автоматичних оновлень`},help:{"v1-zuf1kc-5y":`Необов’язковий вираз cron для запуску кампаній автоматичного оновлення Gateway у часовому поясі хоста Gateway. Не вказуйте його, щоб зберегти поточний щогодинний розклад. Затримки розгортання та зворотний відлік під час бездіяльності діють і надалі; пропущені часові вікна не надолужуються.`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Канал оновлень`},help:{"v1-lqtdvf-5b":`Канал оновлень для встановлень через git + npm ("stable", "extended-stable", "beta" або "dev"). Канал extended-stable доступний лише для пакетів: установлення виконується лише на передньому плані, з необов’язковими інформаційними підказками під час запуску, які не вносять змін.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Перевірка оновлень під час запуску`},help:{"v1-qy3q9g-5v":`Перевіряє наявність оновлень під час запуску Gateway, зокрема показує підказки extended-stable лише для ознайомлення (за замовчуванням: true). Установіть false, щоб вимкнути автоматичну перевірку й застосування оновлень Gateway та вузлів без графічного інтерфейсу, а також анонімні запити перевірки оновлень.`}},voicewake:{label:{"v1-txt1wb-a":`Голосова активація`}},web:{label:{"v1-1ae9z56-b":`Вебканал`}},wizard:{label:{"v1-28jonk-h":`Параметри налаштування`},help:{"v1-14jh6rm-3b":`Параметри налаштування, що належать користувачеві. Історія майстра та стан підтверджень, що належать машині, зберігаються в спільній базі даних стану.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Доступ до виявлення під час налаштування`},help:{"v1-1nqxt0w-38":`Згода на виявлення під час покрокового налаштування: "full" виконує сканування без запитів, а "guarded" запитує дозвіл перед перевіркою локальних застосунків.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Рекомендації застосунків під час налаштування`},help:{"v1-ub8uoi-30":`Визначає, чи може покрокове налаштування використовувати назви встановлених застосунків для рекомендації відповідних плагінів і навичок.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Часова позначка останнього запуску майстра`},help:{"v1-1y0fbk-1k":`Часова позначка останнього запуску майстра, результати якого було успішно збережено.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Команда останнього запуску майстра`},help:{"v1-x2pfkk-15":`Команда, якою було востаннє запущено майстер.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Коміт останнього запуску майстра`},help:{"v1-h0jkmt-1i":`Коміт вихідного коду, використаний під час останнього запуску майстра у версії для розробки.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Режим останнього запуску майстра`},help:{"v1-16508qy-1r":`Вказує, чи останній запуск майстра був призначений для налаштування "local" або "remote".`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Версія останнього запуску майстра`},help:{"v1-1tr4z9d-19":`Версія OpenClaw, використана під час останнього запуску майстра.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Часова позначка підтвердження ознайомлення з безпекою в майстрі`},help:{"v1-86i182-2a":`Часова позначка підтвердження ознайомлення з безпекою під час налаштування, збережена разом із цільовою конфігурацією.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Прискорення робочих дерев`},help:{"v1-9es3gc-4r":`Використовувати прискорення файлової системи для нових керованих робочих дерев, якщо воно підтримується (типове значення: true). Установіть false, щоб використовувати звичайне отримання файлів через Git checkout і копіювання файлів. Застосовується лише до нових робочих дерев.`}},worktreeMaxCount:{label:{"v1-1gj5fhm-p":`Максимальна кількість керованих робочих дерев`},help:{"v1-6z5l36-7q":`Максимальна кількість наявних керованих робочих дерев для всіх агентів і репозиторіїв (типово: 4096). Спочатку видаляються робочі дерева гілок, об’єднаних звичайним способом або зі згортанням комітів, а потім — робочі дерева, що найдовше не використовувалися, включно з незбереженими даними. Поточні запуски захищено; збільште це значення, якщо вони вичерпують ліміт. Перевірка вільного місця на диску перед створенням і надалі застосовується.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Кореневий каталог робочих дерев`},help:{"v1-1tgti9j-5d":`Глобальний каталог для нових керованих робочих дерев. Використовуйте абсолютний шлях або ~ для домашнього каталогу; типове значення — <state-dir>/worktrees. У разі зміни цього значення наявні робочі дерева зберігають свої записані шляхи.`}}}}})))()}export{n,i as t};